/* ÇEVİRİ es · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("es","olay",{
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Establecimiento del gobierno del vladika en Montenegro — separación de hecho de Cetinje", "a924b778"], "d": ["En los años en que la Guerra de la Liga Santa relajaba el control otomano en los Balcanes, la metropolía al frente del monasterio de Cetinje se convirtió en un cargo que pasaba de padre a hijo en la familia Petrović, y la región obtuvo de hecho una administración separada. Gracias a lo inaccesible de las montañas, este vladikato subsistió durante dos siglos en una posición ni plenamente independiente ni plenamente dependiente; su independencia jurídica solo sería reconocida por el Tratado de Berlín de 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Recuperación de Corinto", "26f53e3a"], "d": ["La primera gran parada de la campaña de Morea de Damad Ali Pachá fue Corinto; los otomanos recuperaron la ciudad a los venecianos en junio de 1715 y avanzaron desde allí hacia el resto de la península.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Ofensiva de Nader: pérdida de Tabriz, Najicheván, Hamadán, Kermanshah, Maragheh y Qasr-i Shirin", "d95efd59"], "d": ["Las ciudades del oeste de Irán tomadas entre 1723 y 1727 aprovechando el hundimiento del Estado safávida se perdieron una a una por la ofensiva de Nader Jan, que se había hecho con el poder efectivo en Irán. También Ardabil y Jalhal, en Azerbaiyán, pasaron a manos de Nader. La pérdida de Hamadán, Kermanshah y Qasr-i Shirin tuvo un fuerte eco en Estambul; que el ejército no saliera en campaña y esperara en Üsküdar, y que se intentara encubrir la pérdida, fue una de las causas directas de la rebelión de Patrona Halil, estallada seis semanas después.", "3affcf18"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Desastre de Baghavard (Arpaçay) — pérdida del Cáucaso ante Nader Jan", "4262f54c"], "d": ["Las provincias del Cáucaso tomadas en 1723-1725 aprovechando el hundimiento del Estado safávida pudieron conservarse diez años. Nader Jan, que se había hecho con el poder efectivo en Irán, infligió una grave derrota al ejército otomano en Baghavard, cerca de Revan; el serdar Abdullah Köprülü Pachá murió en el campo de batalla. Tras el desastre, Revan, Tiflis, Gence y Shirván fueron evacuadas en pocos meses. La frontera oriental volvió a la línea de Qasr-i Shirin de 1639, que sería confirmada en 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Pérdida de Bender ante los rusos", "0daca453"], "d": ["Tras el desastre de Kagul, el ejército otomano se había replegado al sur del Danubio y las fortalezas entre Moldavia y Özi habían quedado solas. Bender, que guardaba el vado del río Dniéster, fue tomada al asalto tras un asedio de dos meses; la ciudad fue saqueada. La pérdida de la fortaleza rompió el eslabón central de la línea defensiva del norte del mar Negro, y tras ella cayeron también Akkirman y Kili. En Küçük Kaynarca Bender sería devuelta, pero se perdería de nuevo en 1806.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["El emirato de los Sabah en Kuwait entró bajo protección otomana", "3584dba0"], "d": ["Según el artículo «Kuveyt» del TDV, el puerto había sido fundado a comienzos del siglo XVIII por la tribu Utub, procedente de Néyed, y la familia Sabah se había hecho cargo del gobierno hacia finales del siglo. En los mismos años en que Al-Hasa pasaba a manos de los saudíes, el emirato, que ante la presión wahabí no tenía otra opción que apoyarse en Basora, entró bajo protección otomana. El vínculo se oficializaría en 1871 con la reordenación de Basora por Midhat Pachá y Kuwait sería considerado uno de los tres distritos del sanjacado de Basora; la posterior reclamación territorial de Irak se basa también en este registro.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Pérdida de La Meca ante los wahabíes", "2da23acd"], "d": ["El movimiento wahabí, surgido en Néyed, se dirigió hacia el Hiyaz en tiempos de Saud b. Abdulaziz; tras Taif y Medina, La Meca fue tomada por segunda vez — el emir de La Meca, el sherif Ghalib, entregó la ciudad a los wahabíes con la condición de seguir en el emirato. Los mausoleos fueron destruidos y se cortó el camino de las caravanas de peregrinos procedentes de Damasco y El Cairo; el surre que el sultán enviaba cada año a los Haremeyn quedó también interrumpido en estos años — la única excepción a esta asignación ininterrumpida hasta 1915 es el período del dominio wahabí. Como la condición de protector de los Haremeyn era uno de los pilares de la legitimidad del sultán, esta pérdida fue, más allá de la pérdida territorial, un duro golpe político; su recuperación tardaría siete años y solo sería posible con el ejército de Mehmed Alí Pachá de Kavala.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Fin de la República de Dubrovnik — ocupación francesa", "f8e27bf1"], "d": ["Los franceses, establecidos en la costa de Dalmacia por el Tratado de Campo Formio (1797), pusieron fin a la pequeña república mercantil al ocupar Dubrovnik el 27 de mayo de 1806. Así terminó el estatuto de vasallaje de tres siglos y medio de Dubrovnik, que desde 1458 conservaba su autonomía y sus privilegios comerciales pagando tributo a los otomanos; la ciudad y la isla de Mljet de la república pasan en el mapa a la administración francesa directa.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Pérdida de Sujumi ante los rusos — apertura de la costa oriental del mar Negro", "adc96bd4"], "d": ["En la guerra otomano-rusa de 1806-1812 la flota rusa se dirigió a la costa oriental del mar Negro y tomó Sohumkale, en la que se apoyaba el dominio otomano en Abjasia. La fortaleza era el centro del contacto con las tribus del Cáucaso y del comercio costero. Con su pérdida, Rusia se asentó por primera vez de forma duradera en la costa oriental del mar Negro; la influencia otomana en el Cáucaso quedó reducida a los alrededores de Anapa y Poti.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Parga fue cedida a la administración otomana", "66e0cc5d"], "d": ["Parga estaba en manos de Venecia desde 1401 y nunca había entrado en la administración otomana; tras la caída de Venecia pasó sucesivamente a Francia e Inglaterra. El artículo «Tepedelenli Ali Paşa» del TDV resume así la situación: la ciudad se rindió a los ingleses y solo fue cedida en 1819 a la administración de Ali Pachá. La cesión tuvo como consecuencia la emigración de la mayor parte de su población a las islas Jónicas. Así, el último del trío Preveza-Parga-Vonitsa, dejado a Venecia en Passarowitz, fue anexado también al imperio; Parga permanecería noventa y cuatro años como otomana.", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Corinto pasó a los insurgentes griegos", "892dcdc6"], "d": ["Durante la guerra de independencia griega, Acrocorinto pasó a manos de los insurgentes y el comandante de la fortaleza, Kâmil Bey, fue hecho prisionero.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Pérdida de Nauplia ante los insurgentes", "1a67fa50"], "d": ["Nauplia, el puerto de Morea con las fortificaciones más fuertes, se rindió por hambre tras un bloqueo de más de un año. La fortaleza era desde el comienzo de la rebelión el último gran punto de apoyo del control otomano en la península; con su pérdida, toda Morea pasó a manos de los insurgentes. La ciudad sería poco después la primera capital del nuevo Estado griego.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["Lepanto pasó a la administración griega", "c9d19d4b"], "d": ["Lepanto, en la costa norte del golfo de Corinto, que había permanecido en manos otomanas hasta la rebelión griega, se perdió en abril de 1829 y pasó a la administración griega; el nombre de la población fue cambiado al antiguo Naupacto. La población musulmana y judía de la ciudad desapareció por completo y esta se convirtió en una pequeña población.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Ocupación francesa de Argel — fin del odjak de tres siglos", "0be8f568"], "d": ["Con el pretexto del incidente del abanico, nacido de una disputa por una deuda, Francia mantuvo bloqueada la costa de Argel durante tres años y luego desembarcó tropas en Sidi Ferruch. Al final de una campaña de tres semanas el dey Hüseyin se rindió y terminó el odjak otomano de Argel, que duraba desde 1516. La ocupación no se limitó a la capital; Tremecén, Cherchell y Medea, en el interior, se perdieron también aquel mismo verano. Todavía tardaría veinticuatro años más en pasar toda la costa al control francés.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Cesión de Eubea (Eğriboz) a Grecia — junto con la isla (Karistos, Oreoi)", "7b524aa4"], "d": ["Eubea, que fue escenario de intensos combates durante la guerra de independencia griega pero permaneció en manos otomanas, fue cedida a los griegos en 1831 tras la entrada en vigor del tratado de paz. La población musulmana de la ciudad, importante base naval desde 1470, vendió todos sus bienes a precios muy bajos y emigró en masa a territorio otomano; la ciudad quedó vacía mucho tiempo y el viajero alemán Fallmerayer la describió en 1842 como una ciudad fantasma.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Ocupación francesa de Vehrân (Orán)", "a8415d66"], "d": ["Vehrân, que España había cedido sin guerra en 1792, era el mayor puerto del oeste de Argelia. Seis meses después de la caída de la capital, las tropas francesas entraron en la ciudad. La ofensiva hacia el oeste iniciada desde aquí se encontraría pronto con la resistencia del emir Abd al-Qadir, que duraría quince años.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Ocupación de Annaba (Bône)", "21f37fb1"], "d": ["Annaba, puerto del este de Argelia cercano a la frontera tunecina, fue tomada por las fuerzas francesas y convertida en base de la marcha sobre Constantina. La ciudad era también el puerto africano más cercano, frente a la isla de Cerdeña.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Cesión de Atenas al nuevo Estado griego", "98af5572"], "d": ["Atenas, otomana desde 1456, había cambiado de manos varias veces durante la guerra de independencia griega, y la guarnición de la Acrópolis había vuelto al control otomano en 1827. Como quedaba al norte de la frontera trazada por el Protocolo de Londres, la ciudad fue cedida al nuevo reino y la guarnición evacuó la Acrópolis. Al año siguiente, Atenas fue declarada capital de Grecia en lugar de Nauplia.", "6fca14a0"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Ocupación de Bugía (Bougie)", "a8927e00"], "d": ["El puerto de Bugía, donde las montañas de la Cabilia se abren al mar, era el último eslabón independiente de la línea costera entre Argel y Annaba. Fue tomado con el apoyo de la artillería naval; sin embargo, el interior montañoso detrás de él no entraría bajo control francés hasta treinta años después. Estas ocupaciones a lo largo de la costa constituyen la desaparición, año tras año, de la Argelia otomana en el mapa.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Ocupación de Sétif", "2073731a"], "d": ["Tras la caída de Constantina un año antes, las fuerzas francesas subieron a la meseta, tomaron la antigua ciudad romana de Sétif y establecieron allí una guarnición permanente. Sétif era el punto de cruce de las rutas de caravanas entre la costa y el Sahara; su ocupación mostró que Francia comenzaba a controlar no solo los puertos, sino también la red comercial del interior.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Ocupación de Biskra — pérdida de la puerta del Sahara", "d895cad0"], "d": ["Biskra era la puerta que se abre al Sahara al pie sur de las montañas del Atlas y el centro de los oasis de palmeras. Con su toma, en los años en que la resistencia del emir Abd al-Qadir comenzaba a quebrarse, el control francés alcanzó por primera vez el borde norte del desierto. Lo que seguiría sería ya una campaña del desierto, avanzando oasis tras oasis.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Ocupación de Touggourt — pérdida completa de Argelia", "33c056e2"], "d": ["Con la toma de Touggourt, ciudad oasis del norte del Sahara, la ocupación iniciada en 1830 quedó completada en la mitad norte de la actual Argelia. El Estado otomano combatía en esos años en la Guerra de Crimea en el mismo bando que Francia; sin renunciar nunca oficialmente a su reclamación jurídica sobre Argelia, de hecho no pudo dar un solo paso. El único territorio que quedaba en el norte de África era Trípoli de Berbería.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Caída de El Obeid — Kordofán pasó a las fuerzas del Mahdi", "58299f62"], "d": ["El movimiento iniciado por Muhammad Ahmad, que se proclamó mahdi, se extendió rápidamente contra la administración egipcia en Sudán. El Obeid, centro de Kordofán, cayó tras un asedio de cuatro meses y se convirtió en la capital de la rebelión; el tesoro y los depósitos de armas de la ciudad permitieron al movimiento convertirse en ejército. Sudán era jurídicamente territorio del jedivato de Egipto, todavía ligado a los otomanos, de modo que la pérdida cae en el mapa del cuerpo del imperio.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Caída de Jartum — pérdida de todo Sudán", "d4b98464"], "d": ["Tras un asedio de diez meses, las fuerzas del Mahdi entraron en Jartum, en la confluencia del Nilo Azul y el Nilo Blanco; el gobernador de la ciudad, Gordon, fue muerto, y la columna británica enviada en su auxilio llegó con dos días de retraso. A partir de esta fecha, todo Sudán, incluidos Sennar, Dongola y Kordofán, permaneció catorce años bajo la administración del Estado Mahdista. La región solo pasaría en 1899 a la administración conjunta anglo-egipcia, con el vínculo otomano completamente roto.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Ocupación italiana de Massaua — pérdida de la costa occidental del mar Rojo", "c333b95b"], "d": ["El puerto de Massaua, centro de la provincia de Abisinia, fue ocupado por Italia, que aprovechó la confusión de la rebelión del Mahdi extendida por Sudán; esto constituyó el núcleo de la Eritrea italiana. Suakin, al norte, y el archipiélago de Dahlak, mar adentro, se perdieron también en el mismo proceso. Así terminó el dominio otomano en la costa occidental del mar Rojo, que duraba desde la época de Selim I el Severo, y el mar se convirtió en aguas extranjeras en ambas orillas.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Ocupación italiana de Rodas", "e08662c5"], "d": ["Italia, que quería sentar al Estado otomano a la mesa en la Guerra de Trípoli, llevó la guerra al Mediterráneo y desembarcó tropas en Rodas. La isla fue tomada en pocos días. Rodas, que Solimán el Legislador tomó en 1522 tras un largo asedio y conservó trescientos noventa años, dejó así de ser la mayor base insular del imperio en el Mediterráneo oriental; aunque en el Tratado de Ouchy se la consideró ocupación temporal, nunca pudo ser recuperada.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Ocupación italiana del Dodecaneso", "200aacf2"], "d": ["En la semana siguiente a la toma de Rodas, la flota italiana ocupó también las islas de los alrededores; este archipiélago recibiría después el nombre de «Dodecaneso». La mayoría de las islas estaban a pocas millas de la costa de Anatolia y controlaban el paso sudoriental del Egeo. La ocupación fue considerada temporal en el Tratado de Ouchy a cambio de la renuncia a Trípoli, pero Italia nunca evacuó las islas; serían cedidas a Grecia en 1947.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Ocupación de Cos", "ab246c62"], "d": ["Cos, último eslabón de la operación del Dodecaneso, era una isla fértil y poblada situada justo frente a la península de Bodrum. Con la ocupación, todas las islas del extremo sudoriental del Egeo pasaron al control italiano y la costa suroeste de Anatolia quedó rodeada de un extremo a otro por una cadena de islas extranjeras.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Declaración de independencia de Nicaria", "c4452033"], "d": ["En la pequeña isla de Nicaria, entre Samos y Quíos, la población, en el clima de incertidumbre creado por las ocupaciones italianas, se sublevó, expulsó de la isla a la gendarmería otomana y proclamó un «Estado libre» de cinco meses con su propia bandera, sello y asamblea. En noviembre de 1912 la isla se unió a Grecia. A pesar de su pequeñez, este hecho es una clara muestra de cómo se disolvía la administración central en el Egeo.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Salida de Samos de la administración otomana", "3a862f2b"], "d": ["Samos era desde 1832 un principado autónomo que pagaba tributo a los otomanos y era gobernado por un príncipe nombrado por Estambul. En el vacío creado por la Guerra de Trípoli, el movimiento unionista de la isla se hizo con la administración y el orden de principado autónomo terminó de hecho; la isla proclamó ese mismo año su unión a Grecia. Esta isla, a dos kilómetros de la costa de Anatolia, fue uno de los primeros territorios perdidos en el Egeo.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Caída de Ioánina — pérdida del Épiro y de Parga", "d42fce18"], "d": ["Ioánina, sitiada durante cinco meses en la Guerra de los Balcanes, se rindió tras la caída de las posiciones de Bizani; con la ciudad, todo el Épiro pasó a Grecia. Parga, dependiente del sanjacado de Ioánina, se perdió también en esta fecha y terminó su administración otomana de noventa y cuatro años. La pérdida de Ioánina significaba el cierre de la última ventana del imperio al Adriático.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Caída de Edirne ante los búlgaros", "459d2e56"], "d": ["Tras un asedio de cinco meses y medio, Edirne, sin municiones ni provisiones, se rindió; Şükrü Pachá fue hecho prisionero. La caída de la ciudad, otomana desde 1361 y capital durante noventa y dos años, fue considerada el golpe más duro de la Guerra de los Balcanes. Edirne sería recuperada cuatro meses después, en la Segunda Guerra de los Balcanes, aprovechando el hundimiento de Bulgaria en los demás frentes.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Pérdida de Yanbu ante las fuerzas del sherif Hussein", "e291c816"], "d": ["La insurrección iniciada en junio por el sherif Hussein se extendió a la costa del mar Rojo; Yanbu, puerto de Medina, pasó a manos de los insurgentes con el apoyo de la flota británica. El puerto se convirtió en la principal puerta de entrada del flujo de armas y dinero que llegaba del exterior a la insurrección. Así quedó cortada la conexión marítima de las fuerzas de Fahreddin Pachá en Medina, y la ciudad quedó sola en el extremo del ferrocarril del Hiyaz.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Tercera batalla de Gaza — pérdida de Gaza y Khan Yunis", "c142a069"], "d": ["Tras dos intentos fallidos, Allenby rompió el frente en su tercera ofensiva rodeando por Beerseba y la línea de Gaza, mantenida durante seis meses, se derrumbó. Gaza y Khan Yunis, al sur, fueron evacuadas el mismo día. Esta ruptura fue el comienzo de la disolución del frente de Palestina; Jerusalén caería cinco semanas después.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Ocupación de Gümülcine — pérdida de Tracia occidental", "904d813c"], "d": ["Tracia occidental, que tras Mudros había pasado primero al control de las fuerzas aliadas, fue dejada a Grecia por decisión de la conferencia de San Remo y el ejército griego entró en Gümülcine. La región, recuperada a Bulgaria en 1913, fue el último territorio que el imperio perdió en Rumelia. El estatuto de la población turca de la región sería regulado tres años después en Lausana con el régimen de minorías.", "e3d0605f"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["Disgregación del Estado ilkhánida: muerte de Abu Said Bahadur Jan", "0f187469"], "d": ["Según el artículo «İlhanlılar» de la Enciclopedia del Islam del TDV, la muerte de Abu Said sin dejar heredero condujo a la fragmentación del Estado ilkhánida, que dominaba Irán desde hacía un siglo; los emires, aprovechando las luchas por el trono, fundaron dinastías locales como los yalayiríes, los Kara Koyunlu, los muzafaríes, los sarbadáridas de Jorasán y los Eretnaoğulları. Esta disgregación dividió la región en un mosaico de beylicatos que duraría un siglo; finalmente se reunificaría con las campañas de Tamerlán.", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["Tamerlán somete la mayor parte de Irán", "1cee2b82"], "d": ["Según el artículo «Timur» de la Enciclopedia del Islam del TDV, Tamerlán, que desde comienzos de la década de 1380 fue liquidando una por una las dinastías locales posilkhánidas como los sarbadáridas, los kértidas y los muzafaríes, sometió de hecho a su dominio la mayor parte de Irán durante la «campaña de los tres años» de 1386-1388; el golpe definitivo a la dinastía muzafarí se daría en 1393. Así la región quedó de nuevo bajo una única autoridad central tras un siglo de fragmentación.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["Victoria del Araxes: Kara Yusuf derrota al timúrida Abu Bakr Mirza", "4b61a75a"], "d": ["Tras la muerte de Tamerlán en 1405, el bey Kara Koyunlu Kara Yusuf, que regresó del exilio, tomó Avnik y recuperó sus tierras de Anatolia oriental; después marchó contra Abu Bakr Mirza, nieto de Tamerlán, considerado señor de Azerbaiyán y de los dos Irak, y lo derrotó a orillas del Araxes. Esta victoria no dio Tabriz a los Kara Koyunlu: el TDV `tebriz` escribe que la ciudad estaba en manos de Abu Bakr Mirza en 1408; la batalla que dio Azerbaiyán fue la de Sardrud, el 13 de abril de 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Victoria de Sardrud: Tabriz y Azerbaiyán pasan a los Kara Koyunlu", "1f0a429d"], "d": ["Kara Yusuf derrotó a Abu Bakr Mirza, el timúrida, por segunda vez después del Araxes, en Sardrud, cerca de Tabriz; esta victoria dio Azerbaiyán a los Kara Koyunlu. A continuación, Kara Yusuf encargó a Bistam Bey la conquista del Irak persa;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Epidemia de peste en Estambul y traslado del palacio a Edirne", "70c7a163"], "d": ["Según el artículo «İstanbul» de la Enciclopedia del Islam del TDV, el rápido e intenso poblamiento de la ciudad preparó el terreno para la propagación de enfermedades epidémicas de tiempo en tiempo; durante la epidemia de peste del año 1466, el palacio y los dignatarios del Estado se retiraron temporalmente a Edirne. La población de la ciudad sufrió graves pérdidas en epidemias de este tipo.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["Uzun Hasan pone fin al Estado Kara Koyunlu", "ef68399e"], "d": ["Según el artículo «Uzun Hasan» de la Enciclopedia del Islam del TDV, el soberano Ak Koyunlu Uzun Hasan derrotó y mató al soberano Kara Koyunlu Cihan Shah en la región de Bingöl-Sancak el 12 de Rebîülâhir 872 / 10 de noviembre de 1467; el hijo de Cihan Shah, Hasan Ali, fue derrotado en Merend en septiembre de 1468 y muerto ante Hamadán entre abril y mayo de 1469, y así se puso fin definitivo al Estado Kara Koyunlu. Los territorios pasaron al dominio Ak Koyunlu; en la década siguiente el Estado se expandiría hasta el interior de Irán.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Apertura a la enseñanza de las madrasas de Sahn-ı Semân", "021f2a83"], "d": ["Según el artículo «Sahn-ı Semân» de la Enciclopedia del Islam del TDV, estas ocho madrasas, fundadas en el seno del complejo de Fâtih, fueron concebidas como la institución de enseñanza de más alto nivel de la época y formaron la cúspide de la jerarquía ilmiye otomana. La docencia y la graduación en ellas fueron consideradas, en los siglos siguientes, el peldaño más prestigioso en la carrera de cadí y de profesor.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Finalización del Palacio de Topkapı (Saray-ı Cedîd)", "d2db6323"], "d": ["Según el artículo «Topkapı Sarayı» de la Enciclopedia del Islam del TDV, las fuentes de la época difieren en las fechas de inicio y fin de las obras; según la fecha 883 (1478) de la inscripción de Bâb-ı Hümâyun, las obras, comenzadas probablemente en 1465 por orden de Mehmed el Conquistador, estaban en gran parte terminadas hacia este año y el palacio ocupó el lugar del centro de Estado del palacio viejo. Así el sultán se trasladó a su nueva residencia, que sería durante tres siglos el corazón administrativo y ceremonial del Estado.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Entronización de Bayezid II en Estambul", "9b686d04"], "d": ["Según el artículo «Bayezid II» de la Enciclopedia del Islam del TDV, el príncipe Bayezid, bey del sanjacado de Amasya, vino rápidamente a Estambul al recibir la noticia de la muerte de su padre y subió al trono; con el apoyo de los jenízaros dejó atrás a su hermano Cem, que había partido de Konya. En la entronización se distribuyó a los jenízaros el donativo de acceso al trono que era costumbre. Este cambio de trono encendió también la mecha de la lucha entre los dos hermanos.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Cem Sultan se proclamó sultán en Bursa", "b355168a"], "d": ["Según el artículo «Cem Sultan» de la Enciclopedia del Islam del TDV, Cem, que llegó a Bursa pasando por Karaman, tomó la ciudad, se proclamó sultán e hizo leer la jutba. Este breve sultanato terminó cuando las fuerzas enviadas por su hermano mayor Bayezid II derrotaron a Cem en Yenişehir. Tras la derrota, Cem hubo de huir hacia Egipto.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Ejecución de Gedik Ahmed Pachá", "6d75a58c"], "d": ["Según el artículo «Gedik Ahmed Paşa» de la Enciclopedia del Islam del TDV, el pachá, conocido por la campaña de Otranto y por su gran visirato, fue ejecutado en Edirne por orden de Bayezid II, por su actitud en el asunto de Cem Sultan y por el recelo que suscitaba su influencia. La muerte de uno de los comandantes más experimentados de la época de Mehmed el Conquistador tuvo un amplio eco en el palacio.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Fundación de la primera imprenta en Estambul", "04475930"], "d": ["Según el artículo «Matbaa» de la Enciclopedia del Islam del TDV, los hermanos David y Samuel ibn Nahmias, inmigrantes judíos venidos de España, fundaron en Estambul la primera imprenta que imprimía con caracteres hebreos. Quedó registrada como la primera empresa de imprenta que funcionó en tierras otomanas; la impresión en turco con caracteres árabes sería posible mucho después, en el siglo XVIII.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["Shah Ismail toma Tabriz: fundación del Estado safávida", "014d81e6"], "d": ["Según los artículos «Safevîler» y «Akkoyunlular» de la Enciclopedia del Islam del TDV, İsmail, el joven jeque de la tekke de Ardebil, con un ejército formado por sus discípulos kizilbash de Anatolia, infligió una grave derrota al sultán Ak Koyunlu Elvend en la región de Najicheván; Elvend huyó a Diyarbekir, İsmail entró en Tabriz, se sentó en el trono y declaró el chiísmo duodecimano como credo oficial. Así se cerró tanto el dominio Ak Koyunlu como la era de los beylicatos posilkhánidas de la región; se fundó el Estado safávida, que duraría tres siglos.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Terremoto de la «Pequeña Resurrección» en Estambul", "53e3b1d6"], "d": ["Según el artículo «İstanbul» de la Enciclopedia del Islam del TDV, el violento terremoto que golpeó la ciudad fue recordado entre el pueblo como la «Pequeña Resurrección»; se produjeron graves daños en las murallas, las mezquitas y muchos edificios, y hubo numerosas víctimas. Por orden de Bayezid II se inició en la ciudad una amplia movilización de reparación y reconstrucción.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Comienzo de la rebelión de Şahkulu", "3d9a4a90"], "d": ["Según el artículo «Şahkulu Baba Tekeli» de la Enciclopedia del Islam del TDV, Şahkulu, alimentado por la propaganda safávida, reunió a su alrededor a una amplia masa turcomana en la región de Teke y comenzó una gran rebelión de carácter religioso-social. La rebelión, una de las crisis de seguridad interna más graves de la época, sacudió profundamente la autoridad central del Estado.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Muerte de Bayezid II en el camino de Dimetoka", "c46e98c9"], "d": ["El antiguo sultán, que tras su abdicación salió de Estambul para ir a Dimetoka, la ciudad donde había nacido, se indispuso en la aldea de Abalar, cerca de Çorlu, mientras avanzaba en su litera que solo recorría 5-6 km al día, y murió el 25 de rabi' al-awwal de 918 (10 de junio de 1512). El artículo de la Enciclopedia del Islam del TDV encuentra muy sospechosa la causa de la muerte; según algunas fuentes locales y extranjeras, se insiste en la posibilidad de que fuera envenenado. Tras un reinado de treinta y un años, murió así el octavo sultán de la descendencia de Osman Gazi.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Ejecución del príncipe Ahmed por orden de Selim I el Severo", "65abb2f2"], "d": ["Según el artículo «Selim I» de la Enciclopedia del Islam del TDV, el príncipe Ahmed, favorito de su padre Bayezid II y principal rival por el trono, fue derrotado en la llanura de Yenişehir en la lucha que emprendió tras la entronización de su hermano Selim, y fue capturado y muerto mientras huía del campo de batalla. Con este hecho, Selim puso fin en gran medida a la rivalidad por el trono entre sus hermanos y sobrinos.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["İbrahim Pachá fue nombrado gran visir", "9c94c1e3"], "d": ["Según el artículo «İbrâhim Paşa, Makbul» de la Enciclopedia del Islam del TDV, İbrahim Pachá, ascendido de has odabaşı a beylerbey de Rumelia y el mismo día a gran visir, se convirtió en gran visir el 13 de sha'ban de 929 (27 de junio de 1523). Fue un nombramiento sin precedentes, del servicio de palacio directamente al gran visirato, y mostraba la extraordinaria cercanía de İbrahim Pachá a Solimán el Legislador.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Barbarroja Hayreddin Pachá fue nombrado kapudan-ı derya", "a0ff6bab"], "d": ["Según el artículo «Barbaros Hayreddin Paşa» de la Enciclopedia del Islam del TDV, Hayreddin Pachá, conocido por sus éxitos en Argel, fue llamado a Estambul el 6 de abril de 1534 y nombrado kapudan-ı derya y beylerbey de Cezayir-i Bahr-i Sefîd. Este nombramiento se considera el comienzo de la reestructuración de la flota otomana y de la institucionalización del poder naval en el Mediterráneo.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rüstem Pachá fue gran visir por primera vez", "ddfcc014"], "d": ["Según el artículo «Rüstem Paşa» de la Enciclopedia del Islam del TDV, tras la destitución de Hadım Süleyman Pachá por un desacuerdo que tuvo con un visir, Rüstem Pachá fue nombrado gran visir el 17 de ramadán de 951 (2 de diciembre de 1544). Rüstem Pachá, cuya cercanía al palacio aumentó gracias a su matrimonio con Mihrimah Sultan, se convirtió con este cargo en uno de los estadistas más influyentes de la época de Solimán el Legislador.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebüssuûd Efendi fue nombrado sheij al-Islam", "11ed04f8"], "d": ["Según el artículo «Ebüssuûd Efendi» de la Enciclopedia del Islam del TDV, Ebüssuûd Efendi, que había sido ocho años cadiasker de Rumelia, fue nombrado sheij al-Islam en sha'ban de 952 (octubre de 1545) y permaneció en este cargo veintiocho años y once meses. Ebüssuûd Efendi, conocido por sus fetuas que armonizaban los códigos de Solimán el Legislador con el derecho de la sharía, desempeñó un papel determinante en la configuración de las instituciones jurídicas y educativas de su época.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Murió Barbarroja Hayreddin Pachá", "3378a0bf"], "d": ["Según el artículo «Barbaros Hayreddin Paşa» de la Enciclopedia del Islam del TDV, murió en Estambul el 6 de yumada al-awwal de 953 (5 de julio de 1546), tras una breve enfermedad. La muerte de Barbarroja, enterrado en el mausoleo contiguo a la madrasa que él mismo mandó construir en Beşiktaş, fue vista como el cierre de una época en la supremacía mediterránea establecida por la flota otomana.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Comenzó la construcción de la mezquita y el complejo de Süleymaniye", "101ec36f"], "d": ["Según el artículo «Süleymaniye Camii ve Külliyesi» de la Enciclopedia del Islam del TDV, el complejo, cuyos cimientos se pusieron en 1550 bajo la dirección del arquitecto jefe Mimar Sinan, fue concebido como un gran complejo social compuesto, además de la mezquita, por madrasas, hospital, comedor público y biblioteca. La obra fue uno de los mayores programas de construcción, símbolo del poder del reinado de Solimán el Legislador y de la edificación de Estambul.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["Comenzó una nueva oleada de peste en Estambul y sus alrededores", "547d6bf6"], "d": ["Según el artículo «Tâun» de la Enciclopedia del Islam del TDV, una de las epidemias del siglo XVI que afectaron al mundo islámico tuvo lugar entre 1552 y 1566 y fue especialmente intensa en Estambul, Anatolia, Rumelia, Egipto y el norte de África. La ampliación de las rutas comerciales y la creciente movilidad de la población se cuentan entre los factores que facilitaron la propagación de enfermedades epidémicas en el período de mayor fuerza del imperio.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Kara Ahmed Pachá fue nombrado gran visir", "a7d7748e"], "d": ["Según el artículo «Kara Ahmed Paşa» de la Enciclopedia del Islam del TDV, Kara Ahmed Pachá, que servía como segundo visir, fue elevado al gran visirato el 27 de shawwal de 960 (5 de octubre de 1553), tras la repentina destitución del gran visir en funciones. Este cambio señala un período, coincidente con los días de la ejecución del príncipe Mustafa, en el que los equilibrios de poder dentro del palacio cambiaban rápidamente de manos.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Fue ejecutado el kapudan-ı derya Pîrî Reis", "3b2ad7a0"], "d": ["Según el artículo «Pîrî Reis» de la Enciclopedia del Islam del TDV, cuando llegaron a Egipto las acusaciones de que, al levantar el asedio de Ormuz, había saqueado a cambio de soborno los bienes de los musulmanes y abandonado a su ejército en el campo de batalla, el célebre marino y cartógrafo fue ejecutado en El Cairo a finales del año 960 (finales de 1553). La muerte de Pîrî Reis, cuyos bienes fueron confiscados, se considera consecuencia de la rivalidad entre pachás en la política naval de Basora y del océano Índico en la época.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Kara Ahmed Pachá fue ejecutado, Rüstem Pachá volvió a ser gran visir", "9a85076a"], "d": ["Según los artículos «Rüstem Paşa» y «Kara Ahmed Paşa» de la Enciclopedia del Islam del TDV, en lugar de Kara Ahmed Pachá, ejecutado de improviso durante la reunión del diván el 13 de dhu al-qa'da de 962 (29 de septiembre de 1555), Rüstem Pachá fue nombrado gran visir por segunda vez ese mismo día con el apoyo de las sultanas Hürrem y Mihrimah. Las fuentes dejan abiertos los entresijos del suceso, que ha sido interpretado como resultado de intrigas dentro del palacio.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Murió Hürrem Sultan", "1ae998b5"], "d": ["Según el artículo «Hürrem Sultan» de la Enciclopedia del Islam del TDV, Hürrem Sultan, que como haseki sultana de Solimán el Legislador tuvo durante años gran influencia dentro del palacio, murió en Estambul el 26 de yumada al-ajira de 965 (15 de abril de 1558) y fue sepultada en su mausoleo del complejo de la mezquita de Süleymaniye. La muerte de Hürrem Sultan, que había consolidado su autoridad sobre el harén tras la muerte de la valide sultana Hafsa en 1534, eliminó también el efecto equilibrador frente a la rivalidad por el trono entre sus hijos Bayezid y Selim.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Sokullu Mehmed Pachá ascendió al gran visirato", "896391a2"], "d": ["Según el artículo «Sokullu Mehmed Paşa» de la Enciclopedia del Islam del TDV, Sokullu Mehmed Pachá, que ascendió al gran visirato con la muerte de Semiz Ali Pachá el 30 de dhu al-qa'da de 972 (29 de junio de 1565), fue el último gran visir de Solimán el Legislador y, al continuar en este cargo también en las épocas de Selim II y Murad III, se convirtió en uno de los grandes visires que más tiempo sirvieron en la historia otomana.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Selim II llegó a Estambul y fue entronizado", "0289ef97"], "d": ["Tras la muerte de Solimán el Legislador en Szigetvár, la noticia fue mantenida en secreto durante semanas por Sokullu Mehmed Pachá para no alterar el orden. Según la Enciclopedia del Islam del TDV, mientras Selânikî da como fecha de llegada de Selim a Estambul el 15 de rabi' al-awwal de 974 (30 de septiembre de 1566), la mayoría de los historiadores contemporáneos consideran correcto el 9 de rabi' al-awwal (24 de septiembre). La muerte de Solimán el Legislador solo fue proclamada oficialmente en Belgrado el 24-25 de octubre de 1566.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["La flota reconstruida por Kılıç Ali Pachá se hizo a la mar", "d0fc9f48"], "d": ["Tras la grave derrota de Lepanto (7 de octubre de 1571), se construyeron barcos en los astilleros durante todo el invierno. Según la Enciclopedia del Islam del TDV, el 1 de safar de 980 (13 de junio de 1572) la nueva flota, compuesta por 250 galeras y unos 300 reises voluntarios, fue botada en una exhibición de fuerza.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Sokullu Mehmed Pachá fue víctima de un atentado y murió", "6ffa8dec"], "d": ["Sokullu Mehmed Pachá, que fue gran visir catorce años durante el reinado de tres sultanes, fue apuñalado y muerto el 20 de sha'ban de 987 (12 de octubre de 1579) por un derviche que se le acercó, como para presentar una petición, en el diván de la tarde en su mansión. Según la Enciclopedia del Islam del TDV, se discute si el atentado tuvo relación con la venganza del ejecutado shaij hamzawí Hamza Bâlî.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["Primer ahidnâme comercial con Inglaterra — capitulaciones concedidas a los ingleses", "59c8e3ee"], "d": ["William Harborne, representante inglés enviado a Estambul en octubre de 1578, obtuvo de Murad III, con el apoyo de Sokullu Mehmed Pachá y de Hoca Sâdeddin Efendi, un ahidnâme fechado en 1580. Con este ahidnâme los comerciantes ingleses adquirieron el derecho a beneficiarse en igual grado de los privilegios comerciales (capitulaciones) concedidos antes a los franceses y a los venecianos. Se intercambiaron cartas entre la reina Isabel I y Murad III y se estableció también una relación oficial entre los dos Estados. Inmediatamente después de estos privilegios, en 1581 se fundó en Londres la Levant Company; los ingleses llevaron a cabo su comercio en la región por medio de esta compañía hasta 1825.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["El Observatorio de Estambul fue demolido por hatt-ı hümâyun", "3bc0c78c"], "d": ["Por efecto de una fetua según la cual los observatorios traían mala suerte a los países y de la oposición dentro del palacio, el Observatorio de Estambul fue demolido, con todos sus instrumentos, por un hatt-ı hümâyun del 4 de dhu al-hiyya de 987 (22 de enero de 1580). Según la Enciclopedia del Islam del TDV, este fue el breve final de la institución fundada por Takıyyüddin er-Râsıd.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Comenzó la fiesta de circuncisión del príncipe Mehmed en el Atmeydanı", "c2926d5d"], "d": ["El príncipe Mehmed, hijo de Murad III, fue circuncidado con magníficas ceremonias que comenzaron el 6 de yumada al-awwal de 990 (29 de mayo de 1582) y duraron cincuenta y seis o cincuenta y siete días. Según la Enciclopedia del Islam del TDV, las fiestas celebradas en el Atmeydanı fueron una de las celebraciones palaciegas más fastuosas de su época.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Murió la valide sultana Nurbânû", "77d0a577"], "d": ["Nurbânû Sultan, madre de Murad III, murió el 22 de dhu al-qa'da de 991 (7 de diciembre de 1583). Según la Enciclopedia del Islam del TDV, como valide sultana había mantenido correspondencia con las cortes de Venecia y Francia, y el Senado veneciano había aceptado ese mismo año enviarle un regalo por valor de 2000 ducados venecianos de oro en reconocimiento a sus servicios.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Estalló el Suceso del Beylerbeyi por el akçe devaluado", "db2f2e61"], "d": ["Cuando el Estado pagó reduciendo la proporción de plata del akçe, los sipahis y jenízaros cercaron el palacio y provocaron una sangrienta rebelión que pasó a la historia con el nombre de Suceso del Beylerbeyi. Según el artículo «Abdülkadir Şeyhî Efendi» de la Enciclopedia del Islam del TDV, el sheij al-Islam fue destituido a raíz de este hecho.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Mehmed III subió al trono, diecinueve príncipes fueron estrangulados", "2cd9a8c5"], "d": ["Mehmed III, a la muerte de su padre Murad III, llegó a Estambul el viernes 16 de yumada al-awwal de 1003 (27 de enero de 1595) y subió al trono. Según la Enciclopedia del Islam del TDV, esa misma noche fueron estrangulados diecinueve príncipes, cuatro de ellos adultos (Mustafa, Bayezid, Osman y Abdullah); fue el fratricidio más numeroso de la historia otomana.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safiye Sultan adquirió influencia como valide sultana", "000bec21"], "d": ["Safiye Sultan, esposa de Murad III y madre de Mehmed III, con la entronización de su hijo alcanzó una posición determinante en la política palaciega con el título de valide sultana. Según la Enciclopedia del Islam del TDV, en este período la influencia originada en el harén llegó hasta el punto de intervenir directamente en los asuntos del Estado.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Mehmed III salió personalmente a campaña por presión de los jenízaros", "d3c50656"], "d": ["A pesar de la oposición del gran visir Damad İbrahim Pachá y por presión de los jenízaros, Mehmed III salió de Estambul el 20 de junio de 1596, como el primer sultán desde Solimán el Legislador que se puso personalmente al frente del ejército. Según la Enciclopedia del Islam del TDV, esto significaba la reactivación de la antigua tradición de la gaza.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["La epidemia de peste iniciada en la década de 1570 seguía afectando a Estambul", "eb4ca37a"], "d": ["Según el artículo sobre la peste de la Enciclopedia del Islam del TDV, la epidemia iniciada en la década de 1570 mantuvo su efecto hasta comienzos del siglo XVII y golpeó a Anatolia, los Balcanes, Egipto y el norte de África, empezando por Estambul. Los períodos epidémicos constituían una amenaza crónica que interrumpía con frecuencia la vida del palacio y de la ciudad.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Murió Karayazıcı Abdülhalim, el movimiento rebelde se debilitó", "876ca7a6"], "d": ["Karayazıcı Abdülhalim, que se retiró herido tras la grave derrota sufrida en Sepetli, cerca de Elbistan, el 12 de agosto de 1601, murió en el año 1010 (1602). Según la Enciclopedia del Islam del TDV, la noticia de su muerte llegó a Estambul en el ramadán del año 1010 (febrero-marzo de 1602); las fuentes señalan que se discute si su muerte fue consecuencia de la herida o si ocurrió a manos de sus propios hombres.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Fin de hecho de la tradición del fratricidio", "9046c607"], "d": ["En su entronización, Ahmed I, a diferencia de los sultanes anteriores, no hizo matar a su hermano, el príncipe Mustafa, sino que le perdonó la vida; esta decisión se considera el comienzo de la adopción de hecho del principio de ekber-erşed en el sistema sucesorio otomano. El artículo «Mustafa I» de la Enciclopedia del Islam del TDV relata que Mustafa llevó desde entonces una vida de mahfil en el palacio. La práctica puso un fin de hecho a los asesinatos de entronización que se habían sucedido durante siglos.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Se puso la primera piedra de la mezquita del Sultán Ahmed", "1683262f"], "d": ["Por orden de Ahmed I se puso con ceremonia la primera piedra de la mezquita que construiría en el Atmeydanı el arquitecto Sedefkâr Mehmed Ağa. Según el artículo «Sultan Ahmed Camii ve Külliyesi» de la Enciclopedia del Islam del TDV, el edificio fue también objeto de las críticas de la época por ser la primera gran mezquita sultánica construida directamente con fondos del tesoro, sin una victoria de conquista. El complejo fue concebido para incluir, junto con la mezquita, una madrasa, un comedor público y un mausoleo.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Asesinato de Osman el Joven por los jenízaros (Hâile-i Osmâniye)", "324f6582"], "d": ["Los jenízaros y sipahis, sublevados por los rumores de que planeaba salir de Estambul con el pretexto de la peregrinación y disolver el cuerpo de jenízaros, depusieron a Osman II y lo hicieron estrangular en las mazmorras de Yedikule. Según el artículo «Osman II» de la Enciclopedia del Islam del TDV, este hecho es en la historia otomana el primer caso en que un sultán fue asesinado abiertamente por una rebelión militar y produjo una profunda ruptura en la relación entre la dinastía y el ejército. Sus últimas horas transcurrieron así: fracasado el intento de refugiarse en la mansión del agá de los jenízaros Ali Ağa, el sultán fue montado en un caballo, según la expresión del TDV, «de manera lamentable, con la cabeza descubierta y en estado de desaliño», y llevado entre graves insultos primero a la Mezquita Central, donde estaba Mustafa I, y por la tarde del mismo día a Yedikule; según algunos historiadores, para probar su muerte le cortaron la oreja y la nariz y se las mostraron a la madre de Mustafa I. Tras el suceso, Mustafa I fue entronizado por segunda vez. El hecho, conocido como «Hâile-i Osmâniye» (la tragedia de Osman), alteró de modo permanente el equilibrio entre palacio y cuerpo de jenízaros e inició discusiones de legitimidad que durarían todo el siglo.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Segunda entronización de Mustafa I", "34a0b29a"], "d": ["Tras el asesinato de Osman el Joven por los jenízaros, y al no haber otro miembro varón adulto en la dinastía, Mustafa I fue entronizado por segunda vez. Según el artículo «Mustafa I» de la Enciclopedia del Islam del TDV, este segundo sultanato transcurrió también, como el anterior, sin poder dirigir de hecho los asuntos del Estado, y el gobierno quedó en manos de los visires y de la valide sultana. Este período de catorce meses terminó en 1623 con la entronización de Murad IV.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["Incendio de Cibali", "3e42fb08"], "d": ["El incendio que estalló en Cibali y se extendió rápidamente por efecto del viento redujo a cenizas una gran parte de Estambul; según el artículo «İstanbul» de la Enciclopedia del Islam del TDV, las fuentes de la época relatan que se quemaron miles de casas. La relación establecida entre el incendio, el entramado de casas de madera y el hábito de fumar tabaco fue la justificación directa de la severa prohibición del tabaco y de los cafés que Murad IV decretaría poco después. La catástrofe fue solo uno de los grandes incendios que se repetían en la Estambul de la época.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Prohibición del tabaco y de los cafés por Murad IV", "5dd71297"], "d": ["Tras el incendio de Cibali, por preocupación por los incendios y el orden público, Murad IV prohibió fumar tabaco y los cafés; a quienes no cumplieron la prohibición se les aplicaron castigos severos, incluida la pena de muerte. Según el artículo «Murad IV» de la Enciclopedia del Islam del TDV, el sultán siguió una política de disciplina interna tan estricta que recorría personalmente las calles de la ciudad disfrazado para vigilar el cumplimiento de la prohibición. Estas duras medidas se consideran parte del esfuerzo de Murad IV por restablecer la autoridad central.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Epidemia de peste en Estambul", "f33f58c5"], "d": ["En tiempos de Murad IV, Estambul fue sacudida por una grave epidemia de peste que afectó a una parte importante de la población; el comercio dentro de la ciudad y la vida diaria se vieron interrumpidos durante meses. El artículo «İstanbul» de la Enciclopedia del Islam del TDV registra que las epidemias repetidas en el siglo XVII afectaron seriamente al equilibrio demográfico de la ciudad. Durante la epidemia, el palacio y la élite se trasladaron por un tiempo a los jardines y pabellones fuera de la ciudad.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Vuelo con alas de Hezarfen Ahmed Çelebi (tradición)", "df474c04"], "d": ["Según la tradición transmitida por Evliya Çelebi, Hezarfen Ahmed Çelebi logró, con alas fabricadas por él mismo, lanzarse desde la torre de Gálata y planear hasta Üsküdar; aunque su certeza histórica es discutida, se convirtió en símbolo de la imaginación técnica. Al principio el sultán lo recompensó, pero luego, por el eco que provocó el hecho, lo desterró a Argel.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Cinci Hoca Hüseyin Efendi adquirió influencia en el palacio", "41d21572"], "d": ["Hüseyin Efendi, curandero con soplos llamado a palacio para tratar las dolencias psíquicas del sultán İbrahim, ganó en poco tiempo la confianza del sultán y ascendió hasta el cargo de cadiasker de Anatolia. Según el artículo «Hüseyin Efendi, Cinci Hoca» de la Enciclopedia del Islam del TDV, utilizó esta influencia para acumular riquezas e intervenir en los acontecimientos políticos de la época. Tras la muerte de İbrahim fue privado de todos sus cargos y ejecutado en 1648.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Ejecución de Kemankeş Mustafa Pachá", "0ecc8030"], "d": ["Kemankeş Mustafa Pachá, gran visir desde la época de Murad IV, que había conseguido un importante superávit para el tesoro con sus reformas financieras, fue estrangulado y ejecutado porque sus rivales dentro del palacio influyeron sobre İbrahim y lo acusaron de provocar una rebelión de los jenízaros. Según el artículo «Kemankeş Mustafa Paşa» de la Enciclopedia del Islam del TDV, su ejecución tuvo lugar el 21 de dhu al-qa'da de 1053 / 31 de enero de 1644: Kemankeş Kara Mustafa Pachá fue estrangulado por el verdugo Kara Ali en el mercado de Hocapaşa y sepultado en su propio mausoleo de Çarşıkapı. Su muerte es recordada como un ejemplo impresionante de la inestabilidad del cargo de gran visir en la época y puso fin al breve período de reformas estrictas.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["Decisión en el diván de la campaña de Creta y partida de la flota", "9076827e"], "d": ["Se decidió en el Divan-ı Hümayun abrir una campaña de gran envergadura contra la isla de Creta, perteneciente a Venecia, y la flota otomana al mando del kapudan-ı derya partió de Estambul rumbo a Creta. Según el artículo «Girit» de la Enciclopedia del Islam del TDV, esta decisión constituyó el comienzo político de un largo período de asedio y guerra que duraría unos veinticinco años. La apertura de la campaña había provocado amplias discusiones entre los dignatarios del Estado, por ser la mayor empresa de política exterior de la época de İbrahim.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Entronización de Mehmed IV a los siete años", "a197a3bc"], "d": ["Inmediatamente después de la deposición de İbrahim, su hijo Mehmed, de solo siete años, fue entronizado y se convirtió en sultán con el título de Mehmed IV. Según el artículo «Mehmed IV» de la Enciclopedia del Islam del TDV, el acceso al trono a edad tan temprana avivó la lucha de influencia dentro del palacio entre su abuela Kösem Sultan y su madre Turhan Sultan. Esta lucha por el poder culminaría en 1651 con el asesinato de Kösem Sultan.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Reforma del presupuesto equilibrado de Tarhuncu Ahmed Pachá", "376fc7f2"], "d": ["El gran visir Tarhuncu Ahmed Pachá, para superar la crisis financiera causada por los largos años de guerra, aplicó un severo programa de ahorro que incluía también los gastos de palacio y preparó el primer presupuesto equilibrado conocido de la historia otomana (el informe de Tarhuncu). Según el artículo «Tarhuncu Ahmed Paşa» de la Enciclopedia del Islam del TDV, esta reforma produjo un importante superávit para el tesoro, pero creó un amplio descontento en el entorno del palacio y en la alta burocracia. Este descontento culminaría un año después en su ejecución.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["Suceso del Plátano (Vak'a-i Vakvakiye)", "4c6ed90f"], "d": ["Según el artículo «Çınar Vak'ası» de la Enciclopedia del Islam del TDV, los jenízaros y sipahis que volvían de la campaña de Creta sin cobrar se sublevaron en Estambul y exigieron la ejecución de los estadistas a quienes acusaban de corrupción. La propuesta de confiscación y destierro del gran visir Zurnazen Mustafa Pachá no fue aceptada; primero tres funcionarios y luego cerca de treinta estadistas fueron ejecutados y sus cadáveres colgados de los plátanos de la plaza de Sultanahmet. Por ello el suceso es conocido como Çınar Vak'ası (Suceso del Plátano).", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Nombramiento de Köprülü Mehmed Pachá como gran visir con aceptación condicionada", "3a6b7f8f"], "d": ["Según el artículo «Köprülü Mehmed Paşa» de la Enciclopedia del Islam del TDV, Köprülü Mehmed Pachá, de casi ochenta años, tomó el sello solo después de hacer aceptar a la valide Turhan Sultan y a Mehmed IV unas duras condiciones —que no se interfiriera en sus nombramientos y que no se diera crédito a lo que se dijera en su contra—. Asumió el cargo el 26 de dhu al-qa'da de 1066, en lugar de Boynueğri Mehmed Pachá, y emprendió con dureza el restablecimiento de la disciplina del Estado.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["Represión del movimiento de los Kadizadelíes por Köprülü Mehmed Pachá", "5ec3ce84"], "d": ["Según el artículo «Kadızâdeliler» de la Enciclopedia del Islam del TDV, Köprülü Mehmed Pachá, nada más asumir el cargo, se ocupó del conflicto religioso entre el círculo de Kadızâde Mehmed Efendi y la gente de las cofradías. Tras consultar a los ulemas, emitió un firmán de ejecución para los líderes del movimiento, Üstüvânî Mehmed Efendi, Türk Ahmed y Divâne Mustafa, pero esta pena fue conmutada por destierro y los tres fueron enviados a Chipre; así terminó la segunda fase del movimiento.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Gran incendio en Estambul: quema de Ağakapısı", "b9253b66"], "d": ["Según el artículo «Ağakapısı» de la Enciclopedia del Islam del TDV, en el gran incendio que estalló en julio de 1660, en tiempos de Mehmed IV, Ağakapısı, cuartel general oficial del agá de los jenízaros, se quemó por completo y fue reconstruido a continuación. Este incendio fue uno de los grandes incendios urbanos que golpearon una y otra vez a la Estambul de la época.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Nombramiento de Köprülüzâde Fâzıl Ahmed Pachá como gran visir", "c1999b5c"], "d": ["Según el artículo «Köprülüzâde Fâzıl Ahmed Paşa» de la Enciclopedia del Islam del TDV, fue nombrado gran visir el 8 de rabi' al-awwal de 1072 (1 de noviembre de 1661), a la muerte de su padre Köprülü Mehmed Pachá. Fâzıl Ahmed Pachá, conocido, a diferencia de su padre, como persona de carácter suave, piadosa y protectora de sabios y artistas, mandó fundar bibliotecas e instituciones benéficas en Estambul y en los territorios conquistados durante su gran visirato de más de quince años.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Nombramiento de Vânî Mehmed Efendi como predicador de Yeni Cami y preceptor del sultán", "7ea6aaae"], "d": ["Según el artículo «Mehmed Efendi, Vânî» de la Enciclopedia del Islam del TDV, Vânî Mehmed Efendi, llamado a Estambul cuando Köprülüzâde Fâzıl Ahmed Pachá se convirtió en gran visir y presentado a Mehmed IV, ganó en poco tiempo el estrecho interés del sultán. En 1665 fue nombrado predicador de Yeni Cami y preceptor del sultán, y se convirtió en uno de los hombres de religión más influyentes del palacio.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Nombramiento de Merzifonlu Kara Mustafa Pachá como gran visir", "3d1e836c"], "d": ["Según el artículo «Merzifonlu Kara Mustafa Paşa» de la Enciclopedia del Islam del TDV, fue nombrado gran visir el 28 de sha'ban de 1087 (5 de noviembre de 1676), a la muerte de Fâzıl Ahmed Pachá. Merzifonlu, con larga experiencia en la administración del Estado como yerno y discípulo de la familia Köprülü, se convirtió en uno de los grandes visires más fuertes e influyentes de Mehmed IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Muerte de Vânî Mehmed Efendi en el destierro", "cda714aa"], "d": ["Según el artículo «Mehmed Efendi, Vânî» de la Enciclopedia del Islam del TDV, Vânî Mehmed Efendi, considerado uno de los principales que hicieron aceptar al sultán la campaña de Viena, cayó en desgracia por la presión de la opinión pública tras el fracaso de la campaña y fue desterrado a la población de Kestel, en Bursa. Murió allí el 14 de dhu al-qa'da de 1096 (12 de octubre de 1685) y fue sepultado a la entrada de la mezquita que él mismo había mandado construir.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Nombramiento de Köprülüzâde Fâzıl Mustafa Pachá como gran visir y sus reformas financieras", "b048570e"], "d": ["Según el artículo «Köprülüzâde Fâzıl Mustafa Paşa» de la Enciclopedia del Islam del TDV, Fâzıl Mustafa Pachá, nombrado gran visir el 11 de muharram de 1101 (25 de octubre de 1689), reorganizó el método de recaudación de la cizye según los principios de la sharía, combatió la inflación del mangır y fortaleció el tesoro transfiriendo recursos desde las instituciones del palacio. Además reforzó la administración provincial con funcionarios de confianza y mandó establecer consejos locales semejantes al diván central.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["Entrada en vigor del sistema de malikâne", "316b8426"], "d": ["Según el artículo «Mâlikâne» de la Enciclopedia del Islam del TDV, en el último cuarto del siglo XVII el aumento de los gastos de guerra y la disminución de los ingresos por las pérdidas territoriales sumieron al tesoro en una grave crisis financiera. En el sistema de malikâne, que entró en vigor en 1106 (1695), se reconoció a los arrendatarios (mültezim) el derecho a un impuesto fijo vitalicio, introduciendo un incentivo para proteger la producción en lugar de una explotación a corto plazo.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["Entronización de Mustafa II", "b53656c7"], "d": ["Según el artículo «Mustafa II» de la Enciclopedia del Islam del TDV, Mustafa II, que subió al trono a los treinta y un años, proclamó su sultanato sin esperar la aprobación del gran visir y del sheij al-Islam; la ceremonia de ceñir la espada se celebró unos días después en Eski Cami. El sultán, que subió al trono en una época de guerras en varios frentes tras el desastre de Viena, fue el último sultán otomano que salió personalmente a campaña.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Nombramiento de Feyzullah Efendi como sheij al-Islam por segunda vez", "1cf14cff"], "d": ["Según el artículo «Feyzullah Efendi, Seyyid» de la Enciclopedia del Islam del TDV, fue nombrado sheij al-Islam por segunda vez el 11 de shawwal de 1106 (25 de mayo de 1695), tras la entronización de Mustafa II. Su influencia sobre el sultán fue aumentando durante este período en el cargo, que duró más de ocho años.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Feyzullah Efendi colocó a sus hijos en altos cargos y la reacción acumulada", "a6398280"], "d": ["Según el artículo «Feyzullah Efendi, Seyyid» de la Enciclopedia del Islam del TDV, el sheij al-Islam obtuvo de Mustafa II un firmán sin precedentes según el cual su hijo Fethullah Efendi sería sheij al-Islam después de él, y colocó a sus parientes en altos cargos a edad temprana. Estas prácticas crearon un amplio descontento entre la clase ilmiye, el ejército y la población de Estambul; combinado con los rumores de que la capital sería trasladada a Edirne, preparó el terreno para el Suceso de Edirne de 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["Comienzo del Suceso de Edirne", "5a106458"], "d": ["Según el artículo «Edirne Vak'ası» del TDV, el movimiento, iniciado por la sublevación de soldados que no habían cobrado sus ulufe, se transformó en poco tiempo en una amplia rebelión en la que participaron jenízaros, estudiantes de madrasa, comerciantes y pueblo. El objetivo principal de la rebelión era el sheij al-Islam Feyzullah Efendi, a quien se acusaba de intervenir excesivamente en los asuntos del Estado. Una multitud de unas 60.000 personas marchó de Estambul a Edirne.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Gran visirato de Nevşehirli Damad İbrahim Pachá", "8d627a6f"], "d": ["Según el artículo «Damad İbrâhim Paşa, Nevşehirli» del TDV, fue elevado al cargo de gran visir el 8 de yumada al-ajira de 1130 (9 de mayo de 1718), durante las negociaciones de paz en curso con Austria, y desde su nombramiento se dedicó a las negociaciones que pondrían fin a la guerra; dos meses después se firmó el Tratado de Passarowitz (21 de julio de 1718). En palabras del TDV, «quería ocuparse de los problemas sociales y financieros y anhelaba un período de paz que hiciera olvidar las guerras que durante largos años habían terminado en derrota». Realizó reformas en la hacienda, redujo los salarios de los soldados y creó un importante superávit en el tesoro del Estado. Su gran visirato, que duraría doce años, constituyó el marco político de la época que lleva su nombre (la Era de los Tulipanes).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Fundación del Cuerpo de Tulumbacı", "f58b0d97"], "d": ["Según el artículo «Tulumbacı» del TDV, ante el éxito que mostró en los incendios de Estambul con la bomba (tulumba) Gerçek Dâvud, que volvía de la campaña de Morea de 1715, el gran visir Nevşehirli Damad İbrahim Pachá le encargó fundar un cuerpo oficial de bomberos. El cuerpo, fundado en el Cuartel de Acemi Oğlanları con seis oficiales y cincuenta soldados, llegó a 150 hombres en 1724 y a 461 en 1755. Dâvud permaneció al frente del cuerpo hasta su muerte en 1733.", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["Recepción de Mehmed Efendi por Luis XV", "0ff5b174"], "d": ["Según el artículo «Yirmisekiz Çelebi Mehmed Efendi» del TDV, el embajador fue recibido oficialmente por el rey de Francia Luis XV en el Palacio de las Tullerías y presentó los regalos y la carta de Ahmed III. Durante su visita recorrió los palacios de Versalles, Trianon y Marly, así como hospitales, observatorios y talleres; registró con dibujos lo que vio.", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["Regreso de Mehmed Efendi a Estambul", "a09a8bba"], "d": ["Según el artículo «Yirmisekiz Çelebi Mehmed Efendi» del TDV, las observaciones del embajador, que volvió de una embajada de un año en París, influyeron en el gusto arquitectónico de la Era de los Tulipanes. El hecho de que su hijo trabajara después con İbrahim Müteferrika preparó el terreno para la fundación de la primera imprenta turca, el legado más duradero de la embajada.", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Construcción del pabellón de Sâdâbâd", "aec9c65e"], "d": ["Según el artículo «Sâdâbâd» del TDV, a orillas del arroyo de Kağıthane se construyó un amplio complejo de recreo y paseo compuesto por un pabellón inspirado en la arquitectura palaciega francesa, un canal, fuentes y quioscos. Sâdâbâd, que se convirtió en el lugar de recreo más de moda de la época, fue inmortalizado en los poemas del poeta Nedîm. El complejo fue en gran parte destruido durante la rebelión de Patrona Halil de 1730.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["Las fuerzas rusas toman Derbent: campaña caspia de Pedro I", "c2b269f9"], "d": ["Mientras el Estado safávida se veía arrastrado a la confusión interna por la invasión afgana, el zar ruso Pedro I emprendió una campaña con el fin de apoderarse de las tierras iraníes de la costa del Caspio; la ciudad costera de Derbent se rindió a las fuerzas rusas sin una resistencia apreciable. Según el artículo «Derbend» de la Enciclopedia del Islam del TDV, esta ocupación fue el comienzo de un dominio ruso temporal que duraría trece años; el Estado otomano, aprovechando la misma confusión, se dirigió a la parte occidental del Cáucaso. El ejército había desembarcado desde Astracán por mar en el golfo de Agrajan y desde allí avanzó por tierra a lo largo de la costa vía Tarku; el shamjal de Tarku recibió a Pedro como huésped y entró en la sujeción rusa.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["Abolición del shamjalato de Tarku: administración directa rusa", "b0f029c6"], "d": ["Adil-Girey, shamjal de Tarku, que en 1722 había recibido a Pedro como huésped y entrado en la sujeción rusa, se rebeló en 1725; Yeropkin destruyó Tarku en el otoño de 1725, el shamjal fue arrestado y desterrado a mediados de mayo de 1726, y el shamjalato fue abolido. Tarku y sus alrededores permanecieron bajo administración rusa directa hasta el Tratado de Ganya de 1735.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["Permiso a İbrahim Müteferrika para fundar una imprenta", "0659dd0a"], "d": ["Según el artículo «İbrâhim Müteferrika» del TDV, se permitió la fundación de la primera imprenta turca por firmán de Ahmed III y por fetua del sheij al-Islam Yenişehirli Abdullah Efendi. La imprenta comenzó a funcionar en el barrio de Yavuzselim de Estambul. Müteferrika imprimió diecisiete obras en veintitrés volúmenes hasta su muerte en 1747.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Finalización del primer libro impreso, el Diccionario de Vankulu", "684700e8"], "d": ["Según el artículo «İbrâhim Müteferrika» del TDV, la traducción turca del Sıhâh al-Jawharî (el Diccionario de Vankulu), primera obra de la imprenta, quedó terminada a comienzos de 1729. Fue el primer libro impreso con caracteres árabes en tierras otomanas y se considera el comienzo de la historia de la imprenta turca.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Ejecución del gran visir Nevşehirli Damad İbrahim Pasha", "50c64341"], "d": ["Según el artículo «Damad İbrâhim Paşa, Nevşehirli» del TDV, el cadáver del gran visir, muerto en el palacio durante la rebelión de Patrona Halil, fue arrastrado por las calles de Estambul y abandonado cerca de la fuente de Ahmed III en la plaza de Sultanahmet. Así terminaron de forma sangrienta sus doce años de gran visirato y la Era de los Tulipanes.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["Abdicación de Ahmed III y ascenso al trono de Mahmud I", "a43f5d40"], "d": ["Según el artículo «Mahmud I» del TDV, ante la presión de los rebeldes, Ahmed III abdicó tras obtener garantías para sí mismo y para sus hijos, y él mismo entronizó a su sobrino, el príncipe Mahmud. Mahmud I, que subió al trono con el consejo de su tío —«toma los asuntos del Estado en tus manos y no confíes en nadie»—, se dedicó desde el principio a quebrar la influencia del grupo rebelde que lo había entronizado.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Reforma del cuerpo de artillería por Humbaracı Ahmed Pasha", "ea3a7c64"], "d": ["Según el artículo «Humbaracı» del TDV, el oficial de origen francés convertido al islam, Ahmed Pasha, emprendió la reforma de la organización de los humbaracıs asalariados (ulufeli) al estilo europeo durante el gran visirato de Hekimoğlu Ali Pasha. Creó una nueva estructura de 601 hombres, dependiente directamente del gran visir, con 300 pagados con sueldo y 301 con timar. Con la tecnología de la época hizo fabricar 100 morteros y 50.000 proyectiles.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Fundación de la Hendesehâne (primer ejemplo de escuela de ingeniería)", "a77ed1f3"], "d": ["Según el artículo «Mahmud I» del TDV, Humbaracı Ahmed Pasha fundó en Üsküdar la Hendesehâne, también llamada Humbarahâne, y dio instrucción militar basada en matemáticas y geometría a alumnos elegidos entre los servidores del palacio y los bostancıs. Esta institución se considera el primer ejemplo de las escuelas de ingeniería que se desarrollarían después.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["Tratado de Ganya: devolución de Derbent y Bakú a Irán", "ff19d531"], "d": ["Rusia, que buscaba una alianza con Irán contra la amenaza otomana, devolvió mediante el Tratado de Ganya las ciudades de la costa del Caspio que tenía en su poder desde hacía trece años a Irán, bajo el mando de Nadir Jan (que aún no había tomado el título de shah). Según el artículo «Derbend» de la Enciclopedia del Islam del TDV, esta retirada fue resultado de que Rusia no quería luchar a la vez en dos frentes en el sur (otomano e iraní), y consolidó el prestigio militar de Nadir, que allanaría su ascenso al trono pocos años después. Tarki (Tarku), bajo administración rusa, también volvió al lado iraní con esta retirada (en el mapa se usa el día de Ganya).", "94b6c31b"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["Ascenso al trono de Nadir Shah en la llanura de Mugán: fin de hecho de la dinastía safávida", "4f640979"], "d": ["Según el artículo «Nadir Şah» de la Enciclopedia del Islam del TDV, el kurultai de unas veinte mil personas reunido en la llanura de Mugán le pidió con insistencia que se pusiera al frente de Irán; Nadir aceptó la propuesta con la condición de que se abandonara la comprensión chiita extremista que había causado las guerras entre safávidas y otomanos y se adoptara la escuela moderada yafarí, y subió al trono con el título de Nâdir Shah el 24 de Şevval 1148 (8 de marzo de 1736). Esto significaba el fin de hecho de la dinastía safávida, de dos siglos de duración, y la fundación de la dinastía afsharí.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["Comienzo de la epidemia de peste en Estambul", "9fa82b56"], "d": ["Según el artículo «Tâun» del TDV, la epidemia de peste que afectó al mundo islámico entre 1739 y 1743 golpeó también a Estambul en esta época. El artículo señala que las epidemias del siglo XVIII fueron relativamente más leves que las de siglos anteriores. Entre los periodos epidémicos se cuentan también los años 1713, 1719, 1728-1729 y 1759-1765.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["Incendio de Hocapaşa", "321c7d0d"], "d": ["Según el artículo «Fatma Sultan Camii» del TDV, el incendio de Hocapaşa, declarado de noche, asoló la Sublime Puerta y sus alrededores; se supone que la mezquita de Fatma Sultan, situada en la zona, también resultó dañada. Esta catástrofe, uno de los grandes incendios que golpearon Estambul durante el reinado de Osman III, causó graves destrucciones en el centro comercial y administrativo de la ciudad.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["Gran visirato de Koca Ragıp Mehmed Pasha", "a1846910"], "d": ["Ragıp Pasha, conocido como poeta y diplomático, fue nombrado gran visir por Osman III (continuó en el cargo tras la muerte de Osman III en octubre de 1757 y recibió un nuevo sello de Mustafa III). Mientras proseguía la Guerra de los Siete Años, siguió una política exterior equilibrada que mantuvo al Estado otomano al margen de los conflictos de Europa. A lo largo de su gran visirato, que duraría seis años, concedió importancia también a actividades culturales, como la fundación de una biblioteca.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["Fallecimiento de Ragıp Pasha", "6bc19323"], "d": ["Ragıp Pasha falleció tras seis años de gran visirato. Con su muerte terminó el gran visirato más duradero y equilibrado del reinado de Mustafa III.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["Gran terremoto de Estambul y destrucción de la mezquita de Fâtih", "2475b4dc"], "d": ["Según el artículo «Fâtih Camii ve Külliyesi» del TDV, en el gran terremoto de 1766 la cúpula principal de la mezquita se derrumbó por completo y los muros sufrieron daños irreparables. Por orden de Mustafa III, la reconstrucción, iniciada en 1767 bajo la dirección de los arquitectos Sarım İbrahim Efendi e İzzet Mehmed Bey, se completó en 1771 con un diseño nuevo, distinto del plan antiguo.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["Efímero intento de escuela de artillería bajo el barón de Tott", "4192260c"], "d": ["Según el artículo «Mühendishâne-i Bahrî-i Hümâyun» del TDV, los fracasos de la guerra otomano-rusa de 1768 pusieron de manifiesto la necesidad de formación militar técnica; la efímera escuela de artillería abierta con la contribución del oficial francés barón de Tott entró en funcionamiento en octubre de 1772, pero resultó ineficaz. Este intento se considera el precursor de la Mühendishâne-i Bahrî-i Hümâyun, que se fundaría en 1775.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Selim III asciende al trono", "00d046d9"], "d": ["A la muerte de Abdülhamid I, su sobrino Selim III subió al trono. Según el artículo «Selim III» de la Enciclopedia del Islam del TDV, el nuevo sultán, interesado desde su juventud como príncipe en la reforma de los ejércitos europeos, empezó a hacer preparar poco después de su ascenso un programa de renovación de gran alcance. En pocos años este programa pasaría a conocerse como Nizâm-ı Cedîd.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Comienza la preparación del programa de reformas del Nizâm-ı Cedîd", "eff78a68"], "d": ["Selim III hizo preparar un amplio programa de renovación conforme a los memoriales solicitados a los altos dignatarios del Estado y a expertos extranjeros. Según el artículo «Nizâm-ı Cedîd» de la Enciclopedia del Islam del TDV, este programa no se limitó a crear un nuevo ejército, sino que se convirtió en un amplio movimiento de reforma que abarcaba también las finanzas, la administración provincial y la diplomacia. Durante los quince años siguientes tendría tanto partidarios como opositores.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["Se establecen embajadas permanentes en las capitales europeas", "2e9dc8a1"], "d": ["Por primera vez en la historia del Estado otomano, Selim III envió embajadores permanentes que residirían de forma continua en los grandes centros europeos. Según el artículo «Elçi» de la Enciclopedia del Islam del TDV, este paso dotó de una organización estable a la diplomacia otomana, que hasta entonces se había llevado a cabo solo mediante delegaciones temporales y de una única misión. La principal tarea de las nuevas embajadas era informar regularmente a Estambul de los acontecimientos políticos y militares de Europa.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["Se funda el tesoro İrad-ı Cedîd", "ae5c8ce2"], "d": ["Se creó un tesoro aparte para cubrir los gastos del ejército del Nizâm-ı Cedîd y del programa de reformas. Según el artículo «Esham» de la Enciclopedia del Islam del TDV, entre los ingresos del nuevo tesoro figuraban la explotación directa por el Estado de algunas mukataas y el control de la venta de esham. Esta medida fue un intento de crear una nueva fuente de recursos al margen del sistema fiscal tradicional.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Comienza la rebelión de Kabakçı Mustafa", "b98eee17"], "d": ["El descontento acumulado contra el Nizâm-ı Cedîd estalló con el levantamiento de los soldados yamak bajo la dirección de Kabakçı Mustafa. Según el artículo «Kabakçı İsyanı» de la Enciclopedia del Islam del TDV, los rebeldes se hicieron con el control de Estambul en poco tiempo y exigieron las cabezas de los estadistas partidarios del Nizâm-ı Cedîd. El levantamiento acabó en pocos días con la deposición de Selim III.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Selim III es depuesto", "ff2c30ec"], "d": ["Bajo la presión de la rebelión de Kabakçı Mustafa, Selim III fue depuesto mediante una fetva obtenida del sheij al-Islam. Según el artículo «Selim III» de la Enciclopedia del Islam del TDV, esta decisión marcó el momento en que terminó de hecho el periodo de reformas de dieciocho años; el ejército del Nizâm-ı Cedîd también fue disuelto poco después. Selim comenzó a ser mantenido bajo custodia en el palacio de Topkapı.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Mustafa IV asciende al trono", "8f1ac86c"], "d": ["Inmediatamente después de la deposición de Selim III, su sobrino Mustafa IV fue proclamado sultán. Según el artículo «Mustafa IV» de la Enciclopedia del Islam del TDV, el nuevo sultán inició su reinado bajo la influencia de los círculos contrarios al Nizâm-ı Cedîd que habían apoyado la rebelión. Este breve periodo fue una etapa de inestabilidad en la que la autoridad central se debilitó por completo.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Alemdar Mustafa Pasha entra en Estambul con su ejército", "0cad3dea"], "d": ["El âyan de Rusçuk, Alemdar Mustafa Pasha, se presentó ante Estambul con su ejército con el fin de volver a entronizar a Selim III. Según el artículo «Alemdar Mustafa Paşa» de la Enciclopedia del Islam del TDV, el propio Mustafa IV lo recibió a su entrada en la ciudad; pero en pocos días el equilibrio de poder dentro del palacio cambiaría por completo. Esta entrada puso en marcha la cadena de acontecimientos que acabó tanto con la muerte de Selim como con un nuevo ascenso al trono.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["Selim III es asesinado", "e452f5f6"], "d": ["El día en que Alemdar Mustafa Pasha se apoderó de la Sublime Puerta, Selim III fue asesinado en el palacio por orden de Mustafa IV. Según el artículo «Selim III» de la Enciclopedia del Islam del TDV, fue una decisión tomada para impedir un intento de volver a entronizar a un sultán depuesto. La muerte de Selim desembocó ese mismo día en el ascenso al trono de Mahmud.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["Mahmud II asciende al trono", "661c1974"], "d": ["Tras el asesinato de Selim III, Mahmud, que había quedado como único varón de la dinastía, subió al trono con el apoyo de Alemdar Mustafa Pasha. Según el artículo «Mahmud II» de la Enciclopedia del Islam del TDV, el nuevo sultán pasó los primeros meses de su reinado bajo la tutela de Alemdar, que lo había entronizado, y esforzándose por restablecer el equilibrio entre los âyan y el centro. Este periodo fue el comienzo del proceso de reformas profundas de los veinte años siguientes.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["Se funda el ejército Sekbân-ı Cedîd", "6f9eb5e4"], "d": ["Alemdar Mustafa Pasha hizo crear, en lugar del disuelto Nizâm-ı Cedîd, un nuevo ejército equipado al estilo europeo. Según el artículo «Sekbân-ı Cedîd» de la Enciclopedia del Islam del TDV, esta fuerza, compuesta por tres regimientos, fue vista por los jenízaros como una amenaza directa y fue eliminada en un levantamiento jenízaro solo unos meses después de su fundación.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["Caída de İbrâil: la primera gran brecha en la línea del Danubio", "ee519321"], "d": ["En la guerra con Rusia iniciada en 1806, la fortaleza de İbrâil, en la orilla norte del Danubio, fue sitiada y bombardeada por las fuerzas rusas al mando del conde Kaminski. En su interior había 4100 soldados de infantería, 1100 de caballería y 260 cañones; la fortaleza se rindió al general Essen por falta de víveres. Así quedó abierto el extremo norte de la línea de defensa del Danubio.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["Rendición de Rusçuk: también se pierde la orilla sur del Danubio", "084062e8"], "d": ["Rusçuk resistió el largo y sangriento asedio del ejército ruso al mando del conde Kaminski; se rindió con la condición de que la guarnición y la población civil pudieran abandonar la ciudad en seguridad. La caída de la ciudad fortificada más fuerte de la orilla sur del Danubio inclinó el curso de la guerra a favor de Rusia.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["Se funda el Cuerpo Eşkinci", "67c56759"], "d": ["Mahmud II hizo crear una nueva unidad, con soldados elegidos de entre el cuerpo de jenízaros, que recibiría instrucción al estilo europeo. Según el artículo «Eşkinci Ocağı» de la Enciclopedia del Islam del TDV, la unidad comenzó su instrucción el 12 de junio de 1826, pero los jenízaros lo vieron como el fin de su propio cuerpo. La rebelión que estalló tres días después puso fin también a la breve vida del Cuerpo Eşkinci.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["Se funda el Asâkir-i Mansûre-i Muhammediyye", "14b84a7e"], "d": ["Inmediatamente después de la abolición del Cuerpo de Jenízaros, Mahmud II hizo crear en su lugar un nuevo ejército regular, instruido al estilo europeo. Según el artículo «Asâkir-i Mansûre-i Muhammediyye» de la Enciclopedia del Islam del TDV, este ejército, a diferencia de los intentos anteriores, se convirtió en una institución duradera gracias a su sistema de rangos, su programa de instrucción y su régimen de sueldos. En los años siguientes se transformaría en el ejército Nizamiye de la era de las Tanzimat.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["Se prohíbe la orden bektaşí", "f7d9a367"], "d": ["Simultáneamente con la abolición del Cuerpo de Jenízaros, se prohibió también la orden bektaşí, conocida por sus vínculos religiosos con el cuerpo. Según el artículo «Bektaşîlik» de la Enciclopedia del Islam del TDV, mientras algunos jeques de tekkes menores fueron ejecutados, el jeque del dergâh de Hacı Bektaş fue desterrado a Amasya y las tekkes fueron entregadas a la administración naqshbandí. A pesar de este duro golpe, la orden siguió manteniendo su organización en secreto.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["El incidente del abanico: pretexto de la invasión", "e949001e"], "d": ["En una entrevista tensa por la deuda de trigo que Francia tenía desde hacía tiempo con Argel, el dey Hüseyin golpeó con el abanico que tenía en la mano al cónsul francés Deval. Este incidente, surgido de una disputa por un crédito, fue convertido en el pretexto oficial de la invasión que comenzaría tres años después.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["Bloqueo francés de la costa de Argel: un asedio de tres años", "d0ba97a5"], "d": ["Tras el incidente del abanico, Francia bloqueó la costa de Argel. El bloqueo duró tres años; se agotaron el comercio marítimo y las fuentes de ingresos de la odjak, y su capacidad de resistencia quedó erosionada antes de que empezara la invasión.", "79d27be2"]},
"OLAYLAR_EK7:1828-02-22:0":{"b": ["Tratado de Turkmenchay: Erevan y Talish pasan a Rusia", "abffcfdb"], "d": ["Al terminar la guerra ruso-iraní de 1826-1828 con una grave derrota de Irán, por el tratado firmado en Turkmenchay los kanatos de Erevan y Najicheván y la región de Talish (Lankarán, Astara), en la costa del Caspio, fueron cedidos a Rusia; además se impuso una pesada indemnización de guerra. Según el artículo «Revan» de la Enciclopedia del Islam del TDV, esta pérdida es el momento en que se trazó la frontera ruso-iraní en el Cáucaso, que seguiría vigente en gran medida hasta hoy, y desencadenó también la migración de población armenia a Erevan.", "f6438d89"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["Segunda caída de İbrâil: el zar Nicolás ante la fortaleza", "eb6a8741"], "d": ["İbrâil, devuelta a los otomanos en 1812 y refortificada en 1817-1818, fue sitiada en abril con 4000 guardianes y 278 cañones en su interior. Su comandante, Ebûbekir Pasha, estableció una nueva línea de defensa; el zar Nicolás I se presentó en persona ante la fortaleza a finales de mayo. La ciudad sufrió la ocupación rusa, pero sería devuelta por el Tratado de Edirne y cedida al principado de Valaquia.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["El fez es declarado tocado oficial", "f55be4eb"], "d": ["Mahmud II, con un cambio profundo en la vestimenta de los funcionarios y los soldados, declaró el fez como tocado oficial en lugar del turbante. Según el artículo «Fes» de la Enciclopedia del Islam del TDV, esta decisión se anunció mediante un hatt-ı hümâyun y se puso en práctica junto con las reformas de estilo occidental del Asâkir-i Mansûre-i Muhammediyye. El cambio significaba también el fin de la jerarquía tradicional de la vestimenta.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["Cesión de Ahıska a Rusia: se pierde la capital del eyalato de Çıldır", "e2e00b2a"], "d": ["Ahıska, bajo administración otomana desde la batalla de Çıldır de 1578 y capital del eyalato de Çıldır, fue cedida a Rusia por el Tratado de Edirne, firmado al término de la guerra de 1828-1829. La pérdida de la ciudad causó una profunda tristeza entre la población y fue objeto de numerosas elegías.", "9ad8078a"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["Desembarco de Sîdî Ferruc: el ejército francés en suelo argelino", "33327553"], "d": ["Tras tres años de bloqueo, el ejército francés de desembarco al mando del conde de Bourmont desembarcó en la bahía de Sîdî Ferruc, al oeste de Argel. Las fuerzas que avanzaron hacia la ciudad rompieron la línea de defensa en tres semanas; el 4 de julio cayó el Fuerte del Emperador, que domina la ciudad, y al día siguiente el dey Hüseyin se rindió.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["Destierro del dey Hüseyin: fin de hecho de la odjak de Argel", "e122403b"], "d": ["En virtud de las condiciones de la rendición, el último dey de Argel, Hüseyin, fue sacado de la ciudad con su familia y su tesoro y enviado a Nápoles. Así terminó la administración de la odjak, que se había sometido a Selim II en 1519 y durante trescientos años había sido la base naval otomana más poderosa del Mediterráneo.", "54846340"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["Retirada del ejército ruso de Valaquia y Moldavia: fin de una ocupación de seis años", "efdb0275"], "d": ["En la guerra otomano-rusa de 1828-1829, los rusos habían ocupado Valaquia y Moldavia y, tras el Tratado de Edirne, no se habían retirado hasta el pago de la indemnización de guerra. Cuando en enero de 1834 la indemnización se redujo a cinco millones, las fuerzas rusas evacuaron los Principados y se nombraron nuevos voivodas para los dos principados. La suzeranía otomana volvió sobre el papel, pero Rusia conservó la influencia que había establecido con el Reglamento Orgánico.", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["Se funda la organización Redif-i Asâkir-i Mansûre", "15947493"], "d": ["La organización Redif, como fuerza de reserva que apoyaría al Asâkir-i Mansûre-i Muhammediyye, fue fundada mediante un reglamento fechado el 8 de julio de 1834. Según el artículo «Redif» de la Enciclopedia del Islam del TDV, bajo la dirección del serasker Koca Hüsrev Pasha se formaron en los distritos provinciales batallones de unos mil cuatrocientos hombres cada uno. La organización fue concebida para apoyar también la seguridad local sin ser llamada a servicio permanente.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["Se funda el Ministerio de Asuntos Exteriores", "750c6c7d"], "d": ["Mahmud II abolió el cargo de Reisülküttâb, que llevaba los asuntos exteriores, y en su lugar fundó el Ministerio de Asuntos Exteriores (Hariciye Nezareti). Según el artículo «Hariciye Nezâreti» de la Enciclopedia del Islam del TDV, el primer ministro del nuevo departamento fue Mehmed Âkif Pasha, y la organización comenzó a funcionar en la mansión del embajador en Viena, Rıfat Bey. Esta disposición fue el comienzo de la conducción de la política exterior otomana según el principio ministerial moderno.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["Se funda el Meclis-i Vâlâ-yı Ahkâm-ı Adliyye", "69db056e"], "d": ["Mahmud II hizo fundar el Meclis-i Vâlâ-yı Ahkâm-ı Adliyye como consejo de alto nivel en el que se discutirían las leyes y reglamentos que se prepararan. Según el artículo «Meclis-i Vâlâ-yı Ahkâm-ı Adliyye» de la Enciclopedia del Islam del TDV, el consejo comenzó a funcionar efectivamente el 31 de marzo de 1838 y casi la totalidad de las reformas posteriores de las Tanzimat fueron preparadas y supervisadas por medio de este órgano. La institución se convirtió en uno de los centros más importantes de la burocracia otomana moderna.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["Ataque de Sinope", "5947e93f"], "d": ["La flota rusa del mar Negro, al mando del almirante Najímov, atacó sin declaración de guerra a la flota otomana fondeada en el puerto de Sinope; se hundieron doce barcos, más de dos mil soldados murieron como mártires y el comandante de la flota, Osman Pasha, fue hecho prisionero. Según el artículo «Sinop» de la Enciclopedia del Islam del TDV, en el ataque ardieron también en la ciudad siete mescids, dos mektebs, 247 casas y 170 tiendas, y perdieron la vida civiles, cinco musulmanes y dieciséis cristianos. El suceso, que resonó en la opinión pública europea como la «catástrofe de Sinope», fue el desencadenante directo de que Inglaterra y Francia entraran en la guerra del lado otomano pocos meses después.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["Se publica Tasvir-i Efkâr", "506c98e2"], "d": ["Tasvir-i Efkâr, publicado por Şinasi, comenzó a aparecer como cuarto periódico en turco después de Takvîm-i Vekāyi', Cerîde-i Havâdis y Tercüman-ı Ahvâl. Según el artículo «Tasvîr-i Efkâr» del TDV, el periódico se convirtió en portavoz del movimiento de los Nuevos Otomanos en la época de Nâmık Kemal, que posteriormente asumió su dirección editorial.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["Se funda la Sociedad de los Nuevos Otomanos", "335fb02d"], "d": ["Los intelectuales otomanos que huyeron a Europa bajo la dirección de Mustafa Fâzıl Pasha se organizaron con el nombre de Joven Turquía mediante un reglamento de trece artículos. Según el artículo «Yeni Osmanlılar Cemiyeti» del TDV, el grupo difundió la demanda de un gobierno constitucional publicando en París, Londres y Ginebra periódicos como Muhbir y Hürriyet.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["Se funda el Şûrâ-yı Devlet", "b863b306"], "d": ["El Meclis-i Ahkâm-ı Adliyye se dividió en dos: el Şûrâ-yı Devlet, que se ocupaba de los asuntos administrativos, y el Dîvân-ı Ahkâm-ı Adliyye, que se ocupaba de los judiciales. Según el artículo «Şûrâ-yı Devlet» del TDV, a la presidencia de la institución, que tomaba como modelo el Conseil d'État francés, se nombró a Midhat Pasha; el objetivo era la separación de los poderes legislativo, ejecutivo y judicial.", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["Se emite la orden de fundación del Darülfünun", "513704bf"], "d": ["El Darülfünun fue fundado oficialmente mediante una orden (irade) preparada por el gran visir Âli Pasha y el ministro de Instrucción Pública Saffet Pasha; las primeras clases habían comenzado antes, en 1863. Según el artículo «Darülfünun» del TDV, la institución pasó efectivamente a la enseñanza en febrero de 1870, bajo la dirección de Hoca Tahsin Efendi, con las secciones de filosofía y letras, ciencias y derecho.", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["Comienzan los trabajos de la Mecelle-i Ahkâm-ı Adliyye", "8abdcbee"], "d": ["La Sociedad de la Mecelle, formada bajo la presidencia de Ahmed Cevdet Pasha, presidente del Dîvân-ı Ahkâm-ı Adliyye, emprendió la preparación de un código civil basado en el derecho hanafí. Según el artículo «Mecelle-i Ahkâm-ı Adliyye» del TDV, el último fascículo de la obra, compuesta de dieciséis libros y 1851 artículos, fue terminado y entró en vigor el 15 de septiembre de 1876; se considera la primera codificación del derecho islámico.", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["Se representa «Vatan yahut Silistre» y Nâmık Kemal es enviado al destierro", "3861284c"], "d": ["Cuando la obra patriótica de Nâmık Kemal se representó en el teatro de Gedikpaşa, los espectadores salieron a las calles gritando «¡Viva la patria, viva Kemal!». Según el artículo «Nâmık Kemal» del TDV, el gobierno, asustado por esta manifestación, cerró el periódico İbret y el 6 de abril de 1873 envió a Nâmık Kemal al destierro en Chipre (Magosa) sin juicio.", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["Abdülaziz muere en circunstancias sospechosas", "85816692"], "d": ["Abdülaziz, trasladado por voluntad propia al palacio de Fer‘iye tras ser depuesto (1 de junio de 1876), fue hallado el 4 de junio en su habitación con las venas de las muñecas cortadas. Una junta de diecinueve médicos, en la que participaron también médicos de las embajadas, redactó un informe de formulación ambigua; el 6 de junio los periódicos anunciaron la muerte como suicidio. La investigación ordenada por Abdülhamid II llegó en cambio a la convicción de que la muerte no era un suicidio sino un asesinato, y los acusados fueron juzgados en 1881 en el Tribunal de Yıldız; el asunto sigue siendo discutido hoy en la historiografía.", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["Destitución y destierro de Midhat Pasha del gran visirato", "b5247b06"], "d": ["El gran visir Midhat Pasha, artífice del Kanun-i Esasi, fue destituido por Abdülhamid II seis semanas después de su proclamación y desterrado al extranjero en el transcurso de una noche. Según el artículo «Midhat Paşa» de la Enciclopedia del Islam del TDV, la destitución se relaciona con el malestar del sultán ante las disposiciones de la constitución que limitaban sus propias facultades. El pasha fue primero a Nápoles y después a diversas ciudades de Europa.", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["Abdulaziz ibn Saud recupera Riad de los Rashidíes", "75eb8830"], "d": ["El joven Abdulaziz, de la dinastía saudí, que diez años antes había sido desterrado a Kuwait, atacó Riad con un pequeño destacamento, mató al lugarteniente del gobernador de Al Rashid (Shammar) y se apoderó de la ciudad. Según el artículo «Riyad» de la Enciclopedia del Islam del TDV, el progresivo debilitamiento de los Rashidíes y su incapacidad de enviar refuerzos a la ciudad facilitaron el éxito de este ataque; el suceso se considera el momento de fundación del Segundo Estado Saudí, que en los treinta años siguientes formaría el núcleo de la actual Arabia Saudí.", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["Entrada del Ejército de Acción en Estambul", "41c8304c"], "d": ["El Ejército de Acción (Hareket Ordusu), que partió de Salónica y estaba compuesto en su mayoría por unidades afectas al Comité de Unión y Progreso, entró en Estambul para sofocar la rebelión del 31 de marzo. Según el artículo «Hareket Ordusu» de la Enciclopedia del Islam del TDV, el mando lo asumió Mahmud Şevket Pasha y la jefatura del estado mayor la ejerció el kolağası Mustafa Kemal. Tras breves enfrentamientos se restableció el orden en la ciudad.", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["Disolución de la última Cámara de Diputados otomana", "2b709269"], "d": ["Tras la ocupación oficial de Estambul por las fuerzas aliadas y el arresto de numerosos diputados, la Cámara de Diputados (Meclis-i Mebusan) quedó incapacitada para trabajar y fue disuelta oficialmente por voluntad de Mehmed VI. Según el artículo «Meclis-i Mebusan» de la Enciclopedia del Islam del TDV, esta disolución simbolizó el fin de hecho de la tradición parlamentaria constitucional otomana. Su clausura reforzó la necesidad de que se reuniera una nueva asamblea nacional en Ankara.", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["Apertura de la Gran Asamblea Nacional de Turquía", "6eab539d"], "d": ["Tras la disolución de la Cámara de Diputados de Estambul, los diputados se reunieron en Ankara y abrieron la Gran Asamblea Nacional de Turquía, y Mustafa Kemal Pasha fue elegido presidente de la asamblea. Según el artículo «Türkiye Büyük Millet Meclisi» de la Enciclopedia del Islam del TDV, la asamblea tuvo un carácter extraordinario, pues reunía en sí los poderes legislativo y ejecutivo. Esta apertura fue el punto de inflexión en que el centro político e institucional de la lucha nacional se trasladó a Ankara.", "805871d7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["Conquista de la fortaleza de İzvornik (Zvornik)", "657c465a"], "d": ["La fortaleza de İzvornik, a orillas del Drina, fue conquistada por los otomanos en 1460. Según la Enciclopedia del Islam del TDV, por su posición favorable desde el punto de vista administrativo y militar fue convertida primero en capital de un distrito (kaza), en 1480 en centro del sanjacado del mismo nombre y en 1491 fue fortificada con murallas de piedra, convirtiéndose en un importante centro administrativo y comercial con seis mezquitas, ocho tekkes y baños.", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["Muerte de Kasim Jan y ascenso al trono de Danyal Jan (Kanato de Kasimov)", "522fd0fd"], "d": ["Con la muerte, en 873/1468, de Kasim Jan, fundador del kanato, le sucedió su hijo Danyal; Danyal reinó hasta 1486.", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["Batalla naval de Diu: supremacía portuguesa en el océano Índico", "1778d347"], "d": ["La flota de Malik Ayaz, que gobernaba la región en nombre del Sultanato de Guyarat y contaba con apoyo mameluco, sufrió una grave derrota frente a Diu ante la flota del gobernador general portugués Francisco de Almeida, que intentaba establecer una base de abastecimiento en esas costas. Esta derrota dio a Portugal una supremacía naval duradera en el océano Índico y quebró el poder naval mameluco-guyaratí; se considera el comienzo del desequilibrio de fuerzas que forma el trasfondo de la lucha del mar Rojo y el océano Índico que los otomanos heredaron después de 1517 (defensa de Yeda, asedio de Diu de 1538).", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["Rebelión de Kalender Shah", "f60f6ca4"], "d": ["Por las dificultades financieras en Anatolia, el descontento con los nuevos arreglos administrativos y la influencia de la propaganda safávida, grandes tribus turcomanas como los Çiçekli, los Akça Koyunlu, los Masadlı y los Bozoklu, junto con grupos que quedaban de la anterior rebelión de Baba Zünnûn, se reunieron en torno a Kalender Shah y alcanzaron una fuerza de unos treinta mil hombres. Los rebeldes derrotaron primero al beylerbeyi de Rum; cuando el gran visir Makbul İbrâhim Pasha reunió tropas y prometió sus derechos, el apoyo a Kalender se desvaneció y la rebelión fue sofocada en las cercanías de Elbistan; Kalender Shah y Veli Dündar fueron muertos en junio de 1527.", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["Conquista de Shahrizor: toma de la fortaleza de Zalm", "4320d9b8"], "d": ["Durante la campaña de Najicheván de Kanuni, el beylerbeyi de Bagdad, Osman Pasha, había sido encargado de apoderarse de la región de Shahrizor; Baltacı Mehmed Pasha, que se convirtió en beylerbeyi de Bagdad a su muerte, sitió Zalm, la fortaleza central de la región, y la tomó el 22 de agosto de 1554 (23 de Ramazan 961). Así la cuenca de Shahrizor, en la vertiente occidental de los Zagros, entró en la administración otomana y se aseguró la conexión entre Bagdad y Kurdistán; la región fue convertida primero en sanjacado y entregada a Murad Bey. En 1563 el beylerbeyi Muzaffer Pasha construyó la fortaleza de Gülanber como nueva capital del eyalato; la fortaleza sería destruida en 1623 por orden de Shah Abbas y reconstruida en 1638 en tiempos de Hüsrev Pasha.", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["Conversión al cristianismo del soberano del Kanato de Kasimov y su destitución", "a1a8eeb9"], "d": ["El soberano al frente del kanato tomó el nombre de «Semen (Simeón)» y se hizo cristiano; los rusos, teniendo en cuenta la reacción de los súbditos musulmanes, lo apartaron del kanato. Poco después, este personaje fue proclamado por Iván el Terrible soberano nominal en Moscú con el título de «gran príncipe del zar y de Rusia» (1575): la intersección más llamativa entre el Kanato de Kasimov y el trono de Moscú.", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["Anexión del sanjacado de Fezzan a Trípoli de Berbería: Murzuk y la encrucijada de caravanas del Sáhara", "2e6554a4"], "d": ["Como resultado de la presión del beylerbeylicato de Trípoli de Berbería, Fezzan, encrucijada de caravanas del Sáhara, con capital en Murzuk, aceptó la sujeción otomana. Según el artículo «Fizan» de la Enciclopedia del Islam del TDV, la dinastía de los Evlâd-ı Muhammed, que gobernaba la región, quedó libre en sus asuntos internos con la condición de pagar impuestos regularmente; Fezzan fue organizado como un sanjacado dependiente del eyalato de Trípoli, tomado en 1551. Así el comercio de esclavos, oro y camellos de la línea Trípoli-Murzuk-Bornu pasó al control otomano. Esta administración indirecta pasaría en 1711 a manos de los Karamanlı y en 1842 a la organización directa de distritos (kaza).", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["Najicheván y Ordubad pasan a la administración otomana", "24d939b3"], "d": ["Tras la toma de Erevan en 1583 y su conversión en capital del beylerbeylicato, las fuerzas que descendieron hacia el sureste por el valle del Araxes incorporaron Najicheván y Ordubad a la administración otomana; las dos ciudades se convirtieron en sanjacados del recién fundado eyalato de Erevan. Según el artículo «Nahcıvan» de la Enciclopedia del Islam del TDV, durante esta guerra se estableció por primera vez en la ciudad una administración otomana duradera: en la campaña de Najicheván de 1553 la ciudad había sido tomada, pero solo saqueada y abandonada. Así se abrió el camino militar entre Erevan y Tabriz, y en septiembre del mismo año se pudo entrar en Tabriz. Shah Abbas recuperaría Najicheván en 1603.", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["Rebelión de Deli Hasan Pasha y su pacificación con el beylerbeylicato de Bosnia", "144f3f2d"], "d": ["Deli Hasan, hermano que se puso al frente del movimiento tras la muerte en 1602 del líder celalí Karayazıcı Abdülhalim, aprovechando la libertad de movimiento que las continuas guerras con Austria daban a los grupos celalíes, invadió Kütahya y marchó sobre Afyonkarahisar. En esta época en que el Estado se ocupaba a la vez de los frentes austríaco e iraní, el asunto se resolvió «con dulzura»: dándole a Deli Hasan el rango de pasha y el beylerbeylicato de Bosnia, el movimiento rebelde fue oficialmente terminado en 1603.", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["Toma de la ciudad de Kasimov por las fuerzas rusas, Uraz Muhammad Jan", "b3f0bd34"], "d": ["Como reflejo de la época de los Disturbios (Smuta) en Rusia, las fuerzas rusas sitiaron y tomaron la ciudad de Kasimov y pasaron a cuchillo a la mayor parte de su población. Uraz Muhammad, al frente del kanato, había sido señalado como objetivo por apoyar al Segundo Falso Dimitri; al año siguiente (1610) fue asesinado él mismo en una conspiración.", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["Pérdida de la fortaleza de Azak ante los cosacos del Don", "ba068b2f"], "d": ["Los cosacos del Don tomaron dos meses después la fortaleza de Azak, que habían sitiado el 21 de abril de 1637; la fortaleza, puerta nororiental del mar Negro y cerrojo del comercio del Don, salió por primera vez de manos otomanas. Según el artículo «Azak» de la Enciclopedia del Islam del TDV, los cosacos tomaron la fortaleza en 1637, resistieron en 1641 un gran asedio de tres meses al mando de Deli Hüseyin Pasha y solo la evacuaron en 1642 con la llegada del kan de Crimea Mehmed Giray. El Estado estaba entonces ocupado con el frente de Bagdad; la imposibilidad de conservar la fortaleza durante cinco años es la primera grieta en la condición del mar Negro de «lago otomano».", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["Recuperación de Lemnos y Samotracia", "c445553b"], "d": ["Tras la liberación de Bozcaada el 31 de agosto de 1657, Köprülü Mehmed Pasha dirigió la flota hacia el norte y recuperó Lemnos y Samotracia, que Venecia tenía en su poder desde hacía dieciséis meses. Según el artículo «Limni» de la Enciclopedia del Islam del TDV, la isla había pasado a manos de Venecia en julio de 1656 y fue recuperada en noviembre de 1657. Así el bloqueo veneciano a la entrada de los Dardanelos quedó completamente roto y la ruta del grano de Estambul volvió a estar asegurada; esta es la ganancia más concreta del primer año del gran visir, que había llegado con poderes extraordinarios.", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["Pérdida de Knin ante Venecia: cae la fortaleza fronteriza de Dalmacia tras 166 años", "252406b7"], "d": ["En la guerra abierta en múltiples frentes tras el desastre de Viena de 1683, las fuerzas venecianas avanzaron hacia el interior de Dalmacia. Knin, sitiada por el general de Dalmacia Girolamo Cornaro, fue entregada por el beylerbeyi Mehmed Pasha tras un asedio de doce días. Knin era la fortaleza clave de la línea fronteriza de Dalmacia, conquistada en 1522 por Gazi Hüsrev Bey y que permaneció 166 años en manos otomanas; su pérdida abrió en gran medida la región a Venecia.", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["Recuperación de Basora de la ocupación iraní", "5b10c5c1"], "d": ["Basora, que Sâdık Han, hermano de Kerim Han Zend, había tomado en 1776, fue evacuada cuando, tras la muerte de Kerim Han el 2 de marzo de 1779, comenzó en Irán la lucha por el trono; Sâdık Han regresó a Irán con la pretensión de reinar. Tras permanecer un breve tiempo en manos de la tribu de los Müntefik, la ciudad volvió a la administración otomana. El antiguo mütesellim Süleyman Ağa, regresado de Shiraz, pidió el gobierno de Basora y se convirtió, con el nombre de Büyük Süleyman Pasha, en gobernador de Basora, Bagdad y Shahrizor. El comercio del Golfo volvió al control otomano; durante los años de la ocupación una parte del comercio se había desplazado a Kuwait y desde 1778 también el correo del desierto se despachaba desde Kuwait.", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["Muerte de Timur Shah, ascenso al trono de Zaman Shah (Estado durrani)", "c3effdb2"], "d": ["Con la muerte de Timur Shah, que había consolidado internamente el país durante más de veinte años, los tres hermanos gobernadores de Kandahar, Herat y Kabul se disputaron el trono; Zaman Shah, gobernador de Kabul, que tenía en su poder la capital, se convirtió en shah el 20 de mayo de 1793. Esta crisis sucesoria es de hecho el comienzo del proceso de desintegración de la dinastía.", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa: fin del sistema tradicional del kapu en Hawái", "0b10e1d8"], "d": ["Seis meses después de la muerte de Kamehameha I, el nuevo rey Liholiho, con el apoyo de su madre Kaʻahumanu, quebrantó deliberadamente la prohibición de que hombres y mujeres comieran por separado (ʻaikapu). Este acto, conocido como «ʻAi Noa» (comida libre), puso fin oficialmente al sistema religioso-jurídico tradicional del kapu; los antiguos templos (heiau) de las islas fueron derribados en poco tiempo. Es la mayor ruptura religiosa y política anterior a la llegada de los misioneros occidentales (1820).", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["Protocolo de Londres: reconocimiento de la independencia de Grecia", "4c7b4b72"], "d": ["El protocolo firmado en Londres por Inglaterra, Francia y Rusia reconoció a Grecia como Estado INDEPENDIENTE, superando la autonomía prevista por el Tratado de Edirne. Disposiciones: la península de la Morea, el Ática y Eubea, así como las islas Cícladas, fueron cedidas al nuevo Estado; la frontera se trazó en la línea Arta-Volos; se acordó el pago de una indemnización al Estado otomano; la forma de gobierno del Estado se fijó como «monarquía independiente». Este es el PRIMER Estado independiente desgajado del imperio y estableció el modelo jurídico de las independencias balcánicas posteriores.", "e8fc6290"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["Abdullah ibn Rashid se apodera del emirato de Hail: fundación de la dinastía shammar (rashidí)", "fb513b8a"], "d": ["Cuando en 1818 las fuerzas de Mehmed Ali Pasha derribaron Dir'iyya, la región de Yabal Shammar salió del dominio saudí y el emirato quedó en manos de la familia Ibn Ali. Abdullah ibn Rashid, que apoyaba el restablecimiento del dominio otomano, ganó en 1835 la lucha que había emprendido con su hermano Ubeyd contra la familia Ibn Ali, se apoderó del emirato de Hail y estableció el dominio de la dinastía rashidí.", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["Se proclama la primera constitución escrita de Hawái", "401a8a1d"], "d": ["Se proclamó la primera constitución plenamente escrita del reino; este documento, que limitaba la autoridad del rey y creaba una asamblea representativa, convirtió a Hawái en una monarquía constitucional.", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["Constitución de la Bayoneta: se recortan los poderes del rey Kalākaua", "4953363b"], "d": ["Un grupo de milicia armada amenazó al rey Kalākaua y lo obligó a firmar una nueva constitución que recortaba en gran medida las atribuciones de la monarquía; el documento se conoce como «Constitución de la Bayoneta» (Bayonet Constitution) y puso de hecho el trono bajo el control de la élite de colonos blancos.", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["Muerte de George Tupou I y ascenso al trono de George Tupou II (Tonga)", "b56e2b32"], "d": ["Con la muerte del rey fundador George Tupou I, su bisnieto George Tupou II subió al trono; la ceremonia de coronación se celebró el 17 de marzo de 1893 en Nukuʻalofa.", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["Nueva Zelanda se convierte en el primer país autogobernado en conceder el voto a las mujeres", "0d277cde"], "d": ["Con la nueva Ley Electoral firmada por el gobernador Lord Glasgow, Nueva Zelanda se convirtió en el primer país autogobernado del mundo en conceder a las mujeres el derecho al voto en las elecciones parlamentarias.", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["Se proclama la República de Hawái", "4346bd5d"], "d": ["Los conspiradores que en 1893 derrocaron a la reina Liliuokalani convirtieron el gobierno provisional en una república formal; Sanford Dole fue proclamado presidente. Este régimen intermedio duró hasta la anexión por Estados Unidos en 1898.", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["Las fronteras de Nueva Zelanda se amplían para incluir las islas Cook y Niue", "d0370a33"], "d": ["Las fronteras de Nueva Zelanda se ampliaron para abarcar las islas Cook (Rarotonga, Aitutaki y las islas del sur, y las islas Cook del norte) y Niue; estas islas pasaron a ser territorio dependiente de Nueva Zelanda.", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["Muerte de George Tupou II y ascenso al trono de Sālote Tupou III (Tonga)", "a3084f3b"], "d": ["George Tupou II murió de tuberculosis; su hija de 18 años, Sālote, fue proclamada reina al día siguiente y la ceremonia de coronación se celebró el 11 de octubre de 1918.", "a63672b5"]},
"OLAYLAR_EK8:1920-04-26:0":{"b": ["Se proclama la República Popular de Joresm", "0a6b79f9"], "d": ["Tras el derrocamiento del kan de Jiva después de la Revolución de Octubre de 1917, se proclamó la República Popular de Joresm.", "1934b071"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["Tratado de Sèvres: texto de reparto del imperio", "64980d7b"], "d": ["Texto firmado por el gobierno otomano con las potencias aliadas que liquidaba de hecho el imperio. Disposiciones: Tracia oriental y la región de Esmirna a Grecia; se previeron una Armenia independiente y un Kurdistán autónomo en Anatolia oriental; Siria quedó como mandato de Francia, Irak y Palestina como mandato de Inglaterra; los Estrechos fueron cedidos a una comisión internacional; el ejército fue reducido a 50.700 hombres, se restablecieron las capitulaciones y las finanzas se pusieron bajo control aliado. La Gran Asamblea Nacional de Ankara NO RECONOCIÓ EN ABSOLUTO el tratado y declaró traidores a la patria a sus firmantes; el texto no entró en vigor y en su lugar vino Lausana en 1923. Esa es la razón de que no tenga correspondencia en el mapa: Sèvres no se aplicó jamás jurídicamente.", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["El Ejército Rojo entra en la ciudad de Bujará: el último emir, Alim Jan, es apartado del trono", "f8f5bfcf"], "d": ["El Ejército Rojo entró en la ciudad de Bujará el 2 de septiembre de 1920 y el último emir mangit, Alim Jan, fue apartado del trono. El emir se retiró a Dusambé, en el este del país, y desde allí dirigió durante medio año la lucha contra los soviéticos; el Ejército Rojo tomó Dusambé el 21 de febrero de 1921 y el emir pasó más al este y de allí a Afganistán. El emirato fue abolido oficialmente el 6 de octubre de 1920 (véase República Popular Soviética de Bujará).", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["Se proclama la República Popular Soviética de Bujará", "ef579627"], "d": ["Tras la destrucción del Emirato de Bujará por el Ejército Rojo el 28-31 de agosto de 1920 y la huida del emir Alim Jan a Bujará oriental, se proclamó la República Popular Soviética de Bujará bajo la presidencia de Faizullá Joyayev.", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["La República Popular de Tannu Tuvá proclama su independencia", "8710ea3d"], "d": ["Se proclamó la independencia bajo la dirección del Partido Revolucionario Popular de Tuvá; el primer artículo de la primera constitución establecía que el Estado actuaba «en las relaciones internacionales bajo el protectorado de la Rusia Soviética».", "3c6cec2c"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["Se adopta la nueva constitución de la República Popular Soviética de Bujará", "fb17bf39"], "d": ["Se adoptó una nueva constitución que, a diferencia de la constitución rusa de 1918, permitía la propiedad privada de la tierra y de los medios de producción y concedía derecho de voto también a los no proletarios (con excepción de los parientes del emir derrocado y los grandes terratenientes).", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["Transformación en la República Socialista Soviética de Joresm", "14a1d26f"], "d": ["El país cambió su nombre y su estatuto y se convirtió en la República Socialista Soviética de Joresm; la estructura administrativa y jurídica fue reorganizada según el sistema soviético.", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["El gobierno de Tannu Tuvá entra efectivamente en funciones", "22ea1516"], "d": ["El gobierno formado tras la primera reunión del partido en febrero de 1922 entró efectivamente en funciones.", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["Se reúne el primer Gran Jural de Tannu Tuvá", "80fe15f2"], "d": ["Se reunió el primer Gran Jural (Asamblea Popular) del país; esta es la primera gran reunión representativa en el proceso de institucionalización del Estado.", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["Fin de la RSS de Joresm y de la República Popular Soviética de Bujará por la delimitación nacional: fundación de las RSS de Uzbekistán y Turkmenistán", "e8c8ab4f"], "d": ["Por la decisión soviética de «delimitación nacional» (natsionalno-territorialnoe razmezhevanie), la República Socialista Soviética de Joresm y la República Popular Soviética de Bujará fueron abolidas; sus territorios se repartieron entre las recién fundadas Repúblicas Socialistas Soviéticas de Uzbekistán y Turkmenistán (el este de Jiva a Uzbekistán, el oeste a Turkmenistán). Artículo `harizm` del TDV: «1924’te Hîve Hanlığı’nın doğu kesimleri Özbekistan Sovyet Sosyalist Cumhuriyeti’ne, batı tarafı da Türkmenistan Sovyet Sosyalist Cumhuriyeti’ne bırakıldı.» — da solo el año.", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["Venta de Alanya al sultán mameluco Barsbay", "c8bd35f2"], "d": ["Alanya (Alâiye), tomada en 1293 por el bey Karamanoğlu Mecdüddin Mahmud, se había convertido en un beylicato aparte gobernado por una rama de los Karamanoğulları; Ibn Battuta registra en 1333 que la administración estaba en manos del Karamanoğlu Yusuf Bey. Karaman b. Savcı Bey vendió la ciudad en 1427 al sultán mameluco Barsbay por cinco mil monedas de oro y Alanya pasó a la administración mameluca. Este puerto clave del Mediterráneo se convirtió así en un obstáculo en manos mamelucas en el camino otomano hacia el sur; cuando Gedik Ahmed Pasha la sitió en 1471, el último bey, Kılıcarslan, entregó la ciudad.", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["Toma de Tabarka a los genoveses: fin de la concesión del coral de los Lomellini", "b1f33eb5"], "d": ["Tras el acuerdo de Carlos V con el bey de Túnez en 1544, la familia genovesa de los Lomellini se había establecido en la isla de Tabarka y durante doscientos años conservó la concesión del coral; la isla permaneció como puesto comercial cristiano en medio de la Túnez otomana. Ali Pasha, de la dinastía husaynida, al enterarse del intento de la familia de deshacerse de la isla, envió fuerzas y la tomó el 12 de junio de 1741; unos mil quinientos cristianos fueron trasladados a Túnez. Desde esta fecha Tabarka pasó a la administración de la odjak de Túnez.", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["Batalla de las Pirámides y toma de El Cairo por los franceses", "3ddd6b96"], "d": ["Napoleón marchó hacia el sur a lo largo del Nilo desde Alejandría y el 21 de julio de 1798 se enfrentó en Imbaba, frente a Guiza, a la caballería mameluca de Murad Bey. La infantería francesa en formación de cuadro rompió las cargas de caballería; el ejército mameluco se dispersó y El Cairo se rindió dos días después sin resistencia. Murad Bey se retiró al Alto Egipto e İbrâhim Bey a Siria. Los franceses establecieron un diván en El Cairo e intentaron llevar la administración por medio de los ulemas; estallaron dos grandes levantamientos en El Cairo, en octubre de 1798 y en marzo de 1800.", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["Asedio de San Juan de Acre por Napoleón: detención de la campaña de Siria", "d2a947ad"], "d": ["Napoleón, que quería dispersar las fuerzas que los otomanos preparaban para recuperar Egipto, marchó a Siria a comienzos de 1799; tomó El Arish el 18 de febrero y Jafa en marzo, y el 18 de marzo de 1799 sitió Acre. La defensa de Cezzâr Ahmed Pasha y el apoyo desde el mar del almirante inglés Sidney Smith rechazaron el asedio durante dos meses; como la artillería de sitio fue capturada en el mar, no se pudieron franquear las murallas. Napoleón se retiró en mayo y esta derrota fue el punto extremo de la ocupación francesa.", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["Fundación del Estado del emir Abdelkader: centralización de la resistencia en Argelia occidental", "9e482383"], "d": ["La resistencia, dispersa tras la caída de Argel, se agrupó en torno al joven Abdelkader, hijo del jeque qadirí Muhyiddin; el 22 de noviembre de 1832, cerca de Mascara, los jefes tribales le juraron fidelidad con el título de «emir de los creyentes». La estructura que creó no era una alianza tribal sino un Estado regular: tenía casa de moneda, fábrica de pólvora, régimen de impuestos y una capital en Tagdempt. Francia reconoció oficialmente su soberanía con el Tratado de la Tafna de 1837. Abdelkader no se acogió a los otomanos sino a la suzeranía del sultán de Marruecos Abderramán; es decir, estas tierras no son súbditas otomanas después de 1832. Se rindió el 23 de diciembre de 1847 y el Estado otomano declaró ese mismo año el fin de sus derechos sobre Argelia.", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["Caída de Constantina: fin del beylicato de Argelia oriental", "159fed36"], "d": ["Tras la caída de Argel en 1830, el beylerbeylicato oriental no se disolvió: el último bey, Ahmed, continuó su administración en Constantina y declaró que actuaba en nombre de los otomanos. La primera expedición francesa de 1836 terminó en desastre; la segunda sitió la ciudad el 6 de octubre de 1837, el comandante Damrémont murió por fuego de cañón el 12 de octubre y el 13 de octubre, franqueadas las murallas, la ciudad fue tomada calle por calle. Ahmed Bey se retiró a las montañas y solo se rindió en 1848. Esta fecha es el fin de hecho de la administración otomano-turca de trescientos años en el este de Argelia.", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["Conquista de la región de Taka y fundación de Kassala", "cc3e0631"], "d": ["Ahmed Pasha Abu Widan, gobernante de Sudán, sometió en 1840 a la administración egipcia la región de Taka, entre los ríos Atbara y Gash, y fundó la ciudad de Kassala como cuartel militar. La ciudad se convirtió en centro de una mudiriyya que controlaba la ruta de caravanas entre Sennar y Suakin y la franja fronteriza abisinia.", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["Ocupación francesa de Mascara: pérdida de la capital de Abdelkader", "bd363c05"], "d": ["Con la llegada de Bugeaud al gobierno general en 1841, la estrategia francesa cambió: en lugar de mantenerse en la costa, ocupar una por una las ciudades del interior. Las columnas móviles que partieron de Orán, Mostaganem y Medea tomaron los centros del Estado regular de Abdelkader; la más importante era Mascara, auténtica capital con su casa de moneda, su fábrica de pólvora y sus graneros. A partir de entonces el emir renunció a establecer un centro fijo y convirtió su ejército en un campamento nómada llamado «smala».", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["Ocupación del valle del Chelif y de Tenes: fundación de Orléansville", "e1eeeb68"], "d": ["Para poder perseguir a Abdelkader, los franceses fundaron en abril de 1843 en medio del valle del Chelif una nueva ciudad llamada Orléansville; ese mismo año fue ocupado también el puerto costero de Tenes. Así el corredor interior entre Argel y Orán pasó al control francés y la resistencia en las montañas del Dahra quedó cercada. El 16 de mayo del mismo año el campamento nómada de Abdelkader, la «smala», fue hallado por casualidad y dispersado.", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["Fundación del campamento fortificado de Sidi Bel Abbès", "fb33ec29"], "d": ["El 12 de junio de 1843 Bugeaud dio al general Bedeau la orden de establecer en Sidi Bel Abbès un campamento fortificado con foso y murallas; la construcción comenzó el 18 de junio y en noviembre del mismo año se instaló allí un batallón de la Legión Extranjera. El campamento se convirtió en una base permanente que controlaba la llanura interior entre Orán y Tremecén.", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["La franja fronteriza de Nedroma y Marruecos pasa al control francés", "61d821f3"], "d": ["Tras la retirada de Abdelkader a Marruecos en 1843, Nedroma, al noroeste de Tremecén, y la costa de Trara pasaron al control francés. La batalla de Isly, el 14 de agosto de 1844, derrotó al ejército marroquí, y la frontera entre los dos países se trazó con la Convención de Lalla Maghnia, del 18 de marzo de 1845; Nedroma quedó del lado argelino de esta línea.", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["Caída de Laghouat: apertura de la puerta del Sáhara", "b161b32c"], "d": ["El general Pélissier sitió Laghouat con una fuerza de seis mil hombres el 21 de noviembre de 1852 y el 4 de diciembre la ciudad cayó en un sangriento asalto. Laghouat era la ciudad oasis que controlaba el paso entre el Tell y el Sáhara; su caída abrió el avance francés a las rutas de caravanas del desierto y preparó que la confederación del Mzab quedara sujeta a tributo en el plazo de un año.", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["Anexión de la región de Bogos (Keren) a Egipto", "b2ab83ce"], "d": ["Werner Munzinger Pasha, gobernador de la provincia de «Sudán Oriental y Costa del Mar Rojo» que el jedive İsmâil estableció en la costa occidental del mar Rojo, anexó a Egipto en 1872 la región de Bogos, habitada por el pueblo bilen, y su centro Keren. Este fue el avance más duradero de Egipto en el borde de la meseta abisinia y dio comienzo a una disputa fronteriza de doce años con Abisinia.", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["Anexión del Sultanato de Darfur a Egipto: Zubayr Pasha entra en El Fasher", "f41268ed"], "d": ["Zubayr Rahmet Pasha, fortalecido por el comercio de marfil y esclavos, con tropas equipadas con fusiles Remington dispersó al ejército fur en Menawashi el 25 de octubre de 1874; el sultán Ibrahim murió en la batalla. Zubayr entró en El Fasher el 2 de noviembre sin combate y el reinado de la dinastía keyra, que duraba desde 1603, terminó de hecho. Darfur se incorporó así a las provincias del Sudán del Egipto de Mehmed Ali; pero la resistencia de la familia keyra en las montañas continuó hasta 1891.", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["Anexión de los oasis del Mzab (Ghardaïa)", "9372959f"], "d": ["Las ciudades ibadíes del Mzab habían aceptado en 1852 pagar tributo a Francia pero habían conservado su administración interna; treinta años después, en 1882, la región fue incorporada directamente al territorio francés y Ghardaïa fue puesta bajo administración militar. Así terminó también jurídicamente la última franja autónoma del Sáhara septentrional.", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["Bombardeo de Alejandría y desembarco británico", "18d57bf8"], "d": ["Cuando el movimiento de oficiales encabezado por Urabi Pasha puso bajo control al jedive, Inglaterra intervino con el pretexto de la seguridad de la ruta de Suez. La flota del almirante Seymour bombardeó las baterías costeras de Alejandría los días 11-12 de julio de 1882; tras el incendio y el saqueo que estallaron en la ciudad, las tropas británicas desembarcaron el 15 de julio. El Estado otomano no pudo impedir esta operación en una provincia sobre la que era jurídicamente soberano y dejó también sin respuesta la invitación a participar en la intervención. Así se dio el primer paso de una ocupación que duraría treinta y dos años.", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["Batalla de Tel el-Kebir: disolución del ejército de Urabi", "8e38fecf"], "d": ["Wolseley desembarcó sus fuerzas en Ismailía por el canal de Suez y, marchando por el desierto, asaltó por sorpresa las trincheras egipcias de Tel el-Kebir al amanecer del 13 de septiembre de 1882; la batalla terminó en una hora. Urabi se rindió al día siguiente y la caballería británica entró en El Cairo ese mismo día. Desde esta fecha las finanzas, el ejército y los asuntos exteriores de Egipto pasaron de hecho al control británico; la soberanía otomana, en cambio, continuó jurídicamente hasta 1914.", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["Convención de La Marsa: culminación del protectorado de Túnez", "71338640"], "d": ["El Tratado de Bardo (Kasrüssaîd) del 12 de mayo de 1881 había dejado los asuntos exteriores de Túnez a Francia pero la administración interna al bey; la Convención de La Marsa, firmada dos años después, el 8 de junio de 1883, puso también las reformas financieras y administrativas bajo control francés y completó el protectorado. El Estado otomano mantuvo su pretensión de soberanía sobre Túnez y nunca reconoció la ocupación, pero no pudo dar ninguna respuesta efectiva. Así Túnez, odjak otomana desde 1574, pasó oficialmente al protectorado francés.", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["Desastre de Shaykan: destrucción del ejército de Hicks Pasha", "a0e08986"], "d": ["Hicks Pasha, oficial británico retirado que mandaba una fuerza egipcia de unos diez mil hombres enviada desde El Cairo, avanzaba por el desierto de Kordofán sin agua y sin guías cuando el 5 de noviembre de 1883 fue cercado en Shaykan por las fuerzas del Mahdi, y el ejército fue aniquilado casi por completo. Este desastre rompió la columna vertebral de la administración egipcia en Sudán: en un mes se rindieron Darfur y Bahr el-Ghazal y todo Kordofán pasó al Mahdi. De aquí arranca el camino hacia la caída de Jartum.", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["Darfur pasa a las fuerzas del Mahdi: rendición de Slatin Pasha", "6d8992d4"], "d": ["Slatin Pasha, gobernador general de Darfur, combatía desde 1882 el levantamiento mahdista de la tribu de los Rizeigat; pensando que sus soldados achacaban sus derrotas a que él era cristiano, se hizo musulmán abiertamente en 1883 y tomó el nombre de Abdelkader. Tras la destrucción del ejército de Hicks Pasha en Kordofán en noviembre de 1883, la resistencia perdió sentido y el 23 de diciembre de 1883 se rindió al emir Madibbo. Los pequeños puestos egipcios de Darfur siguieron pronto el mismo camino; terminó la administración turco-egipcia de diez años.", "85dcfe97"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["Zeila y la costa de Somalia pasan a la administración británica", "1d649502"], "d": ["Cuando el levantamiento del Mahdi derrumbó las guarniciones egipcias de Sudán y del mar Rojo, El Cairo se vio obligado a evacuar sus lejanos puestos en la costa abisinia. La administración británica de Adén desembarcó tropas en Zeila y Berbera en 1884; al año siguiente se firmaron tratados de protección con los jefes tribales somalíes y se fundó la Somalilandia Británica. Zeila, vinculada al eyalato de Abisinia desde 1559, se perdió así.", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["Rendición de la guarnición de El Fasher a los mahdistas", "68f0760d"], "d": ["Incluso después de la rendición de Slatin el 23 de diciembre de 1883, la guarnición egipcia de la fortaleza de El Fasher resistió. La guarnición, que perdió los pozos en un asedio de siete días, se rindió el 15 de enero de 1884; se entregaron las armas y la fortaleza pasó a los mahdistas.", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["Tratado de Hewett (Adwa): cesión de Bogos a Abisinia", "0de1b701"], "d": ["Cuando el levantamiento del Mahdi cercó las guarniciones egipcias en Sudán, Inglaterra firmó el 3 de junio de 1884 en Adwa un tratado con Yohannes IV para obtener la ayuda de Abisinia. El segundo artículo del tratado devolvía Bogos a Abisinia, a cambio de lo cual Abisinia facilitaría la evacuación de las guarniciones sitiadas por Massawa. Keren salió así de la administración egipcia de doce años; cinco años después la región se incorporaría a la Eritrea italiana.", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["Recuperación de Dongola: comienzo de la campaña a lo largo del Nilo", "f63aa14f"], "d": ["Tras la derrota de los italianos en Adwa, Inglaterra hizo marchar al ejército egipcio, al mando de Kitchener, hacia el sur a lo largo del Nilo. A medida que el ferrocarril avanzaba por el desierto se resolvió el problema del abastecimiento y la provincia de Dongola fue recuperada el 23 de septiembre de 1896. Aquí terminó la administración mahdista de once años; la campaña continuaría dos años más hasta alcanzar Omdurmán.", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["Batalla de Omdurmán: destrucción del Estado mahdista", "28dff7b2"], "d": ["El ejército anglo-egipcio de Kitchener, equipado con artillería y ametralladoras, dispersó en pocas horas, el 2 de septiembre de 1898 ante Omdurmán, las fuerzas del califa Abdullahi al-Taaishi. Al día siguiente se entró en Jartum y se izó la bandera en el palacio donde Gordon había sido muerto trece años antes. Cayó la capital del Estado mahdista; el califa fue muerto a finales de 1899 en una operación de persecución. La soberanía efectiva cambia de manos en esta fecha; el 19 de enero de 1899 es en cambio el tratado que establece el marco jurídico de la administración.", "ae944d9d"]},
"OLAYLAR_EK9:1899-01-19:0":{"b": ["Acuerdo de Condominio: administración conjunta anglo-egipcia de Sudán", "8033c688"], "d": ["El tratado firmado en El Cairo cuatro meses después de Omdurmán sometió Sudán a la administración conjunta de los dos Estados con el nombre de «Sudán anglo-egipcio»: se izarían las dos banderas juntas y el gobernador general sería nombrado por el jedive con el consentimiento de Inglaterra. En la práctica la administración estaba enteramente en manos de los ingleses. El Estado otomano, alegando que sus derechos sobre Sudán le pertenecían a través de Egipto, no fue parte del tratado y no lo reconoció; pero de hecho quedó al margen.", "c642933f"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["Desembarco italiano en Tobruk: primera ocupación en Trípoli de Berbería", "44780018"], "d": ["Italia declaró la guerra el 29 de septiembre de 1911 y su flota bloqueó la costa los días 25-26 de septiembre. La primera operación terrestre se realizó el 8 de octubre contra Tobruk: la pequeña guarnición otomana se retiró al interior y el puerto fue ocupado sin combate. Tobruk era el puerto otomano más cercano a la frontera egipcia; su caída abrió el flanco oriental de Barca y facilitó la marcha de las fuerzas italianas hacia el oeste a lo largo de la costa.", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["Rendición de la ciudad de Trípoli a los italianos", "785091ad"], "d": ["Trípoli se rindió el 9 de octubre de 1911 tras tres días de bombardeo. Las fuerzas otomanas, en lugar de defender la ciudad, prefirieron retirarse a Aziziye y Garyan y organizar la resistencia en el interior; esta resistencia, en la que participaron Enver y Mustafa Kemal Bey, mantuvo a los italianos confinados en la franja costera hasta el final de la guerra. Es decir, aunque la ciudad cayó, el interior de la provincia siguió bajo control otomano.", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["Pérdida de Derna por el desembarco italiano", "f014c741"], "d": ["Después de Tobruk le tocó el turno a Derna, el segundo puerto de Barca; la ciudad fue ocupada el 16 de octubre de 1911. La meseta alrededor de Derna era la región donde la cofradía senusí era más densa, y los muyahidines reunidos por la llamada a la yihad del jeque Ahmed Şerîf mantuvieron a los italianos cercados en torno al puerto. La ocupación quedó limitada a la ciudad y nunca pudo extenderse al interior.", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["Desembarco italiano en Bengasi: pérdida del centro del sanjacado de Barca", "f9183c40"], "d": ["Bengasi, capital de Barca, fue ocupada el 21 de octubre de 1911 con el cuarto y más importante desembarco en la costa. Así, tres semanas después de la declaración de guerra, Italia tenía en su poder todos los grandes puertos de la provincia de Trípoli de Berbería (Trípoli, Tobruk, Derna, Bengasi); pero no pudo penetrar en el interior de ninguno. El año restante de la guerra transcurrió en embestidas infructuosas hacia el interior desde estos cuatro puntos de la costa.", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["Decreto de anexión unilateral de Italia", "cfe3f9c2"], "d": ["Italia, mientras la guerra continuaba, promulgó el 5 de noviembre de 1911 un decreto y declaró que anexionaba Trípoli de Berbería y Barca. El Estado otomano no lo reconoció y la guerra duró un año más; la anexión solo adquirió validez jurídica con el Tratado de Ouchy del 18 de octubre de 1912. Por eso el decreto no cambia el color otomano en el mapa: la titularidad jurídica es otomana hasta 1912, y el control italiano se muestra como ocupación rayada.", "23668758"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Toma de Köprühisar y preparativos para la fundación de Yenişehir", "39abff03"], "d": ["Tras la caída de las fortalezas de paso entre Bursa e İznik, se sentaron las bases del cuartel avanzado desde el que se pondría bajo asedio a ambas ciudades.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Fundación de Yenişehir", "d3275837"], "d": ["Se estableció el primer asentamiento-guarnición otomano regular, para dirigir los asedios de Bursa e İznik; Orhan Gazi nació allí.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Primer asedio de İznik y conquista de Marmaracık", "cdca2349"], "d": ["İznik fue sitiada por primera vez pero no pudo ser tomada (la conquista definitiva fue en 1331); la fortaleza cercana de Marmaracık fue tomada en esta ocasión.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Campaña de la Compañía Catalana en Anatolia", "4fd940d5"], "d": ["Aunque la compañía catalana contratada por Bizancio para detener el avance turco obtuvo éxitos pasajeros, no resultó duradera; con su retirada se aceleró el avance de los beylicatos fronterizos.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal se hace musulmán y se une a los otomanos", "ca0d86e1"], "d": ["El tekfur de Harmankaya, Köse Mihal, se hizo musulmán y se unió a Osman Gazi con su fortaleza y sus hombres; fue el primer comandante otomano de origen bizantino.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey asume la administración de hecho", "6dadbefc"], "d": ["Debido a la vejez y la enfermedad de Osman Gazi, la dirección y el gobierno de hecho del asedio de Bursa y de las campañas pasaron a su hijo Orhan Bey (la ascensión oficial al trono es en 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-01-01:0":{"b": ["Bloqueo del puerto de Mudanya", "9aa4520c"], "d": ["Al cortarse el puerto que abastecía a Bursa por mar, se abrió el último acto del largo asedio.", "97d6f814"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Toma de Mudanya", "0a623368"], "d": ["Fue tomado Mudanya, el puerto de Bursa, y quedó cortada la conexión de la ciudad con el mar; el asedio de Bursa entró en su fase de estrangulamiento.", "c13020d5"]},
"OLAYLAR_EK:1323-01-01:0":{"b": ["Incorporación de Yalova y Karamürsel", "133cb07a"], "d": ["Para completar el asedio de Bursa se tomaron las localidades portuarias de la costa sur del golfo.", "6588050d"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Conquista de Akyazı y de la isla de İmralı", "d041b0c8"], "d": ["Se tomó Akyazı, al norte del Sakarya; con la toma de la isla de İmralı, los otomanos pasaron por primera vez a ser vecinos de la isla de Mármara.", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["Conquista de Gemlik (Kios) y Armutlu", "682d3bac"], "d": ["Cortada también la última conexión marítima de Bursa, la ciudad quedó preparada para la rendición de 1326.", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca tomó Kandıra y sus alrededores", "341bb97e"], "d": ["Akça Koca, uno de los beyes fronterizos de Orhan Gazi, mientras efectuaba incursiones en la región de İzmit desde su cuartel general al oeste del lago Sapanca, tomó Kandıra y sus alrededores hacia 1326. İzmit estaba aún en manos bizantinas; la ciudad caería solo en 1337.", "ed042ad1"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca tomó Aydos y la fortaleza de Samandıra", "ce4daa8a"], "d": ["Tras la toma de Kandıra, Akça Koca, junto con Konuralp y Gazi Abdurrahman, tomó la fortaleza de Aydos, cerca de Kartal, y luego la fortaleza de Samandıra, al norte de aquella; la región de Samandıra le fue dada como propiedad. Akça Koca murió en 1328 cerca de Kandıra; el beylicato fronterizo de la región fue dado al príncipe Murad.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Alianza otomano-aydínida-saruhánida", "9df6bb74"], "d": ["Los tres beylicatos actuaron conjuntamente contra Bizancio; la flota de Umur Bey, de los Aydınoğlu, desgastó a Bizancio en un segundo frente con sus incursiones en las costas de Tracia.", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Matrimonio de Orhan Gazi con Teodora: alianza con Bizancio", "9b67a590"], "d": ["Orhan Gazi, que apoyaba a Cantacuceno en la lucha por el trono bizantino, se casó con la hija de este, Teodora; esta alianza permitió a las fuerzas otomanas conocer de cerca Rumelia.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Toma de Ankara", "49bf1f6d"], "d": ["Ankara, bajo administración ahí (de los ahíes), pasó a la administración otomana; se abrió el camino de Anatolia central. Otros lugares incorporados en la misma fecha: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Avance en Tracia en tiempos de Süleyman Pachá: Malkara, İpsala y Tekirdağ", "fb31cf02"], "d": ["Tras establecer la cabeza de puente en Galípoli, Süleyman Pachá salió hacia el norte desde la península y fue tomando paso a paso la llanura entre la costa del Mármara y la desembocadura del Maritsa. Malkara, İpsala y Rodosçuk (Tekirdağ) formaron así un corredor ininterrumpido que unía Galípoli con el valle del Maritsa. Sin establecer este corredor no se podía marchar sobre Adrianópolis; el avance, detenido por la muerte repentina del príncipe en 1357, lo continuarían Lala Şahin y Hacı İlbey.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Secuestro del príncipe Halil", "b52ac3d7"], "d": ["Halil, el hijo menor de Orhan Gazi, fue secuestrado por piratas de Foça; la crisis del rescate ocupó durante años las relaciones otomano-bizantinas.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Corte de las vías de socorro de Adrianópolis: las fortalezas de Çorlu, Lüleburgaz, Babaeski y Keşan", "8e8ad485"], "d": ["El príncipe Murad, que reanudó las operaciones de conquista tras el rescate de Halil, envió a los akıncı hasta las inmediaciones de Constantinopla para aislar Adrianópolis de la ayuda que pudiera llegar del exterior. Se tomaron las fortalezas de Çorlu, Lüleburgaz y Babaeski en el camino Constantinopla-Adrianópolis y Keşan, en la encrucijada de caminos del sur de Tracia. La rendición de Adrianópolis llegó una vez completado este anillo de asedio.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Toma de Dimetoka — apertura del valle del Maritsa", "b59aee83"], "d": ["Fue tomada Dimetoka, fortaleza clave del valle del Maritsa; así se abrió el camino hacia la conquista de Adrianópolis. No era posible marchar sobre Adrianópolis sin completar el corredor que se extiende hacia el norte desde Galípoli, por lo que esta fortaleza precede a Adrianópolis en el orden de las conquistas de Rumelia. La ciudad fue durante algún tiempo el cuartel general de los sultanes en Rumelia. Las fuerzas que tomaron Dimetoka pusieron luego bajo control, junto con pequeñas fortalezas como Kuleli Burgaz (Pythion), toda la región del Maritsa medio.", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Pérdida de Galípoli (cruzada de Saboya)", "00e7e415"], "d": ["La flota de Amadeo de Saboya, primo del emperador bizantino, tomó Galípoli y la entregó a Bizancio; la cabeza de puente otomana en Rumelia fue gobernada durante diez años desde la orilla opuesta del estrecho. Otros asentamientos perdidos en la misma fecha: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Batalla de Çirmen — control del valle del Maritsa", "cd738d8d"], "d": ["El ejército de los príncipes serbios fue dispersado en un ataque nocturno; los beyes locales serbios y búlgaros de Macedonia y los Ródope empezaron uno a uno a pagar tributo a los otomanos — no una conquista directa, sino el comienzo de una oleada de vasallaje. En la tradición otomana esta batalla se narra además con el nombre de «Sırpsındığı» y como el ataque nocturno que Hacı İlbey llevó a cabo en el año 1364 contra el ejército cruzado que venía a recuperar Edirne; el TDV señala que esa fecha es errónea y que ambos relatos pertenecen a la misma batalla.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Conquista de Filibe y Eski Zağra", "e780c9ae"], "d": ["Fueron tomadas Filibe, en el alto valle del Maritsa, y Eski Zağra, al norte de ella; el zarato búlgaro quedó sujeto a tributo. La ruta de Tatarpazarcığı e İhtiman, entre Filibe y Sofía, quedó en manos de los beyes locales que se habían hecho vasallos tras Çirmen.", "b8131db8"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Bizancio vasallo: Juan V en el ejército de Murad I (consecuencia de la victoria de Çirmen de 1371)", "13ffe568"], "d": ["Según el TDV, tras la victoria de Çirmen (Maritsa) del 26 de septiembre de 1371, el Imperio bizantino había reconocido la soberanía otomana y había pasado a ser un Estado vasallo, al aceptar pagar tributo y servir en el ejército otomano. El emperador Juan V se unió con esta obligación al ejército de Murad I en 1373; su hijo Andrónico IV, a quien había dejado entonces en Constantinopla, se rebeló contra su padre junto con el príncipe Savcı Bey, que estaba en Bursa.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Recuperación de Galípoli", "5f96c0a5"], "d": ["Andrónico IV, que obtuvo el apoyo otomano en la disputa por el trono bizantino, devolvió Galípoli a cambio; el puente entre Rumelia y Anatolia fue restablecido. Otros lugares incorporados en la misma fecha: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["La dote de Germiyan: incorporación de Kütahya", "d6a6fe61"], "d": ["En el matrimonio de Devletşah Hatun, hija de Germiyanoğlu Süleyman Şah, con Bayezid el Rayo, Kütahya, Simav, Tavşanlı y Eğrigöz pasaron a los otomanos como dote — el ejemplo clásico de expansión sin guerra. Otros lugares incorporados en la misma fecha: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Compra de la provincia de Hamîd: incorporación de Isparta", "4a1b6047"], "d": ["Hamîdoğlu Hüseyin Bey vendió a Murad I, a cambio de dinero en efectivo, una parte de su beylicato (Akşehir-Beyşehir-Isparta); el resto de la provincia de Hamid sería anexionado por el Rayo en 1391.", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Conquista de Serez", "d4d28b60"], "d": ["Fue tomada Serez, la llave de Macedonia oriental; Salónica quedó dentro del cerco de asedio. La línea Köstendil-Petriç-Nevrokop-Drama, entre Sofía y Serez, no estaba aún directamente incorporada en esta fecha; pasó sucesivamente a ser vasalla entre la década de 1370 y 1383 y a administración directa después de 1383.", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Conquista de Sofía", "96d5f01f"], "d": ["Se tomó el control de los pasos occidentales de los Balcanes; como en esta fecha Serez estaba ya en poder otomano desde 1383, los territorios de Tracia y Macedonia formaban un conjunto ininterrumpido.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Conquista de Niš", "77f5d632"], "d": ["Con la toma de Niš, llave del valle del Morava, el despotado serbio quedó directamente amenazado.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Primera rendición de Salónica", "96010ee9"], "d": ["Tras un largo bloqueo la ciudad se rindió (en 1403 sería devuelta a Bizancio y en 1430 conquistada definitivamente). Otros lugares incorporados en la misma fecha: Kavala.", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Ahidname otomano-genovés — renovación del tratado de 1352", "be11d17a"], "d": ["Con los embajadores genoveses llegados de Pera se renovó el acuerdo comercial de 1352, procedente de la época de Orhan Gazi; se fijaron de nuevo los impuestos entre los dos Estados, el trato a los cautivos y el libre comercio. Se considera el primer ahidname oficialmente conocido de amistad y comercio entre otomanos y genoveses — no una alianza militar, sino un acuerdo puramente comercial.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Campaña de Çandarlı Ali Pachá en Bulgaria: toma de Şumnu y Rusçuk", "2781c3a9"], "d": ["Las fortalezas del zarato búlgaro a orillas del Danubio fueron recibidas en rendición en una sola campaña; no debe confundirse con la derrota sufrida ese mismo año en Bileća, en Bosnia — fue un éxito simultáneo en un frente distinto. Tırnova y Vidin eran los últimos centros búlgaros que aún se mantenían.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Derrota de Bileća", "89ba0a64"], "d": ["La fuerza de akıncı enviada contra Bosnia cayó en una emboscada en Bileća y fue aniquilada; este primer gran revés balcánico dio ánimos a la alianza que conduciría a Kosovo.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Anexión de los beylicatos de Anatolia occidental: Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Los tres beylicatos se incorporaron de una sola vez: Manisa, centro de los Saruhanoğlu; Aydın, centro de los Aydınoğlu (incluida la ciudadela alta de İzmir, pero con el puerto y la ciudadela baja todavía en poder de los caballeros de San Juan, hasta 1402); Muğla-Milas, centro de los Menteşeoğlu, incluida la franja costera Datça-Bodrum-Marmaris-Fethiye. Las costas del Egeo se unieron por primera vez en una sola mano. Otros lugares incorporados en la misma fecha: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1391-10-01:0":{"b": ["Comenzó el primer bloqueo de Constantinopla", "4441a9e7"], "d": ["Bayezid el Rayo mantuvo bloqueada Constantinopla de forma intermitente durante diez años; la ciudad se salvó solo gracias a la aproximación de Timur.", "504fcb33"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Anexión de la provincia de Teke: incorporación de Antalya", "fdbeee5c"], "d": ["La provincia de Teke, en la costa del Mediterráneo, se incorporó al territorio otomano. Los Tekeoğlu son una rama escindida de los Hamîdoğlu: Feleküddin Dündar Bey había dejado Antalya, que había conquistado, a su hermano Yûnus Bey, y hacia 1321 había surgido un beylicato aparte. Por ello Antalya y sus alrededores se muestran en el mapa después de 1321 con el color de los Tekeoğlu y no de los Hamîdoğlu. El beylicato se restableció tras la batalla de Ankara y fue liquidado definitivamente solo en 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Conquista de Üsküp", "9e5a1af5"], "d": ["Fue tomado el centro de la Macedonia del Vardar; Üsküp se convirtió en uno de los principales centros fronterizos de Rumelia.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Anexión de Kastamonu", "876330ba"], "d": ["Fue liquidada la rama de Kastamonu de los Candaroğlu; la rama de Sinope continuó como vasalla. Otros lugares incorporados en la misma fecha: Bartın, Safranbolu.", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Caída de Tırnova — anexión de Bulgaria", "ff666977"], "d": ["Cayó la capital del zarato búlgaro; Bulgaria pasó a administración otomana directa. Otros lugares incorporados en la misma fecha: Plevna, Lofça.", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["La fortaleza de Lofça (Lovech) pasó a los otomanos", "a55e87a0"], "d": ["Lofça, una de las fortalezas del zar búlgaro Ivan Shishman, se incorporó al territorio otomano junto con las demás provincias de Shishman en la campaña de 1393 en que cayó Tırnova. La fuente no es categórica: «se cree» que la conquista fue este año.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Incorporación de Dobrudja", "478e36f2"], "d": ["Se incorporaron las tierras de Dobrudja, que se extienden hasta el delta del Danubio. Otros lugares incorporados en la misma fecha: Silistre, Constanza.", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Descenso a Tesalia", "8bec60dd"], "d": ["La llanura de Tesalia, con centro en Yenişehir (Larisa), fue puesta bajo administración otomana. Otros lugares incorporados en la misma fecha: Tırhala, İzdin (Lamia).", "d9f2128c"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Conquista de Nicópolis", "b9791717"], "d": ["Tras la batalla de Rovine de 1395 contra los valacos, Bayezid el Rayo tomó la fortaleza de Nicópolis (Niğbolu), a orillas del Danubio; algunas crónicas búlgaras anónimas indican que la conquista tuvo lugar el 3 de junio de 1395. La fecha de la conquista no es única en las fuentes: el artículo «Niğbolu Savaşı» del TDV İslâm Ansiklopedisi escribe que Bayezid se apoderó de Silistra y Nicópolis en una campaña del Danubio en 1394. La fortaleza sería sitiada en la famosa cruzada de 1396, pero no caería. Otros lugares incorporados en la misma fecha: Ohri.", "bc450a9f"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Batalla de Rovine — campaña de Valaquia", "343ae7a9"], "d": ["Tras la sangrienta batalla, de resultado discutido, librada con Mircea, voivoda de Valaquia, Valaquia aceptó pagar tributo a los otomanos; se estableció el orden de vasallaje al norte del Danubio.", "dd69200f"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Construcción de Anadolu Hisarı", "aa259b00"], "d": ["Para apoyar el bloqueo de Constantinopla se construyó Güzelcehisar (Anadolu Hisarı) en la orilla anatolia del Bósforo — el primer paso permanente hacia el control del estrecho.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Anexión de Vidin", "ee1ae44b"], "d": ["Tras la victoria de Nicópolis, fue anexionado también Vidin, el último principado búlgaro.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Primera anexión de Karaman", "3cf07876"], "d": ["Con la victoria de Akçay, las tierras de los Karamanoğlu se incorporaron por primera vez a los otomanos (se restablecerán en el Interregno).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Incorporación de la costa de Canik: Samsun", "af9c40fa"], "d": ["En el vacío surgido al caer Kadı Burhâneddin prisionero del Ak Koyunlu Karayülük Osman Bey, Bayezid el Rayo vinculó primero a la administración otomana la región de Canik, en la costa del mar Negro. Samsun y sus alrededores se convirtieron así en el primer puerto de la dinastía en el mar Negro. La línea interior Sivas-Tokat-Kayseri se incorporaría dos semanas después, con la disolución de hecho del Estado de Kadı Burhâneddin.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Toma de Malatya", "7cb6ae16"], "d": ["Fue tomada Malatya, en la frontera mameluca — uno de los pasos que aumentaron la tensión con Timur.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Timur tomó Malatya y la dejó a Karayülük Osman — al retirarse Timur, la recuperaron los Dulkadıroğlu", "ad2ce7d8"], "d": ["Bayezid el Rayo había dejado Malatya, tomada en 1399, a Dulkadıroğlu Nasreddin Mehmed y había vuelto a Bursa. Timur, que entró en Anatolia en 1400, tomó primero Sivas y Elbistan y luego Malatya; la ciudad y sus alrededores fueron saqueados y su administración quedó en manos de Karayülük Osman, que estaba con Timur. Al abandonar Timur la región, los Dulkadıroğlu volvieron a dominar Malatya; así el dominio otomano terminó antes de Ankara.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Tratado de Süleyman Çelebi con Bizancio: devolución de Salónica", "cc503cc2"], "d": ["Süleyman Çelebi, que dominaba Rumelia durante el Interregno, llegó a un acuerdo con Bizancio y los Estados latinos y cedió a Bizancio Salónica y las costas del mar Negro hasta Misivri (TDV fetret-devri: Tratado de Galípoli, febrero de 1403) — en el mapa İğneada, Rezve y Ahtapolu pasan a Bizancio; en el mapa Salónica sale de los otomanos en esta fecha.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Derrota naval de Galípoli (Venecia)", "b71d4d68"], "d": ["La flota veneciana infligió una dura derrota a la flota otomana ante Galípoli; el suceso mostró los límites de la marina otomana de la época temprana.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Rebelión de Mustafa el Impostor", "0ec43138"], "d": ["Mustafa Çelebi, que afirmaba ser hijo del Rayo, proclamó el sultanato en Rumelia con apoyo bizantino; Murad II reprimió la rebelión en 1422 y mandó ejecutar a su rival.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Asedio de Constantinopla por Murad II", "4b9d9fba"], "d": ["En respuesta al apoyo bizantino a Mustafa el Impostor, Murad II sitió Constantinopla; el asedio fue levantado cuando su hermano Küçük Mustafa fue alzado en rebelión en Anatolia.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Cesión de Salónica a Venecia", "bfa6c4a0"], "d": ["El gobernador bizantino, bajo presión otomana, cedió la ciudad a Venecia; comenzó la disputa otomano-veneciana que duraría siete años.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Nueva anexión de los beylicatos de Anatolia occidental: Menteşe y Aydın", "aca30a48"], "d": ["Los dos beylicatos del Egeo restablecidos en el Interregno se incorporaron definitivamente al territorio otomano en tiempos de Murad II. Según el artículo «Menteşeoğulları» del TDV, Murad II se apoderó de la provincia de Menteşe en 827 (1424) y encarceló a los dos hermanos que estaban al frente del beylicato. Según el artículo «Aydınoğulları», el beylerbey de Anatolia Hamza Bey hizo capturar a Cüneyd Bey, que de nuevo se había insubordinado, y lo hizo ejecutar con su familia (829/1425-26), y la provincia de Aydın pasó a los otomanos. Los caballeros de San Juan, que tenían la fortaleza portuaria de İzmir desde 1344, la habían perdido ante Timur en 1402 y la región había vuelto al control de los Aydınoğlu; con esta anexión también ella se incorporó a los otomanos. La provincia de Teke (Antalya) no es objeto de este asunto: los Tekeoğlu habían sido liquidados aparte en 1423. Germiyan, por su parte, se incorporaría por testamento en 1429.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Anexión de Germiyan por testamento", "9eb86b77"], "d": ["Yakub II, bey de Germiyan, que murió sin hijos, dejó su país por testamento a los otomanos — el ejemplo de anexión sin guerra que entró en los libros de texto. Otros lugares incorporados en la misma fecha: Karahisâr-ı Sâhib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Conquista definitiva de Salónica", "bc021768"], "d": ["La ciudad, bajo administración veneciana, fue tomada al asalto; el segundo gran puerto de Rumelia pasó definitivamente a ser otomano. Otros lugares incorporados en la misma fecha: Kesendire (Kassandra).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Rendición de Yanya", "ee45cb52"], "d": ["Yanya (Ioánina), centro del Epiro, se rindió mediante tratado.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Primera toma de Semendire", "c11ca17d"], "d": ["Tras un asedio de tres meses fue tomada la capital del despotado serbio y Serbia fue anexionada por primera vez (sería devuelta con el Tratado de Edirne-Szeged de 1444).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Asedio de Belgrado (fracasado)", "3e05f425"], "d": ["El primer gran asedio de Belgrado, de seis meses, no dio resultado; la fortaleza siguió siendo, durante ochenta años, una llave que cerraba el avance otomano.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Derrota de İzladi — la «Larga Campaña»", "97df1466"], "d": ["El ejército que Hunyadi introdujo en los Balcanes en pleno invierno pasó Niš y Sofía y llegó hasta İzladi; la defensa otomana se sostuvo con dificultad. Este clima de derrota llevó a la mesa la paz de Edirne-Szeged.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Tratado de Edirne-Szeged", "0aa4e0de"], "d": ["Paz de diez años: el despotado serbio fue devuelto y el Danubio se aceptó como frontera. La ruptura del tratado en pocos meses, por incitación papal, condujo al desastre de Varna.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Devolución de Semendire y de las fortalezas serbias a Serbia", "cda3cf9e"], "d": ["Se puso en práctica la disposición del Tratado de Edirne-Szeged: el 15 de agosto de 1444 Murad II devolvió Semendire a Đurađ Branković con sus veinticuatro fortalezas importantes y las demás tierras serbias ocupadas (TDV semendire); también Niš (TDV nis), Alacahisar (TDV alacahisar), Şehirköy (TDV sehirkoy) y Pristina (TDV pristine) fueron dejadas a los serbios. Vidin, por no ser tierra serbia, no entró en la devolución — este es el origen de la pérdida territorial del noroeste que se ve en el mapa en torno a la victoria de Varna; pocos meses después, con la derrota de Varna, el tratado quedaría de todos modos invalidado.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Completada la fortaleza de Rumeli — «Boğazkesen»", "480e8a76"], "d": ["Con la fortaleza, terminada en una construcción extraordinariamente rápida, de cuatro o cinco meses según las fuentes, el control del Bósforo pasó por completo a los otomanos; el camino de socorro desde el mar Negro a Constantinopla quedó cerrado. Se considera el primer paso efectivo del asedio.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Comenzó el asedio de Constantinopla", "8af50742"], "d": ["El ejército se asentó ante las murallas; en el asedio, que duraría 54 días, los cañones gigantescos fueron utilizados por primera vez de forma sistemática contra las murallas de una capital.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Los barcos fueron bajados por tierra al Cuerno de Oro", "4f2ba07c"], "d": ["Unos 70 barcos de la flota, que no podían entrar en el Cuerno de Oro cerrado con una cadena, fueron pasados sobre las colinas de Gálata por rieles engrasados y bajados en una sola noche al Cuerno de Oro; la defensa quedó dividida en dos frentes.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Conquista de Atenas", "4f0f1bb2"], "d": ["Terminó el Ducado de Atenas; en la Acrópolis fue izada la bandera otomana. Otros lugares incorporados en la misma fecha: İstefe (Tebas), Livadia.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Anexión de Serbia (caída de Semendire)", "75fd0a62"], "d": ["Semendire, capital del despotado serbio, se rindió; Serbia se convirtió en un sanjacado otomano.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Conquista de Morea", "7d5a3c18"], "d": ["Fue liquidado el despotado de Morea; la península (con excepción de las fortalezas venecianas) pasó a administración otomana.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Incorporación de Sinope", "e03c2739"], "d": ["Candaroğlu entregó Sinope sin guerra; quedó abierto el camino de la campaña de Trebisonda. Otros lugares incorporados en la misma fecha: Kastamonu, Bartın, Safranbolu.", "4fa22834"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Caída del Reino de Bosnia — campaña de Bosnia de Fâtih", "5362e3f2"], "d": ["Cuando el último rey de Bosnia, Stjepan Tomašević (1461-1463), confiando en el apoyo de Occidente, se negó a pagar el tributo, se le tuvo por dejado de ser soberano vasallo, y el ejército bajo el mando del sultán Mehmed Fâtih liquidó el Reino de Bosnia en una sola campaña. El rey fue capturado y ejecutado, el reino desapareció y se creó en la región el sanjacado de Bosnia. Sin embargo, la caída del reino no es lo mismo que la conquista de Bosnia. La administración otomana existía ya en la llanura desde hacía quince años — Hodidjed y la llanura de Saray habían sido tomadas en 1448, y el beylicato fronterizo de Îsâ Bey se había establecido en medio del reino. La conquista tampoco terminó en 1463: Foča fue tomada en 1465, Livno en 1469, el Ducado de Herzegovina en 1483, el banato de Srebrenik en 1512, y Jajce y Banja Luka, en el norte, solo después de Mohács, en 1528 — los húngaros habían establecido tras 1463 un banato que se mantuvo sesenta y cinco años en el norte de Bosnia. El lugar que cambió directamente de manos en esta fecha es Travnik; Jajce, en esta fecha, pasó no a los otomanos sino a Hungría.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Anexión definitiva de Karaman", "f1dcecaa"], "d": ["Las tierras centrales de los Karamanoğlu se incorporaron definitivamente; las disputas internas continuaron hasta la década de 1470. Otros lugares incorporados en la misma fecha: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Conquista de Negroponte (Eğriboz)", "5c97daf3"], "d": ["Cayó Eğriboz, la principal base de Venecia en el Egeo.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Anexión de Alanya, Anamur y Silifke (İçel)", "a0b9d461"], "d": ["La franja costera de İçel, dependiente de los Karamanoğlu (todo el Mediterráneo entre Antalya y Mersin), se incorporó con la campaña naval de Gedik Ahmed Pachá; Alanya era importante por su arsenal estratégico, heredado de la época selyúcida.", "8302df58"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Tratado de Estambul — Albania y Escútari", "b09652f7"], "d": ["Terminó la guerra otomano-veneciana de 16 años; Escútari (İşkodra) y las costas de Albania permanecieron con los otomanos. Otros lugares incorporados en la misma fecha: Lemnos, Samos, Bozbaba (Agios Efstratios).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Desembarco de Otranto", "7916b89d"], "d": ["Las fuerzas otomanas que desembarcaron en la costa de Calabria sitiaron y tomaron la fortaleza de Otranto; como se entró en la ciudad combatiendo, una parte de los notables que resistieron fue ejecutada y otra parte capturada. La tradición eclesiástica recuerda a los muertos como los «mártires de Otranto», unos 800; el TDV atribuye la exageración de esta cifra a la propaganda eclesiástica. Solo se mantuvieron la fortaleza en la punta de la península del Salento y su estrecho entorno; los demás territorios del Reino de Nápoles en la línea Tarento-Brindisi-Lecce no se perdieron — esta cabeza de puente abierta hacia Italia duraría un año.", "f60d286a"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Evacuación de Otranto", "37371bb0"], "d": ["Tras la muerte de Fatih Sultan Mehmed (3 de mayo de 1481), la guarnición de Otranto, que ya no tenía esperanza de refuerzos, evacuó la fortaleza por acuerdo ante el asedio de Alfonso, heredero de Nápoles; así se perdió, un año después, la única cabeza de puente otomana en Italia.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Conquista de Modon y Corón", "38b608c4"], "d": ["Fueron tomados Modon y Corón, los «dos ojos» de Venecia en Morea.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Conquista de Durazzo (Draç)", "1f231b98"], "d": ["Durante la guerra otomano-veneciana de 1499-1503, las fuerzas al mando de Mehmed Bey tomaron Durazzo, el último gran puerto albanés de Venecia en el Adriático. Tras Escútari (1479) y Valona (1417), con esta conquista toda la franja costera de Albania pasó al control otomano.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Incorporación de Anatolia oriental", "e0cb8f8f"], "d": ["Tras Çaldıran se incorporaron Diyarbakır y sus alrededores; los beylicatos kurdos fueron vinculados a los otomanos por obra de İdrîs-i Bitlisî.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Conquista de la fortaleza de Varadin (Petrovaradin)", "abf392a5"], "d": ["El ejército que salió a la campaña de Mohács pasó desde Belgrado a tierras húngaras; de Varadin se tomaron primero los arrabales y, tras un asedio de catorce días, cayó también la fortaleza. Solimán ordenó que no se quemaran las aldeas del camino, porque ya se consideraban territorio otomano.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Rendición de Buda tras Mohács — dos reyes para el trono húngaro", "9d3568a0"], "d": ["Tras la victoria de Mohács, las llaves de la ciudad fueron presentadas al sultán el 11 de septiembre de 1526 ante el ejército otomano que marchaba sobre Buda; pero Solimán no retuvo Buda y retiró su ejército. En la Hungría sin rey, los nobles eligieron dos reyes distintos: János Szapolyai el 10 de noviembre de 1526 y Fernando I de Habsburgo el 17 de diciembre de 1526. Fernando tomó Buda en agosto de 1527. El establecimiento de Szapolyai en Buda como rey bajo protección otomana tendrá lugar con la campaña de 1529 (véase el asunto de 1529); la administración otomana directa se establecería en 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai elegido rey de Hungría — los otomanos reconocieron su reino con la condición de que fuese vasallo", "32bc6baf"], "d": ["Para el trono húngaro, vacante por la muerte del rey en Mohács, una parte de los nobles eligió a János Szapolyai, voivoda de Transilvania; Szapolyai fue coronado en Istolni Belgrad. Los otomanos, que evacuaron Buda, reconocieron el reino de Szapolyai con la condición de que les fuera vasallo, para mantener la región como zona tampón. En el mapa, los lugares dependientes de Szapolyai figuran desde esta fecha como vasallos de los otomanos.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Fernando I proclamado rey de Hungría — Hungría occidental y septentrional bajo la corona de los Habsburgo", "b3910a2f"], "d": ["El archiduque Fernando de Habsburgo, basándose en el matrimonio de su hermana con Luis II, reclamó derechos sobre el trono húngaro y fue proclamado rey por una parte de los nobles. Hungría quedó así dividida entre dos reyes; sus partes occidental y septentrional reconocieron a Fernando. Los nobles croatas lo eligieron además por separado a principios de 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Disputa de los dos reyes: Esztergom bajo protección de los Habsburgo, Szeged con Szapolyai", "da92dee5"], "d": ["Esztergom, que desde 1526 cambió de manos entre los dos reyes, pasó a la protección de los Habsburgo después de que el arzobispo se trasladara al norte con sus archivos y su tesoro. Desde ese mismo año y hasta 1541, Szeged permaneció bajo la soberanía de Szapolyai.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["La población de Pécs pasó al lado de Szapolyai", "3fc4e7f2"], "d": ["Pécs, que había obtenido un privilegio de Fernando en 1528, pasó poco después al lado de Szapolyai; el rey János permaneció algún tiempo en la ciudad en 1533. Con la caída de Buda en 1541, la ciudad volvió al lado de Fernando.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Conquista de Trablusgarp", "8c659986"], "d": ["Trípoli fue tomada a los caballeros de San Juan; la costa central del norte de África pasó a ser otomana. Otros lugares incorporados en la misma fecha: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Conquista de Timișoara", "e9fd4995"], "d": ["Se tomó la región del Banato y se creó el beylerbeylato de Timișoara.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Conquista definitiva de Túnez", "7bbd11bc"], "d": ["Túnez, bajo control hispano-hafsí, pasó definitivamente a la administración otomana; quedó completada la línea del norte de África. Otros lugares incorporados en la misma fecha: Kairuán, Gabes, Sfax.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Conquista de Kanizsa", "0c7b6aa3"], "d": ["En la Larga Guerra se tomó Kanizsa; al año siguiente la defensa de Tiryâki Hasan Pachá se hizo legendaria.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Comenzó la campaña de Uyvar — Fâzıl Ahmed Pachá marchó desde Edirne contra Austria", "306a86db"], "d": ["Cuando Austria atacó Transilvania y tomó las fortalezas de Székelyhíd y Kolozsvár, Estambul decidió una campaña contra los Habsburgo. El gran visir Köprülüzâde Fâzıl Ahmed Pachá partió de Edirne el 13 de abril de 1663. En Belgrado llegó la petición de paz de Austria, pero en dos entrevistas en Osijek se rechazaron las condiciones otomanas. En la consulta de Buda se fijó también como objetivo Uyvar.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Conquista de Uyvar", "ce289470"], "d": ["Fue tomada Uyvar, fortaleza clave de la Hungría septentrional; la expresión «fuerte como un turco ante Uyvar» pasó a las lenguas europeas. Tras Uyvar, también Nitra y Léva se rindieron con una breve resistencia; las dos fueron recuperadas por De Souches en la primavera de 1664.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Recuperación de Morea", "9b6460f1"], "d": ["Morea, cedida a Venecia en Karlowitz, fue recuperada en una sola campaña. Otros lugares incorporados en la misma fecha: Balyabadra (Patras), İnebahtı.", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Segunda pérdida de Belgrado — asedio del príncipe Eugenio", "6a194354"], "d": ["Tras la derrota de Varadin y la pérdida de Timișoara, el príncipe Eugenio sitió Belgrado; cuando fue derrotado también el ejército de socorro que venía a salvar la ciudad, la fortaleza se rindió. La ciudad, recuperada en 1690 tras Karlowitz, se perdió así de nuevo y la línea defensiva del Danubio se derrumbó. Belgrado solo podría recuperarse veintidós años después, con el Tratado de Belgrado de 1739. Otros asentamientos perdidos en la misma fecha: Semendire.", "3bf3f600"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Caída de Özi", "90a67a6c"], "d": ["Özi, fortaleza clave al norte del mar Negro, pasó a manos de Rusia en un sangriento asalto; la población de la ciudad fue pasada a cuchillo.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Tratado de Bucarest — pérdida de Besarabia", "932da4d6"], "d": ["Con el tratado que puso fin a la guerra rusa de 1806-1812, el este del Prut (Besarabia) fue cedido a Rusia. Otros asentamientos perdidos en la misma fecha: Akkirman, Kili, Jotín, Bender, İsmail.", "a4c3a1fb"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Tratado de Edirne", "b3a8fe4c"], "d": ["Al término de la guerra en que el ejército ruso entró en Edirne, se perdió el delta del Danubio; de hecho se aceptó la autonomía/independencia de Grecia. Otros asentamientos perdidos en la misma fecha: Brăila, Anapa, Ahıska. Aunque el tratado devolvió territorio, no puso fin de inmediato a la ocupación: Valaquia-Moldavia y Silistra permanecieron como prenda bajo administración rusa hasta que se pagara la indemnización de guerra — de ahí que en el mapa estos lugares figuren ocupados también después de 1829.", "d09a34fb"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Edicto de autonomía a Serbia — knezado hereditario y condición de guarniciones", "6a5d901d"], "d": ["El hatt-ı hümâyun, emitido en cumplimiento de la disposición del Tratado de Edirne relativa a Serbia, reconoció a Miloš Obrenović como knez hereditario e hizo de Serbia un principado autónomo, libre en sus asuntos internos y vinculado a los otomanos en el exterior. Disposiciones: el knezado pasaría de padre a hijo, se pagaría un tributo anual fijo, la asamblea serbia establecería su propia administración interna, la Iglesia sería autónoma; a cambio, quedarían guarniciones otomanas en las fortalezas de Belgrado, Semendire, Šabac, Böğürdelen y Fethülislâm. Esta estructura doble duró hasta la retirada de las guarniciones en 1867. En el mapa, la ciudad de Belgrado se incorpora en esta fecha a la Serbia autónoma; la fortaleza de Kalemegdan figura bajo guarnición otomana hasta 1867.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Cesión de Chipre a la administración británica", "423da3ee"], "d": ["A cambio de una alianza frente a la amenaza rusa, la administración de Chipre fue cedida a Inglaterra; jurídicamente siguió siendo territorio otomano. Otros asentamientos perdidos en la misma fecha: Nicosia, Famagusta.", "04ce99ee"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Cesión de Tesalia a Grecia", "ac614d24"], "d": ["Conforme a las decisiones del Congreso de Berlín, Tesalia y los alrededores de Narda fueron cedidas a Grecia. Otros asentamientos perdidos en la misma fecha: Arta, Yenişehir (Larisa), Tırhala, İzdin (Lamia).", "850edaa2"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Unión de Rumelia oriental a Bulgaria", "ee43f137"], "d": ["La provincia autónoma de Rumelia oriental fue unida a Bulgaria mediante un golpe; la Sublime Puerta aceptó el hecho consumado.", "41e57063"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Batalla de Domokós", "9c6f29a5"], "d": ["En la guerra otomano-griega de 1897 el ejército obtuvo una victoria decisiva en Domokós; por la presión diplomática, la ganancia territorial quedó limitada.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Autonomía de Creta", "2e764881"], "d": ["Aunque la guerra otomano-griega terminó con victoria otomana, Inglaterra, Rusia, Francia e Italia proclamaron el 18 de diciembre de 1897 la autonomía de Creta; la isla sería una provincia neutral y autónoma bajo soberanía otomana. Después del 6 de noviembre de 1898 la bandera turca ya no se izó en Candia ni en Kisamos; con el comienzo de sus funciones, el 22 de diciembre de 1898, del príncipe Jorge, hijo del rey de Grecia, como alto comisionado extraordinario, Creta salió de hecho de la administración otomana (se separó oficialmente en 1913). Otros asentamientos perdidos en la misma fecha: Kandiye (Creta), Hanya.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Independencia de Bulgaria y anexión de Bosnia", "393feaa4"], "d": ["En la confusión de la monarquía constitucional, Bulgaria declaró su independencia y Austria-Hungría anexionó Bosnia-Herzegovina.", "6b7e2450"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Recuperación de Edirne", "536e5599"], "d": ["En la Segunda Guerra de los Balcanes el ejército cruzó el Maritsa y recuperó Edirne sin combate. Otros lugares incorporados en la misma fecha: Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Victoria de Kut al-Amara", "98b972bc"], "d": ["El comandante de la división inglesa sitiada en Kut se rindió con sus 13 mil soldados — una de las mayores victorias otomanas de la Primera Guerra Mundial.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Pérdida de Bagdad", "2c18a816"], "d": ["La Bagdad otomana de 383 años pasó al ejército inglés. Otros asentamientos perdidos en la misma fecha: Kerbala.", "4add66da"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Pérdida de Jerusalén", "94067617"], "d": ["La Jerusalén otomana de 401 años fue entregada sin poder ser defendida.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Pérdida de Damasco", "ed177b68"], "d": ["Con el derrumbe del frente de Palestina, Damasco fue evacuada; terminó el dominio otomano de cuatro siglos en Siria. Otros asentamientos perdidos en la misma fecha: Hama, Homs.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Rendición de Medina", "76b505f6"], "d": ["Setenta y dos días después del armisticio, la resistencia de Fahreddin Pachá, el «Tigre del Desierto», terminó por voluntad del sultán; la última unidad otomana en el Hiyaz depuso las armas.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Ocupación de İzmir", "e32e5e77"], "d": ["El ejército griego desembarcó en İzmir; la resistencia, iniciada con el primer disparo, encendió la mecha de la Lucha Nacional. Aydın, por su parte, fue ocupada el 27 de mayo de 1919 (asunto aparte).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Ocupación oficial de Estambul", "a8e98ada"], "d": ["Las fuerzas de la Entente ocuparon oficialmente Estambul y el Meclis-i Meb'ûsan fue disuelto; los diputados se dirigieron a Ankara.", "09ed005b"]},
"OLAYLAR_EK:1921-10-13:0":{"b": ["Tratado de Kars", "bb32d4e0"], "d": ["Entre la Gran Asamblea Nacional y las repúblicas del Cáucaso se trazó la frontera oriental tal como es hoy.", "fe736259"]},
"OLAYLAR_FRANSA_KONTROL_1027:1284-01-01:0":{"b": ["El condado de Champaña se vincula a la corona de Francia por el matrimonio de Juana I con Felipe IV: Troyes (junto con Meaux)", "cae2654d"], "d": ["Con el matrimonio (1284) de Juana I, condesa de Champaña y reina de Navarra, con Felipe (IV), heredero de Francia, Troyes, capital de Champaña, se incorporó a las tierras de la corona; para Meaux Treccani dice en el mismo año (1284) que «pasó al rey de Francia». La anexión oficial del condado se produjo en 1314, con el acceso de Luis X al trono (t de la ficha).", "03072856"]},
"OLAYLAR_FRANSA_KONTROL_1027:1305-01-01:0":{"b": ["El conde de Flandes cede la Flandes valona (Lille, Douai, Béthune) al rey de Francia Felipe IV: Lille", "a4746f27"], "d": ["La parte «francesa» (valona) del condado de Flandes —las castellanías de Douai, Béthune y Lille— fue entregada en 1305 al rey de Francia (cesión definitiva en 1320); en 1369 la obtuvieron por matrimonio los duques de Borgoña.", "fa06bb72"]},
"OLAYLAR_FRANSA_KONTROL_1027:1312-01-01:0":{"b": ["Se establece la supremacía del rey de Francia en Lyon: Felipe IV (el Hermoso) se apodera de Lyon, feudo imperial, con el Tratado de Vienne", "60ea68d8"], "d": ["En Lyon, feudo del emperador alemán desde 1032 y cuyo poder efectivo se repartían el arzobispo y los condes de Forez, se estableció en 1312 la supremacía del rey de Francia Felipe IV; desde esta fecha la ciudad se considera francesa.", "74a8638d"]},
"OLAYLAR_FRANSA_KONTROL_1027:1314-11-29:0":{"b": ["Muere Felipe IV; Luis X (el Obstinado) se convierte en rey de Francia", "10fd76ef"], "d": ["Felipe IV murió el 29 de noviembre de 1314; su hijo Luis X subió al trono de Francia (ya era rey de Navarra desde 1305).", "3aa6f8e3"]},
"OLAYLAR_FRANSA_KONTROL_1027:1317-01-09:0":{"b": ["Felipe V es coronado en Reims (siendo regente tras la muerte de Luis X, se había proclamado rey a la muerte de su sobrino Juan I)", "3b50d3fc"], "d": ["Luis X murió el 5 de julio de 1316; el regente Felipe V, tras la muerte —cuatro días después de su nacimiento— de su sobrino póstumo Juan I, se proclamó rey y fue coronado en Reims el 9 de enero de 1317. La fuente no da el día de la proclamación; el atlas toma el día de la coronación.", "5e0b5084"]},
"OLAYLAR_FRANSA_KONTROL_1027:1322-01-03:0":{"b": ["Muere Felipe V; Carlos IV se convierte en rey de Francia", "a0b9abda"], "d": ["Felipe V murió en Longchamp en la noche del 2 de enero de 1322; su hermano Carlos IV subió al trono.", "a4efde24"]},
"OLAYLAR_FRANSA_KONTROL_1027:1328-05-29:0":{"b": ["Felipe VI (Valois) es coronado en Reims: comienza la dinastía Valois", "a9595d82"], "d": ["Cuando Carlos IV murió en febrero de 1328 sin dejar heredero varón, Felipe de Valois se convirtió en regente; el 29 de mayo de 1328 fue coronado en Reims e inició la dinastía Valois. La pretensión del rey de Inglaterra Eduardo III por línea materna es una de las chispas de la Guerra de los Cien Años.", "aca69718"]},
"OLAYLAR_FRANSA_KONTROL_1027:1348-06-09:0":{"b": ["Juana, reina de Nápoles, vende Aviñón al papa Clemente VI", "ecd3d028"], "d": ["El 9 de junio de 1348 Juana, reina de Nápoles, en calidad de condesa de Provenza, vendió la ciudad de Aviñón al papa Clemente VI por 80.000 florines; la ciudad permaneció como enclave pontificio hasta 1791. El registro de asentamiento ya llevaba esta frontera; faltaba el registro del hecho.", "682eb4f6"]},
"OLAYLAR_FRANSA_KONTROL_1027:1349-04-18:0":{"b": ["Felipe VI compra Montpellier al rey de Mallorca", "05d06418"], "d": ["La venta a Felipe VI, rey de Francia, de los derechos de Jaime III, rey de Mallorca, sobre Montpellier fue ratificada el 18 de abril de 1349; Montpellier pasó a la corona de Francia.", "302b9de1"]},
"OLAYLAR_FRANSA_KONTROL_1027:1349-07-16:0":{"b": ["Humberto II cede el Delfinado al nieto del rey de Francia: Grenoble", "a8d8a248"], "d": ["El 30 de marzo de 1349 se concluyó el tratado de Romans entre Humberto II y el rey de Francia; el 16 de julio de 1349, mediante la escritura «Transport du Dauphiné à la France» firmada en Lyon, las tierras y el título del Delfinado fueron cedidos a Carlos (nieto del rey de Francia Felipe VI). Desde ese momento «Delfín» pasó a ser el título del heredero del trono de Francia.", "c129d1f5"]},
"OLAYLAR_FRANSA_KONTROL_1027:1350-08-22:0":{"b": ["Muere Felipe VI; Juan II (el Bueno) se convierte en rey de Francia", "3eb96ab5"], "d": ["Felipe VI murió en Nogent-le-Roi el 22 de agosto de 1350; su hijo Juan II subió al trono.", "ed19aa83"]},
"OLAYLAR_FRANSA_KONTROL_1027:1360-10-24:0":{"b": ["Tratado de Calais: se ratifican las condiciones de Brétigny, Poitou y Aquitania son cedidas a Inglaterra: Poitiers", "8e13271f"], "d": ["El preacuerdo de Brétigny del 8 de mayo de 1360 fue ratificado en Calais el 24 de octubre de 1360: Poitou, Saintonge, Aunis, Agenais, Périgord, Limousin, Quercy, Angoumois y Rouergue fueron cedidos a Inglaterra. Limoges, La Rochelle y Poitiers pasan a Inglaterra en el atlas en este día.", "278ddde1"]},
"OLAYLAR_FRANSA_KONTROL_1027:1388-09-28:0":{"b": ["Niza se entrega al conde de Saboya Amadeo VII (la «dédition» de Niza a Saboya)", "3af46844"], "d": ["Durante la disputa sucesoria entre los herederos angevinos de Provenza, Niza y su entorno (el Condado de Niza) pasaron el 28 de septiembre de 1388 a la soberanía del conde de Saboya Amadeo VII; Niza permaneció hasta 1860 (salvo las ocupaciones francesas) en la dinastía de Saboya/Cerdeña. El atlas ya llevaba esta frontera; faltaba el registro.", "04a5e558"]},
"OLAYLAR_FRANSA_KONTROL_1027:1420-12-01:0":{"b": ["Enrique V entra en París: comienza el régimen anglo-borgoñón", "126d50cb"], "d": ["Tras el Tratado de Troyes (21 de mayo de 1420), en diciembre de 1420 París pasó al dominio anglo-borgoñón; la ciudad fue gobernada en nombre de Enrique VI hasta abril de 1436.", "7426a907"]},
"OLAYLAR_FRANSA_KONTROL_1027:1422-10-21:0":{"b": ["Muere Carlos VI; Carlos VII es proclamado rey de Francia", "7aeefd1a"], "d": ["Carlos VI murió el 21 de octubre de 1422; pese al Tratado de Troyes, Carlos VII se proclamó rey (región de Bourges); París permaneció bajo control anglo-borgoñón.", "da118a77"]},
"OLAYLAR_FRANSA_KONTROL_1027:1436-04-13:0":{"b": ["París se rinde al rey de Francia Carlos VII", "f3d92546"], "d": ["Tras el Tratado de Arras (1435) los habitantes de París abrieron el 13 de abril de 1436 las puertas a los comandantes de Carlos VII; terminó la administración inglesa.", "79a422fe"]},
"OLAYLAR_FRANSA_KONTROL_1027:1450-04-15:0":{"b": ["Batalla de Formigny: el ejército francés derrota al ejército inglés, se acelera la reconquista de Normandía", "77d20042"], "d": ["El 15 de abril de 1450 en Formigny el ejército francés venció a la fuerza de socorro inglesa; cayeron Caen y Cherburgo, y Normandía volvió al control francés.", "0287dae5"]},
"OLAYLAR_FRANSA_KONTROL_1027:1477-01-01:0":{"b": ["Luis XI toma Artois (Arras) de la herencia de Borgoña", "da697a1e"], "d": ["Con la muerte de Carlos el Temerario en Nancy (5 de enero de 1477), el rey de Francia Luis XI ocupó Artois; Arras, al resistir, fue tomada al asalto y sus murallas fueron derribadas. El Tratado de Arras (23 de diciembre de 1482) dejó Artois en Francia como dote de Margarita; con el Tratado de Senlis de 1493 volvió a los Habsburgo.", "7867c9fc"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:0":{"b": ["Con la muerte de Carlos III, Provenza pasa al rey de Francia Luis XI según el testamento: Aix-en-Provence", "dc558e2c"], "d": ["Carlos III, último conde de Provenza de la casa de Anjou, testó en Marsella el 10 de diciembre de 1481 y murió el 11 de diciembre de 1481; el condado de Provenza pasó a manos del rey de Francia. La unión se consolidó jurídicamente en 1486 (adhesión de los Estados de Provenza).", "42fad3ff"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:1":{"b": ["Con la muerte de Carlos III, Provenza pasa al rey de Francia Luis XI según el testamento: Marsella", "bd072b2d"], "d": ["El testamento fue redactado en Marsella (10 de diciembre de 1481); con la muerte de Carlos (11 de diciembre) Provenza, y con ella Marsella, pasó a la corona de Francia.", "3baf7804"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:2":{"b": ["Con la muerte de Carlos III, Provenza pasa al rey de Francia Luis XI según el testamento: Arlés", "de44f23c"], "d": ["Arlés estaba desde 1251 en manos de los condes de Provenza (Anjou); con el paso del condado a la corona de Francia (11 de diciembre de 1481) se hizo francesa.", "b58a0e54"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:3":{"b": ["Con la muerte de Carlos III, Provenza pasa al rey de Francia Luis XI según el testamento: Tolón", "7a8c1f9a"], "d": ["Tolón, puerto de Provenza, se hizo francesa con el paso del condado a la corona de Francia (11 de diciembre de 1481); no hay una fuente separada específica de Tolón, el centro hermano es Aix-en-Provence (APROXIMACIÓN DECLARADA).", "11d22f4b"]},
"OLAYLAR_FRANSA_KONTROL_1027:1493-01-01:0":{"b": ["Tratado de Senlis: Arras (Artois) vuelve al Habsburgo Maximiliano", "040b03f8"], "d": ["El Tratado de Senlis (1493) entre Carlos VIII y Maximiliano I entregó Artois y Arras a los Habsburgo.", "2e7e96b7"]},
"OLAYLAR_FRANSA_KONTROL_1027:1498-04-07:0":{"b": ["Muere Carlos VIII; Luis XII se convierte en rey de Francia", "560db6d5"], "d": ["Carlos VIII murió en Amboise el 7 de abril de 1498; su primo el duque de Orleans, Luis XII, subió al trono.", "24214314"]},
"OLAYLAR_FRANSA_KONTROL_1027:1552-01-01:0":{"b": ["Campaña de Enrique II de los Tres Obispados: Toul se incorpora a Francia", "5d7053ac"], "d": ["Toul, gobernada por obispos-condes y dependiente del Imperio alemán, se incorporó a Francia en 1552 (junto con Metz y Verdún, los Tres Obispados); jurídicamente fue confirmada en 1648 en Westfalia. El día de Metz (18 de abril de 1552) figura aparte en el atlas; para Toul la fuente no da día.", "5cdb37db"]},
"OLAYLAR_FRANSA_KONTROL_1027:1559-07-10:0":{"b": ["Muere Enrique II; Francisco II se convierte en rey de Francia", "88a1a26e"], "d": ["Enrique II murió el 10 de julio de 1559; su hijo de 15 años Francisco II subió al trono (influencia de la dinastía Guisa).", "746455f8"]},
"OLAYLAR_FRANSA_KONTROL_1027:1560-12-05:0":{"b": ["Muere Francisco II; Carlos IX se convierte en rey de Francia", "16566c2b"], "d": ["Francisco II murió el 5 de diciembre de 1560; su hermano Carlos IX (de 10 años) subió al trono y su madre Catalina de Médicis fue regente.", "0139a790"]},
"OLAYLAR_FRANSA_KONTROL_1027:1574-05-30:0":{"b": ["Muere Carlos IX; Enrique III se convierte en rey de Francia (siendo rey de Polonia)", "f86885f1"], "d": ["Carlos IX murió el 30 de mayo de 1574; su hermano Enrique de Valois, rey de Polonia, se convirtió en heredero del trono de Francia y regresó a Francia en septiembre de 1574.", "f3fea374"]},
"OLAYLAR_FRANSA_KONTROL_1027:1589-08-01:0":{"b": ["Enrique III, en su lecho de muerte, reconoce como sucesor a Enrique de Navarra (Enrique IV): comienza la dinastía Borbón", "328bca08"], "d": ["Enrique III, víctima de un atentado y último rey de la línea Valois, reconoció solemnemente a Enrique de Navarra como sucesor el 1 de agosto de 1589; con su muerte (2 de agosto) la dinastía Borbón pasó al trono de Francia.", "df18d0c2"]},
"OLAYLAR_FRANSA_KONTROL_1027:1610-05-14:0":{"b": ["Termina el reinado de Enrique IV; Luis XIII se convierte en rey", "dfe5892c"], "d": ["Enrique IV murió asesinado en París el 14 de mayo de 1610; su hijo Luis XIII se convirtió en rey. (El fin del reinado figura en Treccani como «Regnò fino al 14 maggio 1610».)", "86a0f811"]},
"OLAYLAR_FRANSA_KONTROL_1027:1643-05-14:0":{"b": ["Muere Luis XIII; Luis XIV, de cinco años, se convierte en rey (regencia: Ana de Austria, Mazarino)", "2ac0d106"], "d": ["Luis XIII murió en Saint-Germain-en-Laye el 14 de mayo de 1643; su hijo Luis XIV subió al trono ese mismo día.", "6a173c34"]},
"OLAYLAR_FRANSA_KONTROL_1027:1681-09-30:0":{"b": ["Estrasburgo capitula ante el ejército de Luis XIV: se incorpora a Francia", "3c3c1cc6"], "d": ["Durante la política de las Réunions, el ejército de Louvois sitió Estrasburgo; la ciudad firmó las condiciones de rendición el 30 de septiembre de 1681 (acta de capitulación en Illkirch); ratificación el 3 de octubre y entrada solemne de Luis XIV el 23 de octubre de 1681. La ciudad se incorporó a Francia y se suprimió su autonomía municipal.", "4f2a5014"]},
"OLAYLAR_FRANSA_KONTROL_1027:1791-09-14:0":{"b": ["La Asamblea Constituyente aprueba la unión de Aviñón y el Condado Venaissin a Francia", "d15fe246"], "d": ["Tras la expulsión del vicelegado pontificio de Aviñón (12 de junio de 1790), la Asamblea Constituyente examinó la solicitud de unión; la unión fue aprobada el 14 de septiembre de 1791. Pío VI protestó el 5 de noviembre de 1791; con el artículo 6 del Tratado de Tolentino (19 de febrero de 1797) el papado renunció a Aviñón y al Condado.", "a422cae7"]},
"OLAYLAR_FRANSA_KONTROL_1027:1793-01-03:0":{"b": ["Mónaco se incorpora a la República Francesa con el nombre de Fort-Hercule", "1b846e31"], "d": ["Con la anexión de Mónaco por la Francia revolucionaria cesó la soberanía de los Grimaldi; el principado fue parte de Francia (Fort-Hercule) hasta 1814.", "c3f4c386"]},
"OLAYLAR_FRANSA_KONTROL_1027:1798-03-15:0":{"b": ["La República de Mulhouse se une a la República Francesa (Réunion)", "0c2b4f8a"], "d": ["La República de Mulhouse, aliada de la Confederación Suiza desde 1515, se incorporó voluntariamente a Francia tras la Paz de Basilea (1795); la unión se realizó en 1798 (Réunion).", "e775b26b"]},
"OLAYLAR_FRANSA_KONTROL_1027:1814-05-30:0":{"b": ["Tratado de París: Mónaco vuelve a la soberanía de los Grimaldi", "f3011157"], "d": ["Con el Tratado de París del 30 de mayo de 1814 se restituyeron los derechos de los Grimaldi; Mónaco salió de la anexión francesa (el protectorado sardo de 1815-1861 es otro asunto y no se trató en este registro).", "32ba22e7"]},
"OLAYLAR_FRANSA_KONTROL_1027:1861-02-02:0":{"b": ["Tratado franco-monegasco: Mónaco renuncia, a cambio de 4 millones de francos, a sus derechos sobre Menton (y Roquebrune); Menton pasa a Francia", "ffa21e54"], "d": ["Tras la cesión a Francia de Niza por el Piamonte-Cerdeña en 1860, el príncipe de Mónaco cedió a Francia sus derechos de soberanía en Menton y Roquebrune. Menton era desde 1848 ciudad libre bajo protectorado sardo.", "0aff978e"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-17:0":{"b": ["Las tropas francesas entran en Mulhouse: comienza el regreso de Alsacia", "a56edca7"], "d": ["Seis días después del armisticio (11 de noviembre de 1918) las tropas francesas entraron en Mulhouse. El artículo 51 de Versalles considera el regreso de Alsacia-Lorena a la soberanía francesa con efecto retroactivo desde el 11 de noviembre de 1918; firma el 28 de junio de 1919, entrada en vigor el 10 de enero de 1920.", "204a7d28"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-18:0":{"b": ["Las tropas francesas entran en Colmar", "dabdf81a"], "d": ["Colmar recibió a las tropas francesas el 18 de noviembre de 1918; Alsacia volvía a la administración francesa (retroactividad jurídica desde el 11 de noviembre de 1918, art. 51 de Versalles).", "04dcdb67"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-19:0":{"b": ["La 28.ª División de Infantería francesa entra en Metz", "c37a5b99"], "d": ["La 28.ª División de Infantería francesa entró en Metz el 19 de noviembre de 1918; el Mosela volvió a la administración francesa.", "aa57e100"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-21:0":{"b": ["Las tropas francesas entran en Estrasburgo (ceremonia oficial el 22 de noviembre)", "92b3cc2e"], "d": ["Tras 47 años de administración alemana, las primeras tropas francesas entraron en Estrasburgo el 21 de noviembre de 1918; la ceremonia oficial de entrada se celebró al día siguiente.", "22f53345"]},
"OLAYLAR_FRANSA_KONTROL_1027:1940-08-02:0":{"b": ["Wagner y Bürckel, jefes de la administración civil de Alsacia y Lorena: la región se incorpora de facto al Reich", "0e36dc11"], "d": ["Tras la derrota de Francia, Alsacia y el Mosela se incorporaron de facto a Alemania sin tratado: Alsacia pasó a la administración civil de Wagner, Gauleiter de Baden, y el Mosela a la de Bürckel, Gauleiter de Sarre-Palatinado (el Mosela fue vinculado al Gau Westmark el 30 de noviembre de 1940). El texto del armisticio no contiene cláusula de anexión; jurídicamente la soberanía francesa continúa (Ordonnance del 9 de agosto de 1944).", "8f35b253"]},
"OLAYLAR_FRANSA_KONTROL_1027:1944-11-20:0":{"b": ["Mulhouse es liberada", "151f48e4"], "d": ["El 1.er Ejército francés (de Lattre) liberó Mulhouse en noviembre de 1944.", "78fba884"]},
"OLAYLAR_FRANSA_KONTROL_1027:1944-11-22:0":{"b": ["Metz es liberada (los fuertes resistieron hasta diciembre)", "17049694"], "d": ["El 3.er Ejército de Estados Unidos liberó Metz el 22 de noviembre de 1944; los fuertes de los alrededores resistieron hasta diciembre.", "4566f454"]},
"OLAYLAR_FRANSA_KONTROL_1027:1944-11-23:0":{"b": ["La 2.ª División Blindada de Leclerc libera Estrasburgo", "7b399aa3"], "d": ["La 2.ª División Blindada al mando de Leclerc entró en Estrasburgo el 23 de noviembre de 1944; terminó la administración alemana (anexión de facto desde 1940) en la capital de Alsacia.", "4f1f13e2"]},
"OLAYLAR_FRANSA_KONTROL_1027:1945-02-02:0":{"b": ["Colmar es liberada (la Bolsa de Colmar fue eliminada el 9 de febrero)", "41a297f7"], "d": ["Colmar fue liberada el 2 de febrero de 1945; la Bolsa de Colmar fue completamente eliminada el 9 de febrero de 1945.", "3cc05417"]},
"OLAYLAR_H7_ASAMA:1529-05-10:0":{"b": ["Salida de Solimán el Legislador a la campaña de Viena — la guerra contra los Habsburgo se reanudó", "f7afd2a9"], "d": ["Tras Mohács, el trono húngaro había quedado dividido en dos; Fernando había tomado Buda en 1527 y expulsado a Szapolyai de la capital. El sultán salió a campaña por cuarta vez para apoyar a Szapolyai y detener el avance de los Habsburgo; antes de la campaña se concedieron al gran visir İbrâhim Paşa el título de serasker y el beylerbeylik de Rumelia, y toda la planificación se hizo con él. Las lluvias torrenciales a lo largo del camino retrasaron el avance del ejército; la campaña continuó con la toma de Buda y su entrega a Szapolyai y con el asedio de Viena.", "4d80633a"]},
"OLAYLAR_H7_ASAMA:1562-05-05:0":{"b": ["Renovación de la paz con los Habsburgo — fin de la guerra de Transilvania y Temeşvar", "97071975"], "d": ["La guerra iniciada en 1551 con el paso de Transilvania a Fernando y proseguida con campañas como la conquista de Temeşvar y el asedio de Eger se cerró con la decisión de continuar la paz con los Habsburgo. El acuerdo renovaba recíprocamente los compromisos antiguos de ambas partes; pero no aportó solución a los disturbios en las fronteras y, tras la muerte de Fernando en 1564, los sucesos de Transilvania volvieron a aumentar.", "04cfeca8"]},
"OLAYLAR_H7_ASAMA:1566-05-01:0":{"b": ["La última campaña de Solimán el Legislador — salida de Estambul con Szigetvár y Eger como objetivo", "31277d21"], "d": ["Tras la muerte de Fernando en 1564 y el acceso al trono de Maximiliano II, los enfrentamientos en la frontera de Transilvania habían aumentado. En la campaña que el anciano sultán planeó con Sokullu Mehmed Paşa, el objetivo serían las fortalezas de Szigetvár y Eger, y también se intimidaría al emperador. Tras orar en el mausoleo de Eyüp Sultan, partió de Estambul con gran ceremonia; el 15 de mayo llegó a Edirne y en el quincuagésimo día de su marcha alcanzó Belgrado. Fue su última salida de la capital, que no volvería a ver.", "c601608a"]},
"OLAYLAR_H7_ASAMA:1568-02-17:0":{"b": ["Tratado de Edirne — fin del estado de guerra con los Habsburgo", "d08883e3"], "d": ["Tras la campaña de Szigetvár, ante Selim II, que invernaba en Edirne, se hallaban los embajadores de los Habsburgo, los safávidas, Polonia, Francia y Venecia. Se decidió que la paz con los safávidas continuara; se firmó el tratado que puso fin al estado de guerra con los Habsburgo. En estos asuntos fue grande la influencia del gran visir Sokullu Mehmed Paşa.", "27b65c0e"]},
"OLAYLAR_H7_ASAMA:1578-01-02:0":{"b": ["Decisión de la campaña de Irán — se nombraron dos serdares contra los safávidas, sacudidos por la muerte de Tahmasp", "1f09b186"], "d": ["Con el envenenamiento del sah Tahmasp I en 1576 al término de las disputas entre la dinastía y los notables del Estado, los safávidas habían sido arrastrados a una gran confusión; esto determinó la dirección de la campaña que se iba a abrir. Lala Mustafa Paşa fue encargado de entrar en Irán por Erzurum y Koca Sinan Paşa por Bagdad. Al aumentar la rivalidad entre los dos visires, intervino Sokullu: Sinan Paşa fue relevado y Lala Mustafa Paşa fue encargado de la conquista de Shirvan por Georgia. Esta decisión es la apertura de la guerra otomano-safávida de 1578-1590.", "3157145f"]},
"OLAYLAR_H7_ASAMA:1604-06-15:0":{"b": ["Cigalazâde Sinan Paşa partió a la campaña de Irán", "1e90763e"], "d": ["Mientras proseguía la guerra en dos frentes con Irán y Austria, el sah Abbás había tomado Erevan tras sitiarla, había entrado en Kars, pero solo había podido ser detenido ante Ahıska. Cigalazâde Sinan Paşa, nombrado serdar de Oriente, partió con retraso de Estambul y el 8 de noviembre llegó ante Kars. Aunque la situación era favorable, no marchó contra el sah sino que invernó en Van; ante el ataque del sah pasó a Erzurum, y se perdió una temporada de campaña.", "d155e6f3"]},
"OLAYLAR_H7_ASAMA:1605-11-06:0":{"b": ["Derrota de Cigalazâde Sinan Paşa cerca del lago Urmía (Sûfiyân)", "7438fec4"], "d": ["La situación de Sinan Paşa, que marchaba en la temporada de campaña de 1605 para recuperar Tabriz, se quebró cuando el beylerbeyi de Erzurum, Köse Sefer Paşa, se movió separado del ejército principal y cayó prisionero. El ataque repentino del sah Abbás infligió al ejército una pesada derrota en los alrededores del lago Urmía; Sinan Paşa se retiró primero a Van y luego a Diyarbekir. El hecho de que hiciera ejecutar al beylerbeyi de Alepo, Canbolatoğlu Hüseyin Paşa, por haber llegado tarde en su auxilio, encendió una gran rebelión en Anatolia; tras la muerte de Sinan Paşa, el sah Abbás tomó Ganja, Shirvan y Shamakhi.", "8e130829"]},
"OLAYLAR_H7_ASAMA:1610-03-26:0":{"b": ["Campaña de Kuyucu Murad Paşa contra Tabriz — no hubo encuentro en Acıçay", "3c0a0a5d"], "d": ["El gran visir Kuyucu Murad Paşa, que había reprimido las rebeliones celâlíes y asegurado la calma en Anatolia, marchó por Erzurum, Hasankale, Chaldiran y Hoy contra el sah Abbás, de quien se supo que lo esperaba en Tabriz. Los dos ejércitos se encontraron frente a frente en el paraje de Acıçay, al norte de Tabriz, pero no hubo combate; la correspondencia continuó. Ante la proximidad del invierno y la escasez de munición y provisiones, el pasha se retiró a Diyarbekir por Ahlat, Van y Bitlis, y murió allí al año siguiente, en verano, cuando preparaba una nueva campaña (5 de agosto de 1611).", "289fa3b6"]},
"OLAYLAR_H7_ASAMA:1615-04-23:0":{"b": ["Se reanudó la guerra otomano-safávida — el gran visir Öküz Mehmed Paşa partió a la campaña de Oriente", "ef32fa31"], "d": ["Como no llegaban noticias de İncili Mustafa Çavuş, enviado como embajador a Irán tras el Tratado de Nasuh Paşa de 1612, el gran visir Mehmed Paşa fue encargado de la campaña de Oriente y, completados los preparativos, pasó a Üsküdar. Justo cuando se ponía en marcha llegó la noticia de que İncili Çavuş y el embajador de Irán, Burun Kāsım Han, habían llegado a Van con un acuerdo y regalos, pero la campaña no se aplazó. El gran visir pasó el invierno en Alepo.", "5c279a1a"]},
"OLAYLAR_H7_ASAMA:1616-09-12:0":{"b": ["Asedio de Erevan — levantado sin resultado tras cincuenta y cinco días", "64a4ecb6"], "d": ["El gran visir, que en abril de 1616 salió de Alepo con un gran ejército, llegó ante Erevan por la ruta de Erzurum y Kars. Pensando que la fortaleza se rendiría con facilidad, no se llevaron cañones pesados; el asedio duró cincuenta y cinco días sin material. Con el martirio del aga de los jenízaros Muslu Ağa y de Tekeli Mehmed Paşa, la desgana de los soldados y el avance de la estación, se levantó el asedio y el ejército se retiró a Erzurum. Mehmed Paşa fue destituido en noviembre de 1616 y le sucedió Halil Paşa.", "823b20af"]},
"OLAYLAR_H7_ASAMA:1618-09-10:0":{"b": ["Derrota de Serav (Pul-i Şikeste) — campaña de Halil Paşa en Irán", "d323ed03"], "d": ["Halil Paşa, que había pasado a ser serdar en lugar de Öküz Mehmed Paşa, marchó de nuevo contra Irán en 1618. La batalla librada en el paraje de Pul-i Şikeste, entre Tabriz y Ardabil, terminó con la derrota del ejército otomano. Tras esta derrota, llamada también Batalla de Serav en las fuentes, se firmó ese mismo mes el Tratado de Serav.", "f2c187de"]},
"OLAYLAR_H7_ASAMA:1625-11-13:0":{"b": ["Asedio de Bagdad por Hâfız Ahmed Paşa — duró siete meses y veinte días, sin resultado", "764acb0a"], "d": ["Los otomanos, que habían perdido Bagdad en 1623, marcharon para recuperar la ciudad al mando del gran visir y serdar Hâfız Ahmed Paşa. Como en el consejo reunido en Kirkuk no fue aceptada primero la propuesta de ocupar los desfiladeros, el ejército sitió directamente Bagdad. El pasha entraba personalmente en las trincheras; aunque en el septuagésimo segundo día se penetró en la ciudad por una mina detonada, los soldados fueron rechazados. Cuando en marzo de 1626 el sah Abbás llegó en auxilio con 30.000 hombres, el ejército quedó entre dos fuegos; en el ataque del sah del 7 de junio se sufrieron graves pérdidas. Agotadas las provisiones y diezmado el ejército por el calor y las fiebres, se levantó el asedio y el ejército se retiró a Diyarbekir.", "350e3f52"]},
"OLAYLAR_H7_ASAMA:1630-10-06:0":{"b": ["Asedio de Bagdad por Hüsrev Paşa — levantado tras treinta y nueve días", "18de5581"], "d": ["El gran visir Hüsrev Paşa, que tras la victoria de Mihriban (5 de mayo de 1630) entró en Hamadán y la arrasó e incendió, en lugar de marchar sobre Qazvín volvió hacia el objetivo principal, Bagdad, por decisión del consejo de guerra reunido en Dergezîn. El ejército, que a comienzos de agosto llegó a los alrededores de Bagdad, sitió la ciudad el 6 de octubre. Se sufrieron grandes pérdidas en la salida de la guarnición iraní del 26 de octubre y en el asalto general del 9 de noviembre; este segundo asedio, posterior a la pérdida de Bagdad, también fue levantado sin resultado. El ejército se retiró a Mosul.", "4b3ed1a0"]},
"OLAYLAR_H7_ASAMA:1700-01-01:0":{"b": ["Lepanto (İnebahtı) fue devuelta a los otomanos en virtud de Karlowitz (Karlofça)", "9ca4f9dd"], "d": ["Lepanto, que tras resistir largo tiempo durante las guerras de 1683-1699 cayó en julio de 1687, con las fortalezas cercanas, en manos de Venecia, permaneció en poder de los venecianos hasta un año después del Tratado de Karlowitz y luego volvió a los otomanos. La fortaleza, situada en la boca del golfo de Corinto, recobró así la administración otomana quince años antes que la Morea.", "782654b8"]},
"OLAYLAR_H7_ASAMA:1733-07-19:0":{"b": ["Topal Osman Paşa venció a Nâdir en Dücum — se levantó el asedio de Bagdad", "7ae1fc9e"], "d": ["Contra Nâdir, que sitiaba Bagdad en enero de 1733, el ejército al mando de Topal Osman Paşa, enviado en auxilio de Bagdad, derrotó a las fuerzas de Nâdir en Dücum, cerca de Samarra; Nâdir, herido, se retiró a Hamadán y se levantó el asedio que duraba meses. Pero la victoria fue breve: a finales del mismo año Nâdir entró de nuevo en Irak y derrotó a las fuerzas otomanas en Akderbend, al norte de Kirkuk; Topal Osman Paşa perdió la vida durante estas batallas y fue enterrado en Kirkuk.", "6444aec6"]},
"OLAYLAR_H7_ASAMA:1743-02-25:0":{"b": ["Campaña de Nâdir Shah en Irak — comenzó la última guerra otomano-iraní, cayó Kirkuk", "ba014bf5"], "d": ["Nâdir Shah, que permaneció dieciocho meses en Daguestán y Georgia, habiendo rechazado los otomanos su petición de que el yafarismo fuera reconocido como quinta escuela jurídica, inició en 1743 una nueva campaña contra los otomanos y entró en Kirkuk con un gran ejército. No pudo repetir el mismo éxito en Mosul; tuvo que levantar el asedio. Esta guerra es la última guerra otomano-iraní, que terminó con el Tratado de Kerden de 1746.", "5515afec"]},
"OLAYLAR_H7_ASAMA:1744-07-29:0":{"b": ["Asedio de Kars por Nâdir Shah — duró dos meses, sin resultado", "a3ea61d9"], "d": ["El príncipe safávida Sâfî Mirza, refugiado entre los otomanos, reclamaba derechos sobre el trono de Irán; según el plan, el seraskier de Kars lo llevaría por Tabriz hasta Isfahán para entronizarlo y los otomanos habían abierto tres frentes contra Irán. Ante esto, Nâdir Shah marchó sobre Kars y sitió la fortaleza. No obtuvo resultado alguno de un asedio que duró dos meses.", "42fc48b5"]},
"OLAYLAR_H7_ASAMA:1745-08-21:0":{"b": ["Derrota de Kağaverd — el ejército de Yeğen Mehmed Paşa se dispersó", "7caf6f22"], "d": ["Al año siguiente del asedio de Kars, Nâdir Shah infligió una derrota a las fuerzas otomanas bajo la dirección de Yeğen Mehmed Paşa en el paraje de Kağaverd. Después regresó a Isfahán. El que renunciara a su insistencia en el reconocimiento del yafarismo abrió al año siguiente el camino al Tratado de Kerden.", "3992b8ed"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["Las fuerzas saudí-wahabíes se apoderaron del emirato de Ha'il — el gobierno estaba en la familia Ibn Ali, de la tribu Abde", "2d29ceb9"], "d": ["Cuando las fuerzas del Primer Estado Saudí se apoderaron del emirato de Ha'il, el gobierno de la ciudad estaba en manos de la familia Ibn Ali, del clan Abde de la tribu Shammar. Esta familia gobernó Ha'il hasta que Abdullah b. Rashid se apoderó del emirato en 1835; la dinastía de los Rashidíes se fundó solo en esa fecha. En el atlas, Ha'il aparecía hasta hoy sin dueño hasta 1836, cuando la fuente da el nombre de su emir en 1820.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["Paso de las islas del Quarnero al Reino de Italia de Napoleón y de las Bocas de Kotor a la administración rusa", "c5e411c8"], "d": ["Tras el Tratado de Presburgo, las islas del Quarnero —a diferencia de Dalmacia— no fueron ligadas directamente a Francia sino al Reino de Italia de Napoleón; solo entraron en las Provincias Ilirias en 1809. En las Bocas de Kotor, en cambio, terminó la administración austriaca y se estableció entre 1806 y 1807 la administración rusa; las Bocas pasaron a Francia solo en 1807. Estas dos distinciones no pueden ser cubiertas con una sola ventana «Francia» del atlas.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["Paso de Dalmacia a la administración francesa — aplicación del Tratado de Presburgo (Bratislava)", "00bfe4f6"], "d": ["El Tratado de Presburgo (Bratislava/Pressburg) del 26 de diciembre de 1805 obligó a Austria a renunciar a Istria, Dalmacia y todas las islas del Adriático. Francia asumió de hecho la administración en febrero de 1806; Zadar siguió siendo sede del proveedor general, cargo que ejerció entre 1806 y 1810 el veneciano Vicenzo Dandolo. Dalmacia fue incorporada a las Provincias Ilirias después del Tratado de Schönbrunn de 1809. Así terminó la primera administración austriaca, que duraba desde 1797 — en el atlas este período aparecía hasta hoy como austriaco sin interrupción.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["Recuperación por Austria de las Provincias Ilirias y de Dalmacia — fin de la administración napoleónica", "1b2ac942"], "d": ["A finales de 1813 las tropas de los Habsburgo recuperaron la región al sur del Sava y se restableció la antigua organización fronteriza; el ejército austriaco entró en Istria en octubre de 1813. Desde entonces Karlovac pasó a formar parte del Reino de Iliria austriaco. El período de la administración francesa en Dalmacia se cerró también en 1813. La pertenencia de la región a Austria fue oficialmente confirmada por las decisiones de la Paz de París de 1814 y del Congreso de Viena de 1815.", "a5c337df"]},
"OLAYLAR_KAMERIKA:1535-04-17:0":{"b": ["Se crea el Virreinato de Nueva España", "d86e1ae4"], "d": ["El rey de España Carlos V creó el Virreinato de Nueva España al someter directamente a la administración real los territorios conquistados de México y nombró a Antonio de Mendoza primer virrey. Este ordenamiento puso fin al orden basado en el dominio personal de los conquistadores. Con su centro en México, los límites del virreinato abarcaban México, la península de Yucatán y las regiones de Guatemala.", "a4ad96e7"]},
"OLAYLAR_KAMERIKA:1762-11-03:0":{"b": ["Tratado de Fontainebleau — Luisiana cedida a España", "c96ae72d"], "d": ["Hacia el final de la guerra de los Siete Años, Francia cedió a España mediante un tratado secreto Luisiana, al oeste del Misisipi, y Nueva Orleans. Así terminó de hecho la presencia de Francia en América del Norte: al año siguiente el Tratado de París entregaría a Gran Bretaña la orilla oriental del río.", "18ac5acb"]},
"OLAYLAR_KAMERIKA:1803-01-01:0":{"b": ["Fundación de Fort William — centro interior de la Compañía del Noroeste", "41157d26"], "d": ["La Compañía del Noroeste, al quedar Grand Portage en territorio de Estados Unidos, trasladó su centro interior al norte del lago Superior y fundó Fort William. El puesto era el lugar de la reunión anual en que se encontraban las canoas llegadas de Montreal y las pieles procedentes del interior, y se convirtió en el corazón de la red continental de la compañía.", "72d44bb1"]},
"OLAYLAR_KAMERIKA:1803-01-01:1":{"b": ["Fundación de Fort Dearborn — puesto de Estados Unidos en el paso de Chicago", "1f5f943b"], "d": ["El ejército de Estados Unidos fundó Fort Dearborn en el paso de Chicago, que une el lago Míchigan con la cuenca del Misisipi. El paso era conocido y utilizado desde la década de 1670; la fortaleza marcó la extensión hacia el oeste del control de Estados Unidos en el Territorio del Noroeste.", "c067e27f"]},
"OLAYLAR_KAMERIKA:1803-01-01:2":{"b": ["Fundación de Fort George (Chisasibi) — costa oriental de la bahía de James", "bbf75f94"], "d": ["La Compañía de la Bahía de Hudson fundó Fort George en la desembocadura del río La Grande, en la costa oriental de la bahía de James. El puesto permitió a los grupos cree del interior comerciar sin bajar a la costa y completó la línea costera oriental de la compañía.", "4a44c409"]},
"OLAYLAR_KAMERIKA:1829-01-01:0":{"b": ["Fundación de Fort Halkett — línea de pieles a lo largo del Liard", "de534aa9"], "d": ["La Compañía de la Bahía de Hudson fundó Fort Halkett sobre el río Liard y prolongó así la línea de pieles que iba de la cuenca del Mackenzie al oeste de las Rocosas. El puesto era uno de los emplazamientos avanzados más occidentales de la compañía, en tierras de los kaska dene.", "b47a58dd"]},
"OLAYLAR_KAMERIKA:1829-01-01:1":{"b": ["Fundación de Fort Pitt — centro de carne de bisonte y pieles en el Saskatchewan Norte", "0fca471b"], "d": ["La Compañía de la Bahía de Hudson fundó Fort Pitt a orillas del Saskatchewan Norte para cerrar el hueco entre Fort Carlton y Fort Edmonton. El puesto se convirtió en uno de los principales centros de suministro de pemmican y en el nudo del comercio entre los cree de las llanuras y la compañía.", "4806ba8d"]},
"OLAYLAR_KAMERIKA:1829-01-01:2":{"b": ["Fundación de Springfield — primer asentamiento permanente en la meseta de Ozark", "49557b40"], "d": ["Springfield fue fundada en la meseta de Ozark, en el extremo oriental de las tierras de los osage, en el suroeste de Misuri. El asentamiento se convirtió en el centro de la migración hacia las tierras abiertas después de que los osage abandonaran la región en 1825, y llegó a ser la población principal del suroeste de Misuri.", "74ee2fe5"]},
"OLAYLAR_KAMERIKA:1851-09-17:0":{"b": ["Tratado de Fort Laramie — se trazan los límites en las Grandes Llanuras del Norte", "791662bf"], "d": ["El tratado firmado entre Estados Unidos y los pueblos de las Grandes Llanuras del Norte definió por primera vez por escrito los límites de las tierras de los lakota, crow, mandan, hidatsa, arikara, cheyenne, arapaho y assiniboine, y vinculó a cambio la seguridad de las rutas de los colonos. Los límites fueron rebasados en poco tiempo.", "ccb46cba"]},
"OLAYLAR_KAMERIKA:1868-07-03:0":{"b": ["Tratado de Fort Bridger — se crea la reserva de Wind River", "daa3f132"], "d": ["El tratado firmado con Estados Unidos por los shoshones orientales y los bannock reconoció a los shoshones, liderados por Washakie, una reserva en la cuenca de Wind River. Los shoshones, a diferencia de los otros pueblos que combatían a Estados Unidos en las llanuras, habían elegido el camino de la alianza y por ello habían conservado una parte de su patria. El tratado determinó el estatuto jurídico de las tierras shoshones de la parte norte de la Gran Cuenca.", "e37c9fa3"]},
"OLAYLAR_KAMERIKA:1880-09-01:0":{"b": ["Gran Bretaña cede el archipiélago ártico a Canadá", "f8a7cb12"], "d": ["Por decisión del Consejo Real británico, todas las islas del norte de América del Norte y sus derechos fueron cedidos al Dominio de Canadá. La decisión fue el último paso que completó la cesión de la Tierra de Rupert en 1870 y estableció sobre el papel los límites septentrionales actuales de Canadá. La cesión se hizo sin consultar a las comunidades inuit que vivían en esas tierras y la administración efectiva no se estableció durante décadas.", "4cb3cc28"]},
"OLAYLAR_KI117:1684-08-24:0":{"b": ["Yazlofça pasa a manos polacas", "c86581e5"], "d": ["En la campaña de Sobieski a Moldavia, el ejército polaco recuperó, tras un asedio de dos días, Yazlofça, que estaba en manos otomanas desde 1672. Así comenzó la disolución del sanjacado de Kamaniçe.", "98482094"]},
"OLAYLAR_KI117:1684-11-03:0":{"b": ["Pest vuelve a manos otomanas", "13914c49"], "d": ["Pest, en la que habían entrado las tropas de los Habsburgo en junio de 1684, volvió al control otomano a principios de noviembre de 1684 tras el fracaso del asedio de Buda; los Habsburgo entrarían definitivamente en Pest en 1686.", "41164adc"]},
"OLAYLAR_KI117:1686-01-01:0":{"b": ["Evacuación otomana de la fortaleza de Medzhybizh", "2c4b5a7f"], "d": ["La fortaleza de Medzhybizh, en Podolia, fue evacuada por los otomanos en 1686; al retirarse intentaron hacerla saltar por los aires. Terminó el dominio otomano de unos ocho años.", "27fe058d"]},
"OLAYLAR_KI117:1686-06-17:0":{"b": ["La caballería de los Habsburgo entró en Pest: preparativos previos al asedio de Buda", "c9d23487"], "d": ["La vanguardia del ejército de los Habsburgo que se preparaba para el asedio de Buda, la caballería bávara, entró en Pest, abandonada por la guarnición otomana; la orilla oriental del Danubio pasó definitivamente al control de los Habsburgo. La propia Buda caería el 2 de septiembre.", "9329e3b2"]},
"OLAYLAR_KI117:1686-10-01:0":{"b": ["Mohács pasa al control de los Habsburgo", "f022d9c0"], "d": ["En el avance de los Habsburgo al sur del Danubio tras la caída de Buda, Mohács pasó en el otoño de 1686 al control de los aliados; el verano siguiente el ejército intentaría resistir en esta línea en Harsány (1687).", "06cb2407"]},
"OLAYLAR_KI117:1687-07-01:0":{"b": ["Naupacto (Lepanto) pasa a Venecia", "8daedb90"], "d": ["Tras la caída de Patrás, Naupacto, en la boca del golfo de Corinto, fue también abandonada por los otomanos y pasó al control de Venecia; sería devuelta por el Tratado de Karlowitz de 1699.", "2b368884"]},
"OLAYLAR_KI117:1689-09-11:0":{"b": ["Baden llegó a Jagodina: el corredor del Morava entró en la línea austríaca", "a6459b85"], "d": ["Tras la derrota de Batočina (30 de agosto), el ejército otomano se retiró al sur; Baden llegó a Jagodina el 11 de septiembre de 1689 y tendió un puente sobre el Morava. La línea austríaca se extendió hasta Niš por Jagodina–Ćuprija–Paraćin; Alacahisar, en cambio, quedó fuera de la línea.", "9badb3bd"]},
"OLAYLAR_KI117:1690-08-29:0":{"b": ["Dursun Mehmed Paşa entró en Vidin: la orilla del Danubio vuelve a ser otomana", "2b4d5344"], "d": ["En la contraofensiva de Fâzıl Mustafa Paşa, el ejército de tierra de Dursun Mehmed Paşa, mutasarrıf de Karaman, y la flota del Danubio de Mezemorta Hüseyin Paşa recuperaron Vidin a Austria.", "d76ac495"]},
"OLAYLAR_KI117:1690-09-01:0":{"b": ["El paşa de Rumelia entró en la fortaleza de Orsova", "3884232b"], "d": ["Con la retirada del ejército austríaco de Serbia a finales de agosto de 1690, el paşa de Rumelia volvió a tomar Orsova; la orilla del Danubio en el Banat volvió al control otomano.", "541ca167"]},
"OLAYLAR_KI117:1690-09-17:0":{"b": ["Las fortalezas de Valona y Kanina cayeron en manos de Venecia", "51bf7b50"], "d": ["Mientras la contraofensiva otomana continuaba en Serbia, la flota y las fuerzas venecianas tomaron Valona y Kanina, en la costa de Albania; en marzo de 1691 las dos fortalezas serían destruidas y abandonadas.", "238bd38c"]},
"OLAYLAR_KI117:1691-03-15:0":{"b": ["Venecia destruyó las fortalezas tomadas en Albania y se retiró", "378490dd"], "d": ["Los venecianos, que habían tomado Valona y Kanina el 17 de septiembre de 1690, destruyeron las fortalezas y se retiraron a mediados de marzo de 1691; el sur de Albania volvió al control otomano.", "aa90ce2d"]},
"OLAYLAR_KI117:1695-01-01:0":{"b": ["Kızıkermen pasa a manos rusas", "2b90f9af"], "d": ["En la operación en la línea del Dniéper, simultánea a la campaña rusa de Azov, Sheremétev y Mazepa tomaron Kızıkermen; la fortaleza permaneció en manos rusas hasta el Tratado de Constantinopla de 1700.", "c310dfdd"]},
"OLAYLAR_KI117:1695-01-12:0":{"b": ["Rendición de Gyula a los Habsburgo", "e378c570"], "d": ["Gyula, sitiada, firmó la capitulación el 21 de diciembre de 1694; el 12 de enero de 1695 la guarnición salió y entraron las tropas de los Habsburgo. La fortaleza estuvo hasta Karlowitz (1699) en manos de los Habsburgo, no de los otomanos.", "5e4c275b"]},
"OLAYLAR_KI117:1699-09-22:0":{"b": ["Entrega de Kamaniçe a Polonia", "05950f7a"], "d": ["En virtud del Tratado de Karlowitz del 26 de enero de 1699, la evacuación de Podolia se completó en septiembre; las llaves de Kamaniçe fueron entregadas a la comisión polaca el 22 de septiembre de 1699. El paso a Polonia, junto con las fortalezas dependientes del sanjacado (Bar, Medzhybizh, Yazlofça), se hizo efectivo en este día.", "15c85c1d"]},
"OLAYLAR_KRONOEKSIK0921:1603-06-07:0":{"b": ["Estrangulamiento del príncipe Mahmud", "9fc2fdb5"], "d": ["Mehmed III, sospechando que su hijo mayor, el príncipe Mahmud, codiciaba el trono y podía destronarlo, lo hizo estrangular; la madre del príncipe y unas treinta de sus sirvientas fueron arrojadas al mar. En medio de las rebeliones celalíes y de la inquietud en Anatolia, el sultán había visto que el ejército se inclinaba hacia el príncipe; se registra también que la sultana madre (valide sultan) estaba molesta con la madre del príncipe. Esta ejecución es uno de los últimos eslabones del camino que, seis meses después, con la muerte de Mehmed III, dejó en el trono únicamente a Ahmed I, de trece años, y puso fin de hecho a la tradición del fratricidio.", "bacf93cd"]},
"OLAYLAR_KRONOEKSIK0921:1621-01-01:0":{"b": ["Un invierno sin precedentes — congelación del Bósforo de Estambul", "9e4fb488"], "d": ["Mientras continuaban los preparativos de la campaña de Polonia, Estambul vivió un invierno sin precedentes: el estrecho se heló y en la ciudad no se encontraban alimentos ni bebidas. El gran visir Güzelce Ali Paşa, que temía por su vida a causa de las dificultades en el mercado, murió el 15 de rebiülâhir (9 de marzo), poco después de que el tiempo mejorase y la situación se normalizara, y fue sustituido por Ohrili Hüseyin Paşa. El otağ (tienda imperial) fue instalado el 7 de cemaziyelâhir (29 de abril) en la llanura de Dâvud Paşa; la campaña que llevaría a Osman II a Hotin comenzó después de este invierno.", "146293da"]},
"OLAYLAR_KRONOEKSIK0921:1826-04-08:0":{"b": ["Conclusión de la construcción de la mezquita de Nusretiye", "30dfdc64"], "d": ["La construcción de la mezquita imperial (selâtin) que Mahmud II hizo edificar en Tophane se terminó el 8 de abril de 1826; el edificio sustituyó al mescit del cuartel de Tophane, destruido por el gran incendio del 24 de febrero de 1823, y su construcción se había iniciado en junio de 1823. Su arquitecto fue Krikor Amira Kalfa, de la familia Balyan; se considera uno de los ejemplos más vistosos del estilo imperio en la arquitectura de mezquitas otomana. El 14 de mayo de 1826 los alminares fueron derribados hasta el balcón inferior y reconstruidos más altos; el nombre «Nusretiye» (victoria) de la mezquita se le dio en junio de ese mismo año en memoria de la abolición del cuerpo de jenízaros, y entre el pueblo se la conoce como mezquita de Tophane.", "3043db31"]},
"OLAYLAR_KRONOEKSIK0921:1883-11-03:0":{"b": ["Fundación de la Escuela de Ingeniería Civil (Hendese-i Mülkiyye Mektebi)", "abfa076e"], "d": ["Tras la guerra otomano-rusa de 1877-78, Abdülhamid II fundó el 3 de noviembre de 1883 la Escuela de Ingeniería Civil (Hendese-i Mülkiyye Mektebi) con el fin de formar ingenieros de entre los turcos y los musulmanes. La escuela institucionalizó la formación en ingeniería civil como una institución separada, junto a las escuelas de ingeniería militares; la ceremonia de inauguración de su propio edificio se celebró el 29 de octubre de 1884. En 1909 fue sustraída a la administración militar, quedó vinculada al Ministerio de Obras Públicas (Nâfia Nezâreti) y recibió el nombre de Escuela Superior de Ingeniería (Mühendis Mekteb-i Âlîsi).", "48cf01ce"]},
"OLAYLAR_KUNFUZE_1016:1814-03-01:0":{"b": ["Las fuerzas de Mehmed Ali tomaron Al Qunfudhah a los wahabíes", "fbeec58b"], "d": ["La expedición naval que partió de Yeda tomó sin derramamiento de sangre Al Qunfudhah, que desde hacía cinco años estaba en manos del jeque de Asir, Tâmî.", "fa0c98f2"]},
"OLAYLAR_KUNFUZE_1016:1814-05-01:0":{"b": ["Ataque por sorpresa de Tâmî: la guarnición egipcia se retiró a los barcos", "4dcc360c"], "d": ["La fuerza wahabí al mando de Tâmî derrotó a los soldados albaneses que custodiaban los pozos; las fuerzas egipcias huyeron a los barcos y los cañones y los bagajes quedaron en manos de los wahabíes.", "63048c2e"]},
"OLAYLAR_KUNFUZE_1016:1815-03-01:0":{"b": ["Mehmed Ali entró en Al Qunfudhah tras la victoria de Bisel", "916105b7"], "d": ["El ejército, que marchó hacia el sur después de Bisel, llegó a Al Qunfudhah; Tâmî, capturado, fue llevado allí, y el ejército regresó de allí a La Meca.", "9e1ae360"]},
"OLAYLAR_KUNFUZE_1016:1840-05-09:0":{"b": ["El ejército egipcio se retiró de Tihama", "1047f577"], "d": ["Por orden de evacuación, el ejército egipcio de Yemen abandonó Tihama; las ciudades costeras pasaron a manos del šarīf de Abū 'Arīsh.", "f6a889e6"]},
"OLAYLAR_KUNFUZE_1016:1871-03-01:0":{"b": ["La división de Redif Paşa desembarcó en Al Qunfudhah", "4a6ef114"], "d": ["La división de reserva, que pasó por el Canal de Suez, desembarcó en Al Qunfudhah, en manos de los Mughaydī, y desde allí marchó hacia las montañas de Asir.", "9de9bb79"]},
"OLAYLAR_KUNFUZE_1016:1916-07-18:0":{"b": ["Rendición de Al Qunfudhah a los barcos británicos", "265e164a"], "d": ["Tras el bombardeo de los buques de guerra británicos, la guarnición otomana se rindió; se izó la bandera de los Idrisí en la ciudad y unos días después se instaló una guarnición idrisí. En agosto, ante la objeción del šarīf Hüseyin, Inglaterra obligó a los Idrisí a retirarse.", "f88ff660"]},
"OLAYLAR_KUNFUZE_1016:1919-05-01:0":{"b": ["El rey Hüseyin del Hiyaz volvió a ocupar Al Qunfudhah", "a86c61fa"], "d": ["Se enviaron funcionarios del Hiyaz a Al Qunfudhah, que había permanecido vacía durante la guerra; los Idrisí protestaron.", "c93e8a47"]},
"OLAYLAR_KURULUS_GERI_1021:0630-01-11:0":{"b": ["La Meca fue conquistada: la ciudad pasó al Estado de Medina", "8435e73c"], "d": ["El Profeta conquistó La Meca (20 Ramadán 8 / 11 de enero de 630).", "865a73bd"]},
"OLAYLAR_KURULUS_GERI_1021:0632-06-08:0":{"b": ["Muerte del Profeta: La Meca quedó vinculada a los califas rashidún", "b65e8cd1"], "d": ["Muhammad murió el 13 Rabi' al-awwal 11 / 8 de junio de 632; La Meca entró bajo la administración de los califas rashidún.", "99716bea"]},
"OLAYLAR_KURULUS_GERI_1021:0638-01-01:0":{"b": ["Se fundó Kufa", "617d0f35"], "d": ["Kufa fue establecida como ciudad-guarnición generalmente en el año 17 (638); se convirtió en el centro de los califas rashidún en Irak (día desconocido).", "abaf8837"]},
"OLAYLAR_KURULUS_GERI_1021:0661-01-01:0":{"b": ["Alí fue martirizado en Kufa; Kufa pasó al dominio omeya", "94fb307d"], "d": ["Alí fue martirizado por Ibn Muljam en la mezquita de Kufa (661); se cerró el período rashidún y la ciudad entró bajo la administración omeya (precisión de año; el interregno zubayrí de 680-691 no se registró aparte).", "a58ed98f"]},
"OLAYLAR_KURULUS_GERI_1021:0661-07-29:0":{"b": ["Mu'awiya recibió el juramento de fidelidad: La Meca entró bajo dominio omeya", "d6dcc232"], "d": ["Mu'awiya recibió el juramento de fidelidad el 25 Rabi' al-awwal 41 / 29 de julio de 661; La Meca quedó vinculada a los gobernadores omeyas (no hay un día específico para La Meca, es el día del Estado).", "16cecb18"]},
"OLAYLAR_KURULUS_GERI_1021:0670-01-01:0":{"b": ["Se fundó Kairuán (Uqba b. Nafi, omeya)", "7409e9ae"], "d": ["El gobernador omeya Uqba b. Nafi fundó Kairuán en 670 como base de Ifriqiya.", "b2240f4e"]},
"OLAYLAR_KURULUS_GERI_1021:0683-11-27:0":{"b": ["Ibn al-Zubayr proclamó su califato en La Meca: La Meca salió de los omeyas", "9e31ca5c"], "d": ["La noticia de la muerte de Yazid llegó a La Meca (27 de noviembre de 683); Abd Allah b. al-Zubayr proclamó un califato con centro en La Meca (64/683).", "212a96b5"]},
"OLAYLAR_KURULUS_GERI_1021:0692-10-01:0":{"b": ["Al-Hayyay tomó La Meca: la ciudad entró de nuevo bajo dominio omeya", "48dd6e68"], "d": ["Al final del asedio de Al-Hayyay b. Yusuf, La Meca volvió a entrar bajo dominio omeya el 14 Yumada al-ula 73 / 1 de octubre de 692.", "25eedec5"]},
"OLAYLAR_KURULUS_GERI_1021:0745-01-01:0":{"b": ["Abd al-Rahman b. Habib se sublevó: Kairuán salió de la administración omeya", "4c7a0da0"], "d": ["Con la sublevación de Abd al-Rahman b. Habib en 745, Kairuán salió del gobierno omeya; hasta 761 hubo un período intermedio habibí/jariyí (vacío con propietario declarado).", "69dac839"]},
"OLAYLAR_KURULUS_GERI_1021:0749-09-02:0":{"b": ["El ejército abasí tomó Kufa", "0191709e"], "d": ["El ejército abasí tomó Kufa el 14 Muharram 132 (2 de septiembre de 749); la ciudad pasó de los omeyas a los abasíes.", "998fc494"]},
"OLAYLAR_KURULUS_GERI_1021:0750-08-05:0":{"b": ["Terminó el Estado omeya: La Meca pasó al dominio abasí", "382e4d6e"], "d": ["El último califa omeya, Marwan II, fue asesinado el 26 Dhu l-hiyya 132 / 5 de agosto de 750; La Meca entró en el gobierno abasí de los Haramain (no hay un día específico para La Meca — es el día del fin del Estado, aproximación declarada).", "710c6ec7"]},
"OLAYLAR_KURULUS_GERI_1021:0761-01-01:0":{"b": ["Muhammad b. al-Ash'ath, nombrado por los abasíes, tomó Kairuán", "71af9f79"], "d": ["Muhammad b. al-Ash'ath tomó Kairuán en nombre de los abasíes en el año 144 (761).", "a71fe419"]},
"OLAYLAR_KURULUS_GERI_1021:0762-01-01:0":{"b": ["El califa Mansur comenzó la construcción de Bagdad (Madinat al-Salam)", "844a94d5"], "d": ["Las obras de construcción de la ciudad fundada a orillas del Tigris comenzaron en 762; se convirtió en la capital permanente de los abasíes (día desconocido, solo el año está confirmado).", "750c6eb1"]},
"OLAYLAR_KURULUS_GERI_1021:0800-01-01:0":{"b": ["Ibrahim b. al-Aghlab se convirtió en gobernador: los aglabíes en Kairuán", "f7279ba9"], "d": ["Harún al-Rashid nombró a Ibrahim b. al-Aghlab gobernador de Ifriqiya; los aglabíes (800-909) hicieron de Kairuán su capital.", "3b6e9426"]},
"OLAYLAR_KURULUS_GERI_1021:0909-01-01:0":{"b": ["Los fatimíes tomaron Kairuán; fin de los aglabíes", "021693e0"], "d": ["En 909 Ziyadat Allah III huyó a Egipto; Kairuán pasó a los fatimíes.", "a6422efd"]},
"OLAYLAR_KURULUS_GERI_1021:0945-12-19:0":{"b": ["El buyí Ahmad (Mu'izz al-Dawla) entró en Bagdad; la ciudad pasó al dominio buyí", "31accd4a"], "d": ["Ahmad entró en Bagdad el 11 Yumada al-ula 334 (19 de diciembre de 945); el califa Mustakfí lo nombró emir al-umara y la ciudad pasó al dominio de los buyíes (Kufa también entró bajo dominio buyí en 945-1055; para Kufa el día se tomó de Bagdad, por vecindad).", "11f31be7"]},
"OLAYLAR_KURULUS_GERI_1021:0969-01-01:0":{"b": ["En La Meca se recitó el jutba en nombre de los fatimíes (358/969)", "3f069fea"], "d": ["El emir de La Meca Ja'far b. Muhammad hizo recitar el jutba en nombre de los fatimíes (358/969, precisión de año); los fatimíes como Estado soberano.", "2256892c"]},
"OLAYLAR_KURULUS_GERI_1021:0972-10-02:0":{"b": ["Los ziríes en Kairuán (Buluqqin b. Ziri, gobernador de Ifriqiya)", "5494e662"], "d": ["En nombre del califa fatimí, Buluqqin b. Ziri gobernó Ifriqiya; los ziríes (972-1057) dominaron Kairuán (el TDV da el año; el día se toma del f de la ficha).", "ffcba4c5"]},
"OLAYLAR_KURULUS_GERI_1021:1057-01-01:0":{"b": ["Saqueo hilalí: Mu'izz b. Badis se retiró a Mahdia; terminó el dominio zirí en Kairuán", "4dbbdff5"], "d": ["Hacia 449 (1057) los hilalíes saquearon Kairuán; los ziríes se retiraron a Mahdia; hasta 1229 el dueño de la ciudad no puede seguirse año por año en las fuentes (vacío declarado).", "8bebfdc7"]},
"OLAYLAR_KURULUS_GERI_1021:1085-05-25:0":{"b": ["Alfonso VI entró en Toledo: la ciudad pasó al dominio de Castilla", "3b72bb5f"], "d": ["Treccani: Alfonso VI entró en Toledo el 25 de mayo de 1085; dos años después la ciudad se convirtió en capital de Castilla (el TDV Tuleytula da solo el año: 478/1085; en la cronología de la cola figura aparte el día de la capitulación, 8 de mayo de 1085).", "fa2c9677"]},
"OLAYLAR_MISIR1801:1801-05-14:0":{"b": ["Toma de Damieta a los franceses: evacuación del fuerte de Lesbé", "06b1e7b0"], "d": ["Una fuerza al mando de Ibrahim Pasha, del ejército del gran visir, fue enviada a Damieta. Cuando el ataque contra el fuerte de Lesbé, que protegía Damieta, estaba preparado para la mañana del 14 de mayo, se vio que los franceses habían evacuado el fuerte y retirado la guarnición; también fueron tomados los dos fuertes menores que dependían de él. Damieta fue la segunda ciudad de las bocas del Nilo que salió del control francés, tras Rosetta, caída en abril.", "2eb4936c"]},
"OLAYLAR_MISIR1801:1801-06-27:0":{"b": ["Entrega de El Cairo por los franceses: capitulación de Belliard", "7a11bb5e"], "d": ["Durante la operación conjunta de las fuerzas otomanas y británicas contra Egipto, el general Belliard, comandante de las fuerzas francesas en El Cairo, firmó la capitulación. Junto con El Cairo, Suez, que los franceses habían tomado en noviembre de 1798, salió también del control francés. El fin de la ocupación se completaría dos meses después en Alejandría, y la evacuación del país duraría hasta octubre.", "e8dac3f4"]},
"OLAYLAR_MISIR1801:1801-08-31:0":{"b": ["Entrega de Alejandría por los franceses: capitulación de Menou", "cd50663c"], "d": ["El general Menou, comandante en jefe del Ejército de Oriente, fue sitiado en Alejandría el 17 de agosto; el 21 de agosto los británicos tomaron el fuerte de Marabout, cerca de la ciudad, y el 31 de agosto Menou firmó la capitulación del ejército. El regreso de las tropas francesas a Francia comenzó el 2 de septiembre. Así, la ocupación, que había comenzado con el desembarco en Alejandría en junio de 1798, terminó en la ciudad donde había empezado.", "22e807c1"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:0763-01-01:0":{"b": ["El duque de Nápoles Esteban II se vuelve de Constantinopla hacia Roma: el ducado se independiza de hecho", "5a181f23"], "d": ["El ducado de Nápoles, dependiente de Bizancio, se volvió hacia el Papa en 763, en tiempos de Esteban II, y se hizo de hecho autónomo (el primer duque, Basilio, había sido nombrado en 661).", "4202f3af"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1059-01-01:0":{"b": ["Cosenza pasa de Bizancio a los normandos: Ducado de Apulia y Calabria", "80b85c65"], "d": ["El ducado de Roberto Guiscardo (1059) abarcó Calabria; Cosenza pasó de Bizancio al ducado normando (no se leyó el día de conquista específico de la ciudad, nivel de año).", "97fda44a"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1059-01-01:1":{"b": ["Reggio Calabria pasa de Bizancio a los normandos: Ducado de Apulia y Calabria", "221f6474"], "d": ["El ducado de Roberto Guiscardo (1059) abarcó Calabria; Reggio pasó de Bizancio al ducado normando (no se leyó el día de conquista específico de la ciudad, nivel de año).", "31927a9e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1071-01-01:0":{"b": ["Brindisi pasa de Bizancio a los normandos: Ducado de Apulia", "52c14154"], "d": ["Con la conquista normanda de Bari en 1071 cayó el último bastión de Bizancio en Italia; Brindisi, vinculada a la cadena de Bari, se incorporó al ducado de Apulia (no se encontró una frase fechada específica de la ciudad).", "db68d985"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1071-01-01:1":{"b": ["Lecce pasa de Bizancio a los normandos: Ducado de Apulia", "73da4722"], "d": ["Con la conquista normanda de Bari en 1071 cayó el último bastión de Bizancio en Italia; Lecce, vinculada a la cadena de Bari, se incorporó al ducado de Apulia (no se encontró una frase fechada específica de la ciudad).", "e11ac323"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1099-01-01:0":{"b": ["Se funda en Génova la Compagna Communis: la ciudad pasa al gobierno comunal", "1cc30776"], "d": ["Los notables de Génova fundaron la Compagna Communis y organizaron el gobierno de la ciudad como comuna; comienzo de la República de Génova.", "952b5184"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:0":{"b": ["Tarento pasa del Ducado de Apulia al Reino de Sicilia (Roger II)", "3ecf982e"], "d": ["Roger II tomó en 1128 el ducado de Apulia y el principado de Tarento/Otranto/Brindisi de Bohemundo II (mayo-junio de 1128, fuente secundaria); mismo día que las cadenas de Bari y Salerno.", "b52e2957"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:1":{"b": ["Brindisi pasa del Ducado de Apulia al Reino de Sicilia (Roger II)", "6519178f"], "d": ["Roger II tomó en 1128 Brindisi, en el principado de Tarento de Bohemundo II (fuente secundaria); mismo día que las cadenas de Bari y Salerno.", "7adade28"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:2":{"b": ["Lecce pasa del Ducado de Apulia al Reino de Sicilia (Roger II; centro hermano Bari)", "22cdacd2"], "d": ["Lecce cambió de manos, vinculada a la cadena de Bari, con la incorporación del ducado de Apulia al Reino de Sicilia (1128); no se encontró una frase fechada específica de la ciudad.", "9c938986"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:3":{"b": ["Cosenza pasa del Ducado de Apulia y Calabria al Reino de Sicilia (Roger II)", "75da9e9c"], "d": ["Calabria pasó a formar parte del Reino de Sicilia (1128) con el traspaso del ducado de Apulia y Calabria a Roger II; no se encontró una frase fechada específica de la ciudad (cadena del centro hermano Bari/Melfi).", "e8b41ab1"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:4":{"b": ["Reggio Calabria pasa del Ducado de Apulia y Calabria al Reino de Sicilia (Roger II)", "37e6922f"], "d": ["Calabria pasó a formar parte del Reino de Sicilia (1128) con el traspaso del ducado de Apulia y Calabria a Roger II; no se encontró una frase fechada específica de la ciudad (cadena del centro hermano Bari/Melfi).", "e8b41ab1"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1143-01-01:0":{"b": ["Se funda la Comuna de Roma: renovación del senado (renovatio senatus), se suspende la soberanía temporal del Papa", "b54d2c34"], "d": ["El pueblo de Roma restableció en el Capitolio la comuna y el senado; por influencia de Arnaldo de Brescia, hasta 1155 de hecho no se reconoció la soberanía pontificia (f 1143 de la ficha, Treccani 1144).", "baeccd38"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1318-07-25:0":{"b": ["Jacopo I da Carrara es elegido protector y gobernador de Padua: la Comuna de Padua pasa a un solo señor", "b3fc0eae"], "d": ["La aristocracia de Padua eligió a Jacopo I da Carrara protector/gobernador vitalicio (poco después del 25 de julio de 1318); la comuna pasó a un solo señor. El día no es exacto; se tomó el primer día del intervalo.", "aa9a4a3f"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1351-05-01:0":{"b": ["Zúrich se une a la Confederación mediante alianza perpetua: quinto miembro junto a Lucerna, Uri, Schwyz y Unterwalden", "78e9419b"], "d": ["Zúrich se convirtió el 1 de mayo de 1351, mediante una alianza perpetua con Lucerna, Uri, Schwyz y Unterwalden, en miembro de la Antigua Confederación Suiza.", "4646e7ae"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1506-11-11:0":{"b": ["El papa Julio II entra en Bolonia: termina la señoría de los Bentivoglio, el Papado comienza el gobierno directo", "dc4823a7"], "d": ["El papa Julio II entró en Bolonia con su ejército y expulsó a Giovanni II Bentivoglio; la ciudad quedó unida al Estado Pontificio.", "9afc6459"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1532-01-01:0":{"b": ["Termina la libertad comunal de Ancona: pasa a la soberanía directa del Papado con Clemente VII", "d2fbbb8f"], "d": ["La libertad comunal de la República de Ancona terminó en 1532, en tiempos de Clemente VII, al pasar a la soberanía directa del Papado (precisión de año; no se leyó día ni mes).", "518c4913"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1536-05-21:0":{"b": ["Ginebra vota la Reforma: terminan el dominio del obispo y de Saboya, nace la República de Ginebra", "dcb02e44"], "d": ["Por votación de la asamblea general del 21 de mayo de 1536, Ginebra adoptó la Reforma; la ciudad permaneció como república independiente junto a Berna, pero no fue miembro de la Confederación.", "fd9e9db5"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1540-01-01:0":{"b": ["Termina la señoría de los Baglioni: Perugia pasa al gobierno pontificio directo de Pablo III", "3c57f2fe"], "d": ["Al final de la Guerra de la Sal terminó la señoría de los Baglioni, Pablo III inició la construcción de la Rocca Paolina; terminó la independencia de hecho de la Comuna de Perugia (precisión de año; no se leyó el día).", "0a01ed80"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1739-10-17:0":{"b": ["El cardenal Alberoni ocupa San Marino: se impone el gobierno pontificio", "4d3a4296"], "d": ["El cardenal Giulio Alberoni, legado de Rávena, ocupó San Marino por la fuerza militar e intentó anexarlo al Papado; la población resistió con desobediencia civil.", "79343d06"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1740-02-05:0":{"b": ["El papa Clemente XII reconoce los derechos de San Marino: regresa la independencia", "0783c00e"], "d": ["A raíz de peticiones secretas, el Papa reconoció los derechos de San Marino; terminó la ocupación de Alberoni.", "d3268069"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-05-15:0":{"b": ["Napoleón entra en Milán: termina el dominio austriaco", "adce9a6c"], "d": ["Bonaparte, tras las primeras victorias de la campaña de Italia, entró en Milán el 15 de mayo de 1796; Lombardía salió de manos de Austria.", "2a2ae65e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-06-23:0":{"b": ["Armisticio de Bolonia: Bolonia y Ferrara pasan a manos francesas", "5eed42c8"], "d": ["El papa Pío VI firmó un armisticio en Bolonia; las legaciones de Bolonia y Ferrara pasaron al control francés y se pagó una pesada indemnización.", "4447b7b3"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-12-27:0":{"b": ["Se proclama la República Cispadana (Módena, Reggio, Bolonia, Ferrara)", "f9ee3f5a"], "d": ["En el congreso de Reggio, Módena, Reggio, Bolonia y Ferrara se unieron y proclamaron la República Cispadana; el ducado de los Este terminó de hecho.", "0529810e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-02-02:0":{"b": ["Wurmser entrega Mantua", "476b954d"], "d": ["Al término de un asedio de meses, el comandante austriaco Wurmser entregó Mantua a los franceses el 2 de febrero de 1797.", "68c18933"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-02-19:0":{"b": ["Tratado de Tolentino: el Papa cede Bolonia, Ferrara y la Romaña a Francia", "9868973b"], "d": ["Pío VI hizo la paz con Francia en Tolentino; Bolonia, Ferrara y la Romaña (Rávena, Rímini) pasaron a la República Cispadana, bajo tutela francesa.", "2d453d48"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-05-12:0":{"b": ["Termina la República de Venecia: el Gran Consejo se disuelve", "a03a1a31"], "d": ["Por presión de Napoleón, el Gran Consejo se disolvió el 12 de mayo de 1797 y el dogo Manin dimitió; comenzó la ocupación francesa, y el destino posterior del Véneto se fijó en Campoformio.", "cd4ad1df"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-07-09:0":{"b": ["Se funda solemnemente en Milán la República Cisalpina: se unen Lombardía, Mantua, Bérgamo, Brescia y los territorios cispadanos", "b8338ba1"], "d": ["Lombardía, Mantua, Bérgamo, Brescia, la República Cispadana (Módena, Reggio, Bolonia, Ferrara) y la Romaña, conquistadas por Napoleón, se unieron en un solo Estado.", "ed1bf80a"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1798-02-15:0":{"b": ["Se proclama la República Romana: se interrumpe el gobierno pontificio", "30145500"], "d": ["Con Roma ocupada por Berthier, se proclamó la República Romana en el Capitolio; el papa Pío VI fue enviado al exilio.", "99f72dba"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1798-04-26:0":{"b": ["Ginebra es anexionada a Francia: termina la República de Ginebra, se crea el departamento del Léman", "cbee4241"], "d": ["Se firmó el tratado de anexión con Francia; Ginebra y sus alrededores se incorporaron a la República Francesa como departamento del Léman.", "3c1c8254"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1798-12-09:0":{"b": ["El Piamonte pasa a administración francesa; Carlos Manuel IV se retira a Cerdeña", "d4e022ae"], "d": ["La casa de Saboya abandonó en diciembre de 1798 el Piamonte continental y se retiró a la isla de Cerdeña; Turín quedó bajo control francés (anexión oficial el 11 de septiembre de 1802).", "dcb442ed"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-01-23:0":{"b": ["Se proclama la República Partenopea: el ejército francés entra en Nápoles, una república hermana sustituye al reino borbónico", "f657b307"], "d": ["El ejército de Championnet tomó Nápoles; el Borbón Fernando IV había huido a Palermo. El control efectivo de la república se limita en gran parte a la ciudad de Nápoles y su entorno (la provincia siguió siendo borbónica).", "9e17f40e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-04-27:0":{"b": ["Tras Cassano, el ejército austro-ruso derrumba la República Cisalpina", "5b6ad0d8"], "d": ["Tras la batalla de Cassano, las fuerzas austro-rusas entraron en Lombardía; la República Cisalpina se derrumbó.", "09c16276"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-06-13:0":{"b": ["El cardenal Ruffo reconquista Nápoles: termina la República Partenopea, regresa el gobierno borbónico", "04d437c6"], "d": ["El ejército sanfedista, al mando del cardenal Ruffo, entró en Nápoles; las fortalezas republicanas se rindieron poco después y el reino volvió al gobierno borbónico.", "775b1d4c"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-09-30:0":{"b": ["Las tropas napolitanas entran en Roma: termina la República Romana, regresa el gobierno pontificio", "a367ed6a"], "d": ["Las fuerzas napolitanas ocuparon Roma y terminó la República Romana; el regreso efectivo del gobierno pontificio se completó en julio de 1800 con la entrada de Pío VII.", "6ee7e336"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1800-06-04:0":{"b": ["Tras Marengo, Napoleón restablece la República Cisalpina", "c03710d1"], "d": ["Tras la victoria de Marengo, Napoleón regresó a Milán y restableció la República Cisalpina (el cuadro informativo dice 2 de junio).", "df5345f5"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1802-10-09:0":{"b": ["Muere el duque de Parma Fernando I: el ducado pasa a administración francesa", "0e6bc319"], "d": ["Fernando, que había cedido el ducado a Francia con el Tratado de Aranjuez (1801), murió el 9 de octubre de 1802; Parma y Piacenza pasaron a la administración francesa (anexión oficial en 1808).", "5d07614d"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1805-06-04:0":{"b": ["Napoleón acepta la anexión de Liguria: Génova se incorpora al Imperio francés", "ecc8047e"], "d": ["El Senado de Liguria aprobó la anexión el 25 de mayo de 1805; Napoleón la aceptó el 4 de junio de 1805 y terminó la República Ligur.", "054ecfb4"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1805-12-26:0":{"b": ["Tratado de Presburgo: el Véneto, Istria y Dalmacia pasan al Reino de Italia", "94ff5a04"], "d": ["Austria cedió los antiguos territorios venecianos (Véneto, Friuli, Istria, Dalmacia) al Reino de Italia de Napoleón.", "5e25f259"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1807-12-10:0":{"b": ["Termina el Reino de Etruria: la Toscana cae bajo ocupación francesa", "f4c9b9ef"], "d": ["Napoleón disolvió el Reino de Etruria; la reina regente abandonó Florencia y la Toscana se incorporó a Francia en 1808 como los departamentos del Arno, Ombrone y Méditerranée.", "d2e2917f"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1808-04-02:0":{"b": ["Napoleón anexiona las Marcas al Reino de Italia: Ancona, capital del departamento del Metauro", "2314868d"], "d": ["Con el decreto n.º 158 expedido desde Saint-Cloud, las Marcas pontificias fueron agregadas al Reino de Italia; el decreto del 20 de abril de 1808 creó los departamentos del Metauro (Ancona), Musone (Macerata) y Tronto (Fermo).", "10d2d834"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1809-05-17:0":{"b": ["Napoleón anexiona los territorios pontificios al Imperio francés", "f4ba4cb8"], "d": ["Roma y los territorios restantes del Estado Pontificio (incluida Umbría) fueron anexionados a Francia; Pío VII fue arrestado.", "b281eb72"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1810-02-28:0":{"b": ["Tratado de París: Baviera cede el Tirol del Sur (Trento) a Napoleón, la región se incorpora al Reino de Italia", "01762dda"], "d": ["El rey de Baviera cedió el Tirol del Sur a Napoleón; se creó el departamento del Alto Adigio con capital en Trento, vinculado al Reino de Italia (reparto del 9 de junio de 1810).", "1ceb45f7"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1813-10-15:0":{"b": ["Las tropas austriacas entran en Trento: se derrumba el departamento del Alto Adigio del Reino de Italia", "1870c11e"], "d": ["Las tropas austriacas al mando del general Fenner entraron en Bolzano el 11 y en Trento el 15 de octubre de 1813; el 10 de diciembre de 1813 se estableció una administración austriaca provisional.", "66916a3e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1813-12-31:0":{"b": ["La guarnición francesa se retira de Ginebra: se restablece la República de Ginebra", "b06ab617"], "d": ["Con la aproximación de las tropas austriacas la administración francesa se derrumbó; el 31 de diciembre de 1813 se restauró la República de Ginebra, que se unió a la Confederación en 1814-1815.", "0fe9a364"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-04-11:0":{"b": ["Fontainebleau: Parma y Piacenza se entregan a María Luisa", "909f6ba0"], "d": ["Con la abdicación de Napoleón, Parma, Piacenza y Guastalla fueron entregadas a su esposa María Luisa (paso a la administración efectiva en 1816).", "6d19058c"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-04-16:0":{"b": ["Eugenio firma el armisticio en Mantua: se derrumba el Reino de Italia, Austria toma Milán", "f658fa23"], "d": ["Con el armisticio de Schiarino-Rizzino terminó de hecho el Reino de Italia de Napoleón; Lombardía y el Véneto pasaron al control austriaco (cesión oficial: Acta Final de Viena, 9 de junio de 1815).", "a0989fbc"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-05-20:0":{"b": ["Víctor Manuel I regresa a Turín: se restaura la casa de Saboya", "32499bf1"], "d": ["Terminó la administración francesa del Piamonte; Víctor Manuel I regresó de Cerdeña a Turín y puso de nuevo en vigor la constitución de 1770.", "a2ce4d35"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-05-24:0":{"b": ["Pío VII regresa a Roma: se restablece el gobierno pontificio", "d0b4171c"], "d": ["Tras cinco años de cautiverio, el papa Pío VII entró triunfalmente en Roma el 24 de mayo de 1814; se restauró el Estado Pontificio (las Legaciones fueron devueltas en 1815).", "d93a4a6c"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-07-14:0":{"b": ["Francisco IV asume el gobierno como duque de Módena: se restaura el ducado Este-Habsburgo", "e06a5823"], "d": ["Al disolverse el Reino de Italia de Napoleón, el Ducado de Módena y Reggio fue devuelto a la dinastía Habsburgo-Este (Francisco IV).", "daa659f4"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-09-01:0":{"b": ["Se restaura el gran duque de Toscana Fernando III", "f6f21c83"], "d": ["Terminada la época napoleónica, Fernando III, de la casa de Habsburgo-Lorena, recuperó el gobierno de la Toscana (septiembre de 1814).", "a310e5c7"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1848-03-22:0":{"b": ["Manin toma el Arsenal de Venecia: se proclama la República de San Marcos", "154bae0a"], "d": ["Bajo la dirección de Daniele Manin, Venecia se sublevó contra el dominio austriaco y proclamó la República de San Marcos; las tropas austriacas se retiraron de la ciudad el 26 de marzo.", "476c31cc"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1849-02-09:0":{"b": ["Se proclama la República Romana: con el Papa huido a Gaeta, la Asamblea Constituyente funda la república", "282025d1"], "d": ["El triunvirato encabezado por Mazzini proclamó la república en Roma; se suspendió el gobierno pontificio.", "03575b62"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1849-07-03:0":{"b": ["El ejército francés entra en Roma: termina la República Romana, regresa el gobierno pontificio", "2e5ed341"], "d": ["El cuerpo expedicionario francés de Oudinot tomó Roma; Garibaldi se retiró y la república cayó (Wikipedia dice 2 de julio, la mayoría de las fuentes 3 de julio).", "bbaabf25"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1849-08-22:0":{"b": ["Venecia se rinde a Austria: termina la República de San Marcos", "f5e5de33"], "d": ["Tras el asedio, el cólera y el hambre, Manin entregó la ciudad; regresó la administración austriaca (el cuadro informativo dice 27 de agosto).", "70a16b74"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1943-09-23:0":{"b": ["Mussolini funda la República de Saló: el norte de Italia pasa a ser la República Social Italiana bajo protección alemana", "9248adee"], "d": ["Mussolini, rescatado por los alemanes, fundó bajo control militar alemán la República Social Italiana (Saló), que abarcaba el norte y el centro de Italia; el Reino y el gobierno de Badoglio permanecieron en el sur.", "cd238153"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:536-12-09:0":{"b": ["Belisario entra en Roma: Roma pasa del dominio ostrogodo a Bizancio", "f74ca8a4"], "d": ["En la Guerra Gótica, el ejército de Belisario entró en Roma el 9 de diciembre de 536; la ciudad fue tomada a los ostrogodos y vinculada a Bizancio (Totila la reconquistará en 546).", "75602e01"]},
"OLAYLAR_OK104:1284-01-01:0":{"b": ["Bizancio recupera de los Anjou Krujë (Akçahisar), Durrës y Vlorë", "4e1a9810"], "d": ["Durrës y Krujë, tomadas por Carlos de Anjou en 1271-1272, fueron reconquistadas tras la muerte de Carlos por el emperador bizantino Andrónico II (TDV Kruya: «recuperó Avlonya, Draç y Kruya»). Solo se conoce el año; el día no está confirmado.", "eef9a5c3"]},
"OLAYLAR_OK104:1304-01-01:0":{"b": ["Felipe de Tarento restablece el dominio angevino en Durrës", "be355b48"], "d": ["En Durrës, que había pasado a Bizancio en 1284, Felipe, príncipe de Tarento e hijo del rey de Nápoles Carlos II, restableció en 1304 el dominio angevino; se proclamó de nuevo el Reino de Albania (Regnum Albaniae), pero durante la vida de Felipe quedó limitado a esta ciudad (Europange: «The kingdom of Albania was re-established in 1304, when Philip of Taranto was able to restore the Angevin regime in Durazzo»). En 1332 su hijo Roberto entregó Durrës a Juan de Gravina a cambio del Principado de Acaya; el ducado de Durazzo permaneció en manos angevinas hasta que Carlos Thopia tomó la ciudad en 1368. Solo se conoce el año; el día no está confirmado.", "f918f799"]},
"OLAYLAR_OK104:1344-01-01:0":{"b": ["Los serbios se apoderan de Krujë (Akçahisar), Berat y Vlorë", "cef4ca73"], "d": ["TDV Kruya: «En 1344 los serbios se apoderaron de Kruya, Berat y Avlonya». TDV Arnavutluk dice que Dušan ocupó Albania entre 1343 y 1346 y que con el colapso de su imperio en 1355 se fortalecieron los señores locales. Solo se conoce el año; el día no está confirmado.", "0ab9765f"]},
"OLAYLAR_OK104:1392-01-01:0":{"b": ["Durrës pasa de los Thopia a Venecia", "da0afe63"], "d": ["Durrës, tomada en 1368 por Carlos Thopia, fue cedida a Venecia en 1392 por su hijo Jorge Thopia (TDV Draç: «cedida a Venecia por Jorge, hijo de Thopia», sin año); Venecia confirmó los estatutos de la ciudad en agosto de 1392. Venecia mantuvo Durrës hasta que los otomanos la tomaron en 1501. Solo se conoce el año; el día no está confirmado.", "072ad728"]},
"OLAYLAR_OK104:1393-05-01:0":{"b": ["Los Dukagjini ceden Lezhë (Alessio) a Venecia", "2cab90db"], "d": ["Paul y Lek Dukagjin, que desde 1387 tenían Lezhë (Alessio) como centro del Principado albanés de los Dukagjini, al ver que bajo la presión otomana no podrían defender este puerto en la desembocadura del Drin, entregaron la fortaleza a Venecia y se retiraron a la región montañosa al este de la ciudad. Desde entonces la ciudad permaneció en manos de Venecia hasta ser tomada en 1478, durante la campaña de Fâtih contra Shkodër, por Dâvud Paşa, beylerbeyi de Rumelia; tanto la reunión aquí de la alianza antiotomana de Skanderbeg (Lidhja e Lezhës) el 1 de marzo de 1444 como su muerte aquí el 17 de enero de 1468 tuvieron lugar en una fortaleza veneciana.", "a7df86bc"]},
"OLAYLAR_OK104:1443-01-01:0":{"b": ["Skanderbeg toma Krujë (Akçahisar): comienza la resistencia albanesa", "8f007d17"], "d": ["Tras la derrota de Niš (TDV Kruya: 847/1443), Skanderbeg ocupó Krujë. Tras la muerte de su padre Gjon Kastrioti en 1437, los otomanos habían entregado la ciudad no a él sino a Hasan Bey, designado por ellos. Solo se conoce el año; el día no está confirmado.", "d5be30c0"]},
"OLAYLAR_OK106:1571-01-01:0":{"b": ["Avance de Polonia hacia la línea del Dniéper — fundación de Kremenchuk", "1bc86966"], "d": ["Polonia-Lituania fundó una nueva población fronteriza en la encrucijada del Dniéper medio, paso de las incursiones de Crimea; veinticinco años después se le añadió también una fortaleza. Así, la línea de control de Polonia descendió hasta la orilla norte de la estepa de Zaporiyia, y por primera vez este paso del río quedó ligado a una guarnición permanente de un Estado. En el siglo siguiente, la población pasaría a ser centro de regimiento cosaco en el orden del Hetmanato.", "4d022f2b"]},
"OLAYLAR_OK106:1616-01-01:0":{"b": ["Aparición de Uman en la línea fronteriza polaca de Yedisan", "2e6551ab"], "d": ["Uman figuró por primera vez en los documentos como asentamiento en el extremo sudeste de la región de Bratslav, bajo administración polaca. El lugar estaba sobre las rutas de incursión que desde el Janato de Crimea se extendían hacia el norte; que se asentara aquí una población permanente indica que la franja de estepa vacía entre los dos Estados comenzaba a estrecharse desde el norte. Durante los dos siglos siguientes la ciudad seguiría siendo el mayor asentamiento polaco más meridional de esta línea.", "7a425b4c"]},
"OLAYLAR_OK106:1638-01-01:0":{"b": ["Avance de la línea defensiva de estepa de Moscú — Chuguiv", "c68d36d3"], "d": ["El líder cosaco Yakiv Ostrianyn y sus hombres, que tras la sublevación en Polonia se habían refugiado en Moscú, fundaron un asentamiento fronterizo a orillas del Donets. Fue uno de los primeros grandes saltos hacia la estepa de la línea defensiva que Moscú construía contra las incursiones de Crimea; en el medio siglo siguiente, en esa misma línea nacerían sucesivamente poblaciones como Sumy, Izium y Bajmut. El asentamiento perduró hasta 1765 como centro de compañía dependiente del regimiento de Járkov.", "3fdefaaa"]},
"OLAYLAR_OK106:1652-01-01:0":{"b": ["Fundación de la Ucrania de Sloboda — Sumy y el cinturón de asentamientos de la estepa", "ab7abf59"], "d": ["Campesinos y cosacos procedentes del regimiento de Bila Tserkva, en la Ucrania de la orilla derecha, fundaron una nueva población a orillas del Psel bajo la dirección del coronel Herasym Kondratiev; cuatro años después el voivoda de Moscú fortificó la fortaleza. Esta oleada migratoria es el comienzo del orden de la Ucrania de Sloboda, que abrió al asentamiento la estepa vacía de la frontera sur de Moscú: a los recién llegados se les concedió exención de impuestos y a cambio se esperaba de ellos la guardia fronteriza. Sumy fue, de 1658 a 1765, el centro del regimiento que llevaba su propio nombre.", "fc9a8983"]},
"OLAYLAR_OK106:1703-05-17:0":{"b": ["Construcción de Yeni Kale — el cierre del estrecho de Kerch", "d9067015"], "d": ["Tras la cesión de Azov a Rusia en 1700, la única puerta del mar Negro hacia el mar de Azov se convirtió en una línea fronteriza estratégica. El Estado otomano hizo construir una nueva fortificación en el paraje de Akıntı Burnu, diez kilómetros al nordeste de la ciudad de Kerch, y puso el paso del estrecho al alcance de los cañones; la fortaleza recibió el nombre de Yeni Kale (literalmente «Fortaleza Nueva»). Durante setenta años la fortaleza fue el cerrojo oriental de Crimea y, junto con Kerch, fue cedida a Rusia por el artículo diecinueve del Tratado de Küçük Kaynarca de 1774.", "8f8533a1"]},
"OLAYLAR_OK106:1754-01-01:0":{"b": ["Fortaleza de Santa Isabel — la frontera sur de Rusia llega hasta la línea de incursión otomano-tártara de Crimea", "b9097272"], "d": ["Rusia construyó una nueva fortaleza con el nombre de Santa Isabel en tierras de los cosacos de Zaporiyia. La justificación declarada de la fortaleza era proteger de las incursiones otomanas y de Crimea a los emigrantes balcánicos asentados en Nueva Serbia; es decir, la línea fronteriza rusa descendía por primera vez hasta el centro de la estepa, hasta las propias rutas de incursión. Este puesto avanzado fue, veinte años después, el punto de partida de la expansión hacia el norte del mar Negro que comenzaría con Küçük Kaynarca.", "8ac6527e"]},
"OLAYLAR_OK106:1847-05-31:0":{"b": ["Segundo Tratado de Erzurum — frontera del Shatt al-Arab y cesión de la costa de Juzestán", "5d1f9103"], "d": ["La disputa fronteriza otomano-iraní, sin resolver durante más de un siglo, fue regulada por un segundo tratado firmado en Erzurum tras largas negociaciones conducidas con mediación británica y rusa. La totalidad de la vía fluvial del Shatt al-Arab quedó en manos otomanas; en cambio, los asentamientos de la orilla oriental del río —incluidos el puerto de Muhammara y la isla de Abadán frente a él— fueron cedidos a los qayares. Así, la franja costera de Juzestán, considerada bajo administración otomana desde la anexión de Basora en 1546, se perdió tres siglos después. Mehmed Hurşid Paşa, miembro de la comisión de fronteras creada para fijar sobre el terreno la línea trazada por el tratado, recorrió la región entre 1848 y 1852 y escribió el Seyâhatnâme-i Hudûd.", "8fe2f887"]},
"OLAYLAR_OK107:1514-09-15:0":{"b": ["Retirada de Tabriz — fin de una ocupación de una semana y regreso por Kars y Bayburt", "fd1542e3"], "d": ["Tras la victoria de Chaldiran, Yavuz Sultán Selim, que había entrado en Tabriz el 6 de septiembre, permaneció una semana en la ciudad; hizo trasladar a Estambul, con sus familias, el tesoro del sah Ismail y a una parte de los artesanos y los sabios de la ciudad. Aunque quiso pasar el invierno en Karabaj y continuar la campaña al año siguiente, renunció a ese plan por la oposición de los jenízaros, y el ejército regresó por Kars y Bayburt. Así, Tabriz no quedó en manos otomanas: Chaldiran fue una victoria en el campo de batalla, mientras que la ganancia territorial duradera llegó al año siguiente con la campaña de Kemah, Diyarbekir y Anatolia Oriental.", "9cc5fc19"]},
"OLAYLAR_OK107:1515-09-19:0":{"b": ["Nusaybin, Derik y Silopi se incorporan al Imperio otomano — el brazo meridional de Diyarbekir", "c3621d22"], "d": ["Tras la entrega de Âmid y la creación del beylerbeylik de Diyarbekir, y con la atracción de los beyes kurdos de la región por İdrîs-i Bitlisî, Nusaybin, Derik y Silopi, al sur de la llanura de Mardin, también pasaron a la administración otomana. Estos lugares fueron organizados como centros de nahiye y kaza del nuevo beylerbeylik; algunos, como Cizre, fueron dejados a sus beyes locales con estatuto de yurtluk-ocaklık. Así, la campaña de Anatolia Oriental iniciada tras Chaldiran llegó a la Alta Yazira.", "f975424e"]},
"OLAYLAR_OK109:1918-10-28:0":{"b": ["Declaración de independencia de Checoslovaquia — el primer Estado sucesor de la herencia de los Habsburgo", "8f40155f"], "d": ["Ante la pérdida de fuerzas de Austria-Hungría en la guerra y las huelgas, manifestaciones y sublevaciones en el interior del país, el Consejo Nacional proclamó la independencia de Checoslovaquia el 28 de octubre de 1918. Se constituyó una asamblea nacional provisional tomando como base la situación electoral de 1911, y el 14 de noviembre de 1918 el gobierno presidido por Masaryk entró en funciones. El nuevo Estado obtuvo su lugar en el derecho internacional con el Tratado de Saint-Germain-en-Laye (10 de septiembre de 1919). En el mapa, Checoslovaquia aparece el 11 de noviembre de 1918; la declaración de independencia es dos semanas anterior.", "80a8405f"]},
"OLAYLAR_OK109:1918-10-29:0":{"b": ["Proclamación del Estado de los Eslovenos, Croatas y Serbios — el Sabor croata rompió los lazos con los Habsburgo", "2e5ae559"], "d": ["El 29 de octubre de 1918 el Sabor croata declaró rotos todos los lazos de derecho público de Croacia, Eslavonia y Dalmacia con Austria-Hungría; el mismo día se celebró en Liubliana la fundación del Estado de los Eslovenos, Croatas y Serbios. En Bosnia-Herzegovina, la administración austrohúngara transfirió el poder al gobierno del Consejo Nacional el 1 de noviembre de 1918. Este Estado duró hasta que el 1 de diciembre de 1918 se proclamó en Belgrado el Reino de los Serbios, Croatas y Eslovenos.", "9e0cf3b3"]},
"OLAYLAR_OK109:1918-10-30:0":{"b": ["Fundación de la República de Austria — el núcleo alemán de la herencia de los Habsburgo", "1ec8b06f"], "d": ["Tras la proclamación el 29 de octubre de la fundación de Checoslovaquia en Praga y del Estado de los Serbios, Croatas y Eslovenos en Zagreb, los austríacos de lengua alemana fundaron también la República de Austria el 30 de octubre. Ese mismo día el Estado otomano firmaba el Armisticio de Mudros; el fin de los dos imperios coincidió en el calendario.", "3772c9f7"]},
"OLAYLAR_OK109:1918-10-31:0":{"b": ["Revolución de los Áster — Károlyi se convirtió en primer ministro y la monarquía comenzó a disolverse en Hungría (la república popular se proclamó el 16 de noviembre)", "d7780d2e"], "d": ["Al comprenderse la derrota de las Potencias Centrales, se fortalecieron en Hungría los sentimientos antimonárquicos y se produjo un giro hacia la izquierda. El 31 de octubre de 1918, al término de la «revolución de los áster», el conde Mihály Károlyi, de ideas radicales, se convirtió en primer ministro y a continuación se proclamó la república popular; Károlyi fue elegido presidente titular el 11 de enero de 1919.", "0a48f4b7"]},
"OLAYLAR_OK109:1918-11-03:0":{"b": ["Armisticio de Villa Giusti — Austria-Hungría depuso las armas, Trento y Trieste pasaron a Italia", "75da65fb"], "d": ["La firma por el emperador Carlos, el 3 de noviembre de 1918, del armisticio con los italianos en Villa Giusti aceleró la desintegración del imperio. TDV registra expresamente este día como el de la deposición de las armas de Austria: «Austria, que aceptó la derrota, el 3 de noviembre, y Alemania, el 11 de noviembre, depusieron las armas». En el mapa, Trento y Trieste pasan este día de Austria a Italia: es la primera cesión territorial de la disolución visible en el mapa.", "a86d1725"]},
"OLAYLAR_OK109:1918-11-11:0":{"b": ["Independencia de Polonia — el Consejo de Regencia entregó el mando del ejército a Piłsudski", "e8b546cf"], "d": ["Józef Piłsudski regresó a Varsovia el 10 de noviembre de 1918. El 11 de noviembre el Consejo de Regencia le entregó el mando del ejército; unos días después le dejó también el encargo de formar el gobierno nacional.", "578314ea"]},
"OLAYLAR_OK109:1918-11-14:0":{"b": ["El ejército serbio ocupó Pécs (Peçuy) — comenzó la ocupación serbia de Baranya", "68f0695f"], "d": ["Pécs, de importancia estratégica por sus minas de carbón, pasó a ocupación serbia el 14 de noviembre de 1918. La ocupación serbia de Pécs y de la provincia de Baranya duró hasta agosto de 1921.", "7222b6bd"]},
"OLAYLAR_OK109:1918-11-14:1":{"b": ["El ejército serbio ocupó Timișoara (Temeşvar) — comenzó la administración militar serbia del Banato", "3cc85350"], "d": ["Las tropas serbias ocuparon Timișoara el 14 de noviembre de 1918, disolvieron las guardias nacionales y asumieron la administración militar y, poco después, también la civil del Banato. A comienzos de diciembre entraron también en la ciudad tropas francesas; la administración rumana solo se estableció en julio-agosto de 1919.", "78697a6b"]},
"OLAYLAR_OK109:1918-11-19:0":{"b": ["Las tropas serbias entraron en Szigetvár — ocupación del sur de Somogy", "a06b1907"], "d": ["Avanzando al norte de la línea trazada por el acuerdo militar de Belgrado, 220 soldados del ejército serbio al mando de Obren Petrović entraron en la noche del 18 al 19 en Szigetvár, centro del distrito de Somogy; las aldeas del distrito también fueron ocupadas por esta fuerza. La ocupación duró hasta agosto de 1921; Trianón dejó Szigetvár en Hungría.", "9485d5ab"]},
"OLAYLAR_OK109:1918-12-01:0":{"b": ["Fundación del Reino de los Serbios, Croatas y Eslovenos y de la Gran Rumanía — el mismo día, dos Estados", "6fd85345"], "d": ["Con la unión a Serbia de los eslavos separados del imperio tras la disolución de Austria-Hungría, el 1 de diciembre de 1918 se fundó el Reino de los Serbios, Croatas y Eslovenos; unos 250.000 km² de territorio y 12.000.000 de habitantes. Su base se había sentado en la Declaración de Corfú del 20 de julio de 1917, y las asambleas de Podgorica el 26 de octubre, de Bosnia-Herzegovina el 28 de octubre y de Novi Sad el 25 de noviembre habían decidido la adhesión. El mismo día, con la adhesión por decisión de sus propios pueblos de Transilvania, Bucovina y Besarabia, se formó la Gran Rumanía. En el mapa, los territorios del Reino de Serbia pasan a Yugoslavia.", "4565e7a6"]},
"OLAYLAR_OK109:1918-12-01:1":{"b": ["El ejército rumano entró en Brașov (Brassó) y fue recibido con una ceremonia", "4a917d27"], "d": ["El ejército rumano entró en Brașov en diciembre de 1918; los notables rumanos de la ciudad recibieron con una ceremonia al ejército y al general Berthelot.", "96d03f2f"]},
"OLAYLAR_OK109:1918-12-19:0":{"b": ["El ejército italiano ocupó Knin", "7949dd0f"], "d": ["El ejército italiano ocupó Knin el 19 de diciembre de 1918. La ocupación duró hasta el 4 de abril de 1921, cuando el ejército italiano se retiró de la ciudad tras el Tratado de Rapallo.", "f4363313"]},
"OLAYLAR_OK109:1918-12-29:0":{"b": ["Las tropas checoslovacas tomaron Košice (Kassa)", "0989490f"], "d": ["Cuando el 29 de diciembre de 1918 el 30.º Regimiento de Infantería, que llevaba el nombre de Alois Jirásek, ocupó la ciudad, Košice se incorporó de hecho a la República Checoslovaca.", "2453b355"]},
"OLAYLAR_OK109:1919-04-20:0":{"b": ["El ejército rumano entró en Szatmár (19 de abril) y en Oradea (Varad, 20 de abril)", "3ee2bd72"], "d": ["El sábado de Pascua, 19 de abril de 1919, en Satu Mare una delegación local encabezada por el Dr. Ilie Carol Barbul recibió en el puente sobre el Someș la primera patrulla de la 2.ª División de Caballería al mando del coronel Ressel. Al día siguiente, 20 de abril de 1919, las tropas rumanas al mando del general Traian Moșoiu entraron en Oradea.", "9249e364"]},
"OLAYLAR_OK109:1919-06-28:0":{"b": ["Tratado de Versalles — la restitución de Alsacia-Lorena a Francia pasó al derecho", "3babdfcb"], "d": ["La Conferencia de Paz de París se reunió el 18 de enero de 1919 y el 28 de junio se firmó con Alemania el Tratado de Versalles. El artículo 51 del tratado restituyó a la soberanía francesa Alsacia-Lorena (Estrasburgo, Metz, Colmar, Mulhouse), alemana desde 1871, pero ligó la cesión no al día de la firma, sino retroactivamente al armisticio del 11 de noviembre de 1918. La misma serie de conferencias produjo con Austria Saint-Germain (10 de septiembre de 1919), con Bulgaria Neuilly (27 de noviembre de 1919), con Hungría Trianón (4 de junio de 1920) y con el Estado otomano Sèvres (10 de agosto de 1920).", "4ab970de"]},
"OLAYLAR_OK109:1919-07-22:0":{"b": ["Las tropas rumanas llegaron a Lugoj (Lugos) — administración rumana en el este del Banato", "f65fc73c"], "d": ["El tren que transportaba a las tropas rumanas llegó a Lugoj el 22 de julio de 1919 a las 14 horas; la población de la ciudad recibió al ejército en la estación, el prefecto de Caraş-Severin, George Dobrin, pronunció el discurso de bienvenida y el general Jitianu respondió. La administración rumana se estableció en julio de 1919 en la parte del Banato que correspondió a Rumanía; la cesión jurídica se produjo con el Tratado de Trianón de 1920.", "b228ed28"]},
"OLAYLAR_OK109:1919-08-03:0":{"b": ["El ejército rumano entró en Timișoara (Temeşvar) — se estableció la administración rumana en la ciudad", "8728e1d1"], "d": ["En Timișoara, a la que habían entrado tropas serbias el 14 de noviembre de 1918 y francesas a comienzos de diciembre, entraron en la mañana del 3 de agosto de 1919 las primeras unidades del ejército rumano al mando del coronel Virgil Economu, y se estableció en la ciudad la administración rumana.", "0b1627d3"]},
"OLAYLAR_OK109:1919-08-12:0":{"b": ["El ejército del Reino SHS entró en Prekmurje — Murska Sobota y Lendava salieron de la administración húngara", "21b2ba08"], "d": ["Las tropas del Reino de los Serbios, Croatas y Eslovenos entraron el 12 de agosto de 1919 en Prekmurje, al otro lado del río Mura; ese día terminó la administración húngara en la región. La cesión jurídica se produjo con el Tratado de Trianón de 1920.", "3ce8a913"]},
"OLAYLAR_OK109:1919-09-10:0":{"b": ["Tratado de Saint-Germain — la reducción de Austria pasó al derecho", "e7b722d5"], "d": ["Tras la guerra, Austria firmó con los aliados el Tratado de Paz de Saint-Germain. Según el tratado, Austria reconocía la independencia de Hungría, Checoslovaquia y Yugoslavia, y aceptaba no unirse a Alemania sin el consentimiento de la Sociedad de Naciones, abolir el servicio militar obligatorio y limitar el ejército a 30.000 hombres. Este es también el documento por el que Checoslovaquia obtuvo su lugar en el derecho internacional. La cesión en el mapa había ocurrido un año antes; este tratado la registró.", "482c2ef4"]},
"OLAYLAR_OK109:1919-11-27:0":{"b": ["Tratado de Neuilly — Bulgaria perdió Tracia Occidental y la costa del Egeo", "01f2b8c8"], "d": ["Con la derrota en la guerra, el zar Fernando se había visto obligado a pedir el armisticio y a abdicar en favor de su hijo Boris (29 de septiembre de 1918). Con el Tratado de Neuilly, que puso fin a la guerra, Bulgaria sufrió pérdidas estratégicas de territorio en favor de los serbios, perdió toda la Tracia Occidental, tuvo que ceder a Grecia la costa del mar Egeo y confirmó las disposiciones del Tratado de Bucarest, que daba la Dobruja Meridional a Rumanía. En el mapa, la correspondencia de esta cesión no está en el día del tratado, sino en mayo de 1920, cuando la administración cambió de manos de hecho: Dedeağaç, Sofulu, Orestiada y Çirmen pasan a Grecia el 14 de mayo; Gümülcine, İskeçe, Dimetoka y Ferecik, el 27 de mayo.", "d61eb549"]},
"OLAYLAR_OK109:1920-06-04:0":{"b": ["Tratado de Trianón — Hungría perdió dos tercios de su territorio", "84aff507"], "d": ["Según el Tratado de Trianón, firmado tres meses después de que Horthy fuera nombrado regente del reino el 1 de marzo de 1920, Hungría sufrió graves pérdidas de territorio y de población: dos tercios de su territorio de 283.000 km², sin contar Croacia, y el sesenta por ciento de su población, incluidos más de tres millones de húngaros, quedaron fuera de las fronteras, y su ejército se redujo a 35.000 hombres. En el mapa, la Regencia de Hungría aparece con estas fronteras reducidas; Transilvania y el Alto Hungría pasan también exactamente este día al color de Rumanía y de Checoslovaquia.", "6073745e"]},
"OLAYLAR_OK109:1920-06-04:1":{"b": ["Reparto del Banato, Timișoara cedida a Rumanía (Trianón, arts. 27/3 y 45)", "256b4aca"], "d": ["El Tratado de Trianón trazó la frontera húngaro-rumana con el art. 27/3 y, con el art. 45, Hungría renunció en favor de Rumanía a todos sus derechos y títulos sobre los antiguos territorios de la monarquía situados más allá de esta frontera; así, la unión de Transilvania, el Banato, Crișana y Maramureș con Rumanía fue reconocida en el derecho internacional. La región del Banato se repartió entre Rumanía y Serbia; la ciudad de Timișoara (Temeşvar) se incorporó al Reino de Rumanía. La administración rumana funcionaba de hecho en Timișoara desde el 3 de agosto de 1919; el tratado llevó esta situación al derecho.", "5ec9c446"]},
"OLAYLAR_OK109:1921-04-04:0":{"b": ["El ejército italiano se retiró de Knin", "a1d2e846"], "d": ["Tras el Tratado de Rapallo, el ejército italiano se retiró de Knin el 4 de abril de 1921; terminó la ocupación iniciada el 19 de diciembre de 1918.", "0af4a592"]},
"OLAYLAR_OK109:1921-06-12:0":{"b": ["Italia entregó Šibenik al Reino SHS", "9d07b12a"], "d": ["La ocupación italiana, iniciada el 6 de noviembre de 1918, terminó el 12 de junio de 1921 con una ceremonia en la que participaron representantes militares de Italia y del Reino SHS.", "3d4d272c"]},
"OLAYLAR_OK109:1921-08-20:0":{"b": ["Las tropas serbias se retiraron de Szigetvár — la gendarmería húngara recibió la ciudad", "97781b77"], "d": ["Tras la entrada en vigor de Trianón, las fuerzas serbias comenzaron el 17 de agosto a retirarse de Barcs y Szigetvár, llevándose todo lo transportable. El 20 de agosto, hacia el mediodía, entraron las unidades de gendarmería húngara; por la tarde juraron el consejo municipal y los funcionarios, y a las cinco se hizo la entrega militar en el ayuntamiento.", "1db599da"]},
"OLAYLAR_OK109:1921-08-22:0":{"b": ["Terminó la ocupación serbia de Pécs (Peçuy) — el Ejército Nacional húngaro entró en la ciudad", "f437115a"], "d": ["Las tropas serbias comenzaron a evacuar la región el 18 de agosto de 1921; el 20-21 de agosto la administración de la ciudad y de la provincia fue transferida a los representantes del gobierno húngaro, y el 22 de agosto las unidades del Ejército Nacional húngaro entraron en la ciudad.", "0210d518"]},
"OLAYLAR_OK109:1921-11-13:0":{"b": ["El Bundesheer austríaco entró en Burgenland — el territorio que Trianón dejó a Austria fue recibido de hecho", "7bfd6915"], "d": ["Trianón (1920) y Saint-Germain (1919) habían dejado a Austria la franja germanohablante de Hungría occidental; el primer intento de toma de posesión, el 28 de agosto de 1921, fracasó por la resistencia de las unidades irregulares húngaras. Tras el Protocolo de Venecia (13 de octubre de 1921), la Comisión General Aliada aprobó el 11 de noviembre la entrada del Bundesheer, y dos días después comenzó la recepción del norte de Burgenland; el sur fue recibido el 6 de diciembre de 1921, y la región de Sopron quedó en Hungría por plebiscito.", "c78d0f81"]},
"OLAYLAR_ONCE1000_1019:0330-05-11:0":{"b": ["Se inauguró solemnemente Constantinopla; el centro del imperio se desplazó de hecho hacia el este", "e4d78842"], "d": ["La nueva capital fundada por Constantino I fue inaugurada solemnemente el 11 de mayo de 330; Constantinopla se convirtió en la capital del Imperio bizantino (romano de Oriente).", "482503e4"]},
"OLAYLAR_ONCE1000_1019:0969-07-06:0":{"b": ["El comandante Jawhar al-Siqilli entró en Fustat y conquistó Egipto; fin de los ijshídidas", "fd0410b1"], "d": ["En nombre del califa fatimí Mu'izz li-Din Allah, Jawhar al-Siqilli entró en Fustat (17 Shaban 358 / 6 de julio de 969); Egipto pasó de los ijshídidas a los fatimíes y la región donde se fundaría El Cairo entró bajo dominio fatimí.", "4aee6045"]},
"OLAYLAR_ONCE1000_1019:0990-03-31:0":{"b": ["Abu l-Zawwad tomó Mosul; se fundó la dinastía uqailí", "c3032f55"], "d": ["El uqailí Abu l-Zawwad Muhammad b. Musayyab se apoderó de Mosul (380 / 990); se eligió el primer día de la intersección de 380 H ∩ 990, el 31 de marzo de 990 (tabla hégira-calendario cristiano, ±1-2 días); el día no figura en la fuente.", "ecd80cfe"]},
"OLAYLAR_ONCE1281_GERIYE:1147-10-24:0":{"b": ["Afonso Henriques tomó Lisboa (Ushbuna); la ciudad se convirtió en el centro del nuevo Reino de Portugal", "24fddde8"], "d": ["Ushbuna fue tomada a los almorávides y pasó a manos de Portugal (27 Yumada al-ula 542 / 24 de octubre de 1147).", "bd3b3add"]},
"OLAYLAR_ONCE1281_GERIYE:1229-12-31:0":{"b": ["Jaime I tomó la ciudad de Mallorca (Medina Mayurqa)", "47fd675c"], "d": ["El rey de Aragón Jaime I tomó la ciudad de Mallorca a los musulmanes; Palma pasó a la Corona de Aragón.", "462f0592"]},
"OLAYLAR_ONCE1281_GERIYE:1238-05-12:0":{"b": ["Muhammad b. Yusuf Ibn al-Ahmar fundó el Estado nazarí en Granada", "23f66f33"], "d": ["El Estado nazarí se fundó con centro en Granada (26 Ramadán 635 / 12 de mayo de 1238).", "04a01554"]},
"OLAYLAR_ONCE1281_GERIYE:1238-06-01:0":{"b": ["Acuerdo de Stensby: la Orden Teutónica devolvió el norte de Estonia (Reval) al rey Valdemar II de Dinamarca", "b64c584d"], "d": ["Con el acuerdo alcanzado en Stensby, en Selandia, en junio de 1238, Reval y el norte de Estonia volvieron al dominio danés (el día no figura en la fuente).", "e8ad663d"]},
"OLAYLAR_ONCE1281_GERIYE:1238-09-28:0":{"b": ["Capitulación de Valencia: Jaime I tomó la ciudad", "977120b3"], "d": ["Balansiya (Valencia) pasó al rey de Aragón Jaime I el 28 de septiembre de 1238 mediante un pacto de capitulación (entrada solemne el 9 de octubre).", "c3465b4f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1054-11-05:0":{"b": ["El uqaylí Quraysh hizo recitar la jutba en nombre de Tuğrul Bey", "9fb65fc0"], "d": ["Cuando Tuğrul Bey llegó a la región con motivo de la campaña de Bagdad, el emir uqaylí Quraysh hizo recitar la jutba en su nombre en Shaban de 446 / noviembre de 1054; tras el asesinato del marwaní Süleyman, en 447/1055 fue gravemente herido.", "43df7313"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1064-01-01:0":{"b": ["El sultán Alparslan conquistó Ani y entregó el gobierno de la ciudad al shaddadí Ebû Şücâ‘ Menûçihr", "f2c51a49"], "d": ["Alparslan, que conquistó Ani en 456/1064, entregó el gobierno de la ciudad a Ebû Şücâ‘ Menûçihr, hijo del shaddadí Ebü'l-Esvâr Şâvur. Menûçihr anexó también Kars, y temiendo al ejército bizantino que se acercaba hizo reparar las murallas dañadas durante la conquista; gobernó Ani como vasallo selyúcida durante cincuenta y cuatro años.", "6ddc5837"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1068-01-01:0":{"b": ["Alparslan se apoderó de Ahıska", "31b9964f"], "d": ["Ahıska, tomada por Alparslan en tiempos de los selyúcidas (1068), pasó en 1267-1268 al dominio mongol.", "f2d87d84"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1068-01-01:1":{"b": ["Alparslan y sus aliados arrasaron Tiflis y Kartli", "ff50ab5d"], "d": ["El rey Bagrat había recuperado la mayor parte de sus fortalezas; pero en 1068 Alparslan y sus aliados arrasaron Tiflis y Kartli.", "753e1b62"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1073-01-01:0":{"b": ["Philaretos reunió en la ciudad de Hunu (región de Elbistan) a los sacerdotes armenios, hizo elegir un católicos y convirtió la ciudad en sede del catolicosado", "66005693"], "d": ["Aprovechando la captura de Romano Diógenes en la batalla de Malazgirt de 1071, Philaretos reunió a los sacerdotes armenios en la ciudad de Hunu y les hizo elegir un católicos. Así quedó establecido el centro religioso de una administración armenia desligada de Bizancio en la región de Maraş-Elbistan-Malatya.", "146d6889"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1076-01-01:0":{"b": ["El sultán Melikşah llegó hasta Kartli en su campaña de Georgia; confió la responsabilidad de la región a Serheng Savtegin", "830b979a"], "d": ["Melikşah organizó una campaña contra Georgia con Yuane, hijo de Liparit, el comandante georgiano que le seguía siendo leal; llegó hasta Kartli, regresó con muchos prisioneros y botín y confió la responsabilidad de la región a Serheng Savtegin (1076). El rey Jorge II ganó las guerras que libró con Savtegin y recuperó algunos lugares.", "8a5912c3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1078-07-14:0":{"b": ["Melikşah entró en Georgia por el Araks, saqueó la región de Somkheth y capturó a Yuane", "e62fd603"], "d": ["Cuando el rey Jorge II derrotó a Savtegin y recuperó algunos lugares, el sultán Melikşah salió de nuevo en campaña y entró en Georgia por el Araks (471/1078-79); saqueó la región de Somkheth y capturó a Yuane, y regresó dejando allí a Savtegin con tropas de refuerzo. El emir Ahmed infligió al rey una grave derrota en Kouel y recuperó Kars.", "57f4ff76"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1083-01-01:0":{"b": ["Süleyman Şah I hizo una campaña a Cilicia (Çukurova) y conquistó Tarso, Adana, Ayn Zarba y Mopsuestia", "c443ee8b"], "d": ["Süleyman Şah, que tomó el título de sultán en 1082, hizo ese mismo año una campaña a Cilicia (Çukurova) y conquistó las ciudades y fortalezas de Tarso, Adana, Ayn Zarba y Mopsuestia (1082-1083); a continuación, por invitación de la población de Antioquía, marchó sobre Antioquía con sus hijos Kılıcarslan y Dâvud.", "e617bea2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-01-01:0":{"b": ["Çubuk Bey conquistó Harput y fundó el beylicato de los Çubukoğulları, que abarcaba los alrededores de Palu y Çemişkezek", "1f333d7d"], "d": ["Durante las incursiones turcas hacia Anatolia después de 1071, Çubuk Bey conquistó Harput y fundó el beylicato que abarcaba las regiones de Palu y Çemişkezek. La vida del beylicato fue corta; en la década de 1110 el artuqí Belek tomó la ciudad.", "5c951bf7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-04-29:0":{"b": ["El sultán Melikşah concedió Bitlis y su región como iqta a Dilmaçoğlu Mehmed Bey; comenzó el beylicato de los Dilmaçoğulları", "7cdcb46f"], "d": ["Después de que Fahrüddevle İbn Cehîr, comandante en jefe del ejército selyúcida, tomara Bitlis y su región, el sultán Melikşah la concedió como iqta a Dilmaçoğlu Mehmed Bey, que había participado en Malazgirt (478/1085). El beylicato gobernó en Bitlis y Erzen entre 1085 y 1394.", "da296fec"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-06-20:0":{"b": ["Muslim b. Quraysh fue derrotado y muerto en Kurzahil por Süleyman Şah", "fc482adb"], "d": ["El uqaylí Muslim b. Quraysh, que quería fundar un Estado árabe unido e independiente del sultán de los Grandes Selyúcidas, combatió contra Süleyman Şah cuando hizo saquear la región de Antioquía; derrotado en el lugar de Kurzahil, murió (24 de Safar de 478 / 20 de junio de 1085) y fue enterrado en la puerta de Alepo.", "9f4da840"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1086-01-01:0":{"b": ["El sultán Melikşah llegó al Cáucaso con un gran ejército y sometió por completo la región", "79dd07e4"], "d": ["Después de que el rey Jorge II fuera a Isfahán y aceptara la soberanía de Melikşah, este llegó por última vez al Cáucaso en 1086 con un gran ejército y sometió por completo la región; se había dado a Georgia oriental el nombre de «Didi Turkoba» (la Gran Turquía).", "a15ba581"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1095-01-01:0":{"b": ["Çaka Bey fue asesinado durante un banquete por su yerno Kılıcarslan I", "20cdcec9"], "d": ["Ana Comneno, que registra que Çaka Bey fue asesinado durante un banquete por su yerno Kılıcarslan, da como fecha de la muerte 1097, pero esto es erróneo si se tienen en cuenta el asedio de Malatya en 1096 y la caída de Nicea en 1097; la fecha de la muerte debe de ser 1095 (m. 488/1095 [?]).", "9a287bc8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1097-01-01:0":{"b": ["Kılıcarslan I asedió Malatya, que también deseaban los danişmendíes; levantó el asedio cuando los cruzados se dirigieron a Nicea", "4f036db3"], "d": ["En el invierno de 490/1097 Kılıcarslan marchó sobre Malatya, que también codiciaban los danişmendíes, y asedió la ciudad durante un tiempo; al saber que los ejércitos cruzados se habían puesto en marcha, se dirigió a Nicea, y Nicea se perdió (junio de 1097).", "4282aef8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1100-07-01:0":{"b": ["Gümüştegin Gazi tendió una emboscada a Bohemundo, príncipe de Antioquía, lo capturó y lo encarceló en Niksar", "c43f8a71"], "d": ["El danişmendí Gümüştegin, que asediaba Malatya, tendió una emboscada y derrotó a las fuerzas de Bohemundo, príncipe de Antioquía, que acudió en ayuda; Bohemundo fue llevado primero a Sivas y luego a Niksar, donde fue encarcelado. El asedio se levantó al acercarse Balduino, conde de Edesa.", "543833c3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1101-06-23:0":{"b": ["Ankara fue entregada a Bizancio conforme al acuerdo entre los cruzados y el emperador Alejo Comneno", "d64f8668"], "d": ["Durante la Primera Cruzada, Raimundo de Tolosa había ocupado Ankara sin encontrar una resistencia seria y los turcos de la fortaleza habían sido pasados a cuchillo; conforme al acuerdo entre los cruzados y Alejo Comneno, la ciudad fue entregada al Imperio bizantino el 23 de junio de 1101. La administración bizantina duró unos veinte años.", "f8a37732"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1101-08-01:0":{"b": ["Gümüştegin, Kılıcarslan I y Ridwan derrotaron al ejército cruzado lombardo cerca de Merzifon", "f2703ea8"], "d": ["Los cruzados lombardos, que tomaron Ankara para liberar a Bohemundo de su cautiverio y avanzaron hacia Çankırı, fueron derrotados en agosto de 1101 cerca de Merzifon frente al ejército turco conjunto de 20.000 hombres de Gümüştegin, Kılıcarslan I, Ridwan, rey de Alepo, y Karaca, emir de Harran.", "ddaa77e1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1102-01-01:0":{"b": ["Sökmen recibió la entrega de Hasankeyf; se fundó la rama de los artuqíes de Hısnıkeyfâ", "07e6f974"], "d": ["A la muerte del emir de Mosul Kürboğa, Sökmen, que apoyaba a Mûsâ en Mosul, ayudó a derrotar a Çökürmüş a cambio de la promesa de Mûsâ; al ser asesinado Mûsâ, fue a Hasankeyf y recibió la entrega de la ciudad. Así quedó fundada la rama de Hısnıkeyfâ de los artuqíes (1102-1232).", "fccc615e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1103-01-01:0":{"b": ["Sökmen se apoderó de Mardin tras la muerte de su sobrino Yâkūtî", "a5099d54"], "d": ["Mardin estaba bajo el dominio de Yâkūtî, sobrino de Sökmen; aprovechando la disputa surgida tras su muerte, Sökmen tomó la ciudad en 1103 y sometió a su autoridad la mayor parte de la región de Diyarbekir.", "43484644"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1103-08-01:0":{"b": ["Kılıcarslan I derrotó a Gümüştegin Gazi cerca de Maraş", "15ec5217"], "d": ["La liberación de Bohemundo por Gümüştegin a cambio de un rescate y el descontento de Kılıcarslan, que reclamaba una parte del rescate, enfrentaron a los dos aliados; Kılıcarslan derrotó a Gümüştegin cerca de Maraş.", "64f2df55"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-01-01:0":{"b": ["Gümüştegin Gazi murió en Sivas; su hijo Emîr Gazi asumió la jefatura de la dinastía danişmendí", "75915f65"], "d": ["Con la muerte de Gümüştegin los danişmendíes sufrieron una gran sacudida; Malatya fue entregada a los selyúcidas y surgieron luchas por el trono entre los miembros de la dinastía. Su hijo mayor, Emîr Gazi, se hizo cargo del gobierno.", "f184fc73"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-05-07:0":{"b": ["Sökmen el-Kutbî y Çökürmüş derrotaron y capturaron cerca de Harrán (Balikh) a Balduino de Le Bourg, conde de Edesa, y a Josselin", "5240d89c"], "d": ["Balduino de Le Bourg, conde cruzado de Edesa, y Josselin, conde de Tel Bashir, fueron derrotados y capturados por los musulmanes en la batalla de Harrán el 9 de Shaban de 497 / 7 de mayo de 1104. Sökmen, héroe de la victoria, enfermó y murió en octubre del mismo año.", "3b141414"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-10-01:0":{"b": ["Sökmen murió; le sucedió su hijo İbrâhim", "c40e3436"], "d": ["Sökmen, que enfermó poco después de la victoria de Harrán, murió en octubre de 1104; a la rama de Hısnıkeyfâ accedió su hijo İbrâhim, y con la muerte de İbrâhim en 1108 su hermano Dâvud se convirtió en gobernante artuquí.", "3fb73425"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1110-01-01:0":{"b": ["Muhammed Tapar derrotó a las fuerzas georgianas y destruyó algunas ciudades", "372cbcc6"], "d": ["Cuando el rey David II inició una nueva campaña de invasión con un gran ejército obtenido de los kipchaks y llegó hasta Ganja, el sultán selyúcida Muhammed Tapar marchó sobre Georgia, derrotó a las fuerzas georgianas y destruyó algunas ciudades (503/1110).", "f381ea2e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1110-01-01:1":{"b": ["Melikşah (Şâhinşah), enviado por el sultán de los Grandes Selyúcidas Muhammed Tapar, ocupó en Konya el trono de los selyúcidas de Anatolia", "b8987991"], "d": ["Tras la muerte de Kılıcarslan I, ante los ataques de Alejo Comneno, Muhammed Tapar envió a Anatolia a Melikşah, hijo mayor de Kılıcarslan; Melikşah llegó a Konya, ocupó el trono y luchó seis años contra Alejo.", "a8488c23"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1111-09-01:0":{"b": ["Sökmen el-Kutbî murió en Balis, a orillas del Éufrates; le sucedió su hijo Zahîrüddin İbrâhim", "510ea223"], "d": ["Sökmen, que se unió al ejército de Mevdûd, hijo de Altuntegin, enviado por Muhammed Tapar contra los cruzados, se separó del ejército al agravarse su enfermedad y murió en Balis en septiembre de 1111. Su hijo İbrâhim asumió la jefatura de los Ahlatşah y permaneció hasta 1126/1127.", "1ca34ea9"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1112-01-01:0":{"b": ["El artuquí Belek estableció su centro en Palu y se apoderó de las tierras de los Çubukoğulları", "624ab91f"], "d": ["Con el dominio de Harput por Belek b. Behrâm en 1112, Palu pasó de los Çubukoğulları a la rama de Harput de los artuqíes; Belek la hizo su capital.", "2d7c33df"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1118-01-01:0":{"b": ["David IV comenzó a asentar en Georgia a 45.000 familias kipchaks", "559894b0"], "d": ["David, tras llegar a un acuerdo con 45.000 familias kipchaks del Cáucaso septentrional y de las estepas del sur de Rusia, las trajo a Georgia a partir de 1118 y con su ayuda puso fin en 1121 al dominio selyúcida en Tiflis.", "d4bc7246"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1119-01-01:0":{"b": ["Emîr Gazi derrotó a Roger, príncipe de Antioquía, y realizó una incursión a Antioquía", "7bd138a2"], "d": ["Emîr Gazi, en mayo de 1119, hizo una incursión a Antioquía con un ejército de 7000 hombres y derrotó a Roger, príncipe de Antioquía, que marchó contra él.", "c575e81b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1121-08-12:0":{"b": ["El rey georgiano David derrotó al ejército musulmán en Didgori; se abrió el camino hacia Tiflis y Ani", "03b19a6d"], "d": ["Tuğrul, rey de Ganja, el atabeg Gündoğdu, Dübeys b. Sadaka, el artuquí İlgazi y Dilmaçoğlu Togan Arslan, enviados por el sultán de los selyúcidas del Irak Mahmûd contra el gran ejército obtenido de los kipchaks por el rey georgiano David (David II en la TDV; David IV Agmashenebeli en las fuentes georgianas), fueron derrotados cerca de Didgori el 12 de agosto de 1121. A continuación los georgianos ocuparon Tiflis, bajo dominio islámico desde hacía siglos, y la hicieron capital.", "d186cc45"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1122-11-19:0":{"b": ["Necmeddin İlgazi murió; sus hijos gobernaron, Süleyman en Mayyafariqin y Timurtaş en Mardin", "5e1a6c08"], "d": ["İlgazi, gobernante artuquí de Mardin, que libró una gran lucha contra los cruzados desde Alepo, enfermó durante la campaña de la fortaleza de Zerdenâ con su sobrino Belek y Tuğtegin, atabeg de Damasco, y murió el 19 de noviembre de 1122. De sus hijos, Süleyman gobernó en Mayyafariqin y Timurtaş en Mardin; su sobrino Süleyman, en Alepo.", "6f429e0c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1124-01-01:0":{"b": ["Con la toma de la región de Malatya por Emîr Gazi, Elbistan pasó a la administración danişmendí", "5be35d74"], "d": ["Elbistan, arruinada por un gran terremoto en 1114, pasó en 1124 a la administración de los danişmendíes cuando Emîr Gazi tomó la región de Malatya.", "a81725b1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1129-01-01:0":{"b": ["Los danişmendíes pusieron bajo su control la región de Kastamonu", "e1be4a42"], "d": ["En 1129 Ankara, Çankırı, Kastamonu y la costa del mar Negro pasaron al control de Emîr Gazi; la región de Kastamonu se incorporó a las fronteras danişmendíes.", "df047345"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1129-01-01:1":{"b": ["Los danişmendíes pusieron bajo su control Çankırı, Kastamonu y las costas del mar Negro", "db4c771a"], "d": ["Los danişmendíes, el Estado más poderoso de Anatolia en tiempos de Emîr Gazi, pusieron bajo su control en 1129 Ankara, Çankırı, Kastamonu y las costas del mar Negro; la mayor parte de las tierras que se extendían de Malatya al Sakarya pasó a la administración danişmendí.", "1d1edb93"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1130-01-01:0":{"b": ["El shaddadí Fazl IV murió en la guerra emprendida por Kurti, emir de Erzen, para recuperar Dvin", "d8a7ad18"], "d": ["Fazl IV, que recuperó Ani tras asediarla y anexó Ganja y Dvin, murió en 524/1130 en la guerra emprendida por Kurti, emir de Erzen, para recuperar Dvin; le sucedió su hermano, pero su hijo Mahmûd llegó a Ani y se apoderó del gobierno.", "7810bf30"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1131-01-01:0":{"b": ["El saltukí Ziyâeddin Gazi derrotó al rey georgiano Ivane", "5ba067d6"], "d": ["Ziyâeddin Gazi, que participó en la campaña organizada contra los georgianos cuando estos llegaron hasta Oltu pasando por İspir y Pasinler en 1126, derrotó al rey Ivane en 1131.", "d91b0282"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1132-01-01:0":{"b": ["Con la muerte de Ziyâeddin Gazi, su sobrino İzzeddin Saltuk II asumió la jefatura del beylicato saltukí", "726791ef"], "d": ["Ziyâeddin Gazi, pariente del artuquí Timurtaş, murió en 526/1132; su sobrino İzzeddin Saltuk II asumió la jefatura del beylicato.", "a7412435"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1134-01-01:0":{"b": ["Emîr Gazi murió; su hijo mayor Melik Muhammed fue proclamado gobernante en Malatya", "1cf04ea6"], "d": ["Emîr Gazi (Melik Gazi), el gobernante más influyente de Anatolia, murió en 528/1134. El diploma de investidura, el cetro de oro y los regalos enviados por el califa abasí Mustarshid-Billah y por el sultán Sencer fueron entregados a Melik Muhammed, que fue proclamado gobernante en Malatya. Sus hermanos Aynüddevle y Yağan se sublevaron.", "e39192f6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:0":{"b": ["El sultán Mesud tomó Sivas; arrebató Ankara, Çankırı y Kastamonu a los danişmendíes y se las dio a su hijo Şâhinşah", "cc439683"], "d": ["Cuando con la muerte de Melik Muhammed los danişmendíes se dividieron en tres ramas, el sultán selyúcida de Anatolia Mesud I marchó sobre Sivas y tomó la ciudad, y nombró a su hijo menor Şâhinşah gobernador de Ankara, Çankırı y Kastamonu.", "6b775908"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:1":{"b": ["El sultán Mesud tomó Kastamonu a los danişmendíes y la dejó a su hijo Şâhinşah", "ae895779"], "d": ["El sultán Mesud, que tomó Sivas, dio el gobierno de Kastamonu, junto con Ankara y Çankırı, a su hijo menor Şâhinşah.", "f8cfb811"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:2":{"b": ["El sultán Mesud tomó Çankırı a los danişmendíes y la dejó a su hijo Şâhinşah", "8047e8a8"], "d": ["Mesud I, aprovechando las luchas por el trono danişmendíes, se apoderó de Ankara, Çankırı y Kastamonu y dejó el gobierno de estas tres ciudades a su hijo Şâhinşah.", "07d66793"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1143-06-17:0":{"b": ["El sultán Mesud inició el asedio de Malatya, que duró tres meses; sin resultado, lo levantó el 14 de septiembre de 1143", "4c2d2d2b"], "d": ["El sultán Mesud, que tomó Sivas de la dinastía dividida en tres con la muerte del danişmendí Melik Muhammed (537/1142), asedió Malatya el 1 de Dhu l-Hiyya de 537 / 17 de junio de 1143; tras tres meses sin resultado, levantó el asedio el 2 de Rabi' al-awwal de 538 / 14 de septiembre de 1143 y regresó a Konya.", "2dc53da5"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1143-12-06:0":{"b": ["Melik Muhammed murió en Kayseri; los danişmendíes se dividieron en las ramas de Sivas, Malatya y Kayseri", "1ee92ff3"], "d": ["Tras Melik Muhammed, que según Miguel el Sirio murió en Kayseri el 6 de diciembre de 1143, su hermano Yağıbasan estableció su dominio en Sivas, su hijo Zünnûn en Kayseri y Aynüddevle en Malatya y Elbistan; los danişmendíes, divididos en tres ramas, entraron en una lucha destructiva entre sí.", "b07a9299"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1144-08-01:0":{"b": ["Murió Dâvud, gobernante artuquí de Hısnıkeyfâ; le sucedió su hijo Fahreddin Kara Arslan", "4782f166"], "d": ["Dâvud, que se alió con el artuquí de Mardin Timurtaş contra Zengî, atabeg de Mosul, murió el 1 de agosto de 1144; su hijo Fahreddin Kara Arslan llegó a un acuerdo con el sultán selyúcida de Anatolia Mesud I contra Zengî.", "48a2c46f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1153-03-29:0":{"b": ["Por la conspiración de Fahreddin Şeddâd, emir de Ani, el ejército saltukí fue derrotado por el rey georgiano Demetrio; İzzeddin Saltuk fue capturado", "f936d922"], "d": ["Şeddâd, emir de Ani, que había pretendido a la hija de Saltuk y fue rechazado, comunicó que quería vender la ciudad a Saltuk y entrar a su servicio; cuando Saltuk llegó con su ejército, avisó al rey georgiano. El ejército saltukí fue gravemente derrotado por el rey Demetrio, Saltuk fue capturado y se liberó con un rescate de 100.000 dinares.", "0d47e21f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1155-01-01:0":{"b": ["Tras la muerte del sultán Mesud, a su yerno danişmendí Yağıbasan se le dieron Amasya, Ankara y Capadocia", "295fac37"], "d": ["Cuando con la muerte de Mesud subió al trono Kılıcarslan II (1155), de los dos yernos de Mesud pertenecientes a la dinastía danişmendí, a Yağıbasan se le dieron Amasya, Ankara y Capadocia y a Zünnûn las ciudades de Kayseri y Sivas; sus hermanos se sublevaron reclamando derechos al trono.", "b6540bd8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1155-03-07:0":{"b": ["Fahreddin Şeddâd cayó prisionero de los georgianos; por la rebelión de las monjas armenias en Ani, fue puesto en su lugar su hermano Fazl V", "2e64eb02"], "d": ["Las monjas armenias, que reaccionaron ante la conducta de Fahreddin Şeddâd tras la derrota del ejército saltukí por el rey georgiano Demetrio, se sublevaron y pusieron en Ani, en lugar de Saltuk, a su hermano Fazl V (550/1155); el emirato de Fazl V terminó en 1161 con la entrega de Ani al rey georgiano.", "56cd50fc"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1161-01-01:0":{"b": ["El rey georgiano Jorge tomó Ani", "8081e228"], "d": ["El rey georgiano Jorge, tras infligir en 1154 una grave derrota al gobernante saltukí İzzeddin Saltuk, tomó la ciudad de Ani en 1161; el emirato shaddadí terminó cuando el clero se sublevó y entregó la ciudad al rey georgiano.", "357c7a97"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1161-08-01:0":{"b": ["El Ahlatşah Sökmen, İzzeddin Saltuk y Devletşah asediaron Ani; los musulmanes fueron derrotados cuando Saltuk abandonó el campamento", "d651d8fe"], "d": ["Tras la toma de Ani por el rey georgiano Jorge, Sökmen II, shah de Ahlat, İzzeddin Saltuk II, Fahrüddevle Devletşah, bey de Erzen y Bitlis, y otros emires turcos se unieron y asediaron la ciudad. Al llegar el rey Jorge, Saltuk abandonó el campamento sin avisar a los demás beyes; los musulmanes fueron derrotados, muchos fueron muertos y 9000 cayeron prisioneros.", "2345b0e8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1162-01-01:0":{"b": ["Los georgianos invadieron Dvin", "e8f2a041"], "d": ["Los georgianos, que tomaron Ani en 1161, invadieron al año siguiente Kars y Dvin; después la campaña conjunta de los beyes musulmanes derrotó a Georgia en 1163.", "b28be1b3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1162-01-01:1":{"b": ["Los georgianos invadieron Kars y Dvin", "a7388ca5"], "d": ["Los georgianos, tras tomar Ani en 1161, invadieron al año siguiente Kars y Dvin; después de matar a numerosos musulmanes e incendiar mezquitas y casas, regresaron a Tiflis.", "2a892f7b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1163-01-01:0":{"b": ["El ejército unido de los beyes musulmanes derrotó al rey georgiano Jorge; Jorge se vio obligado a devolver Ani", "346b30b1"], "d": ["El gran ejército formado por iniciativa del sultán Tuğrul y del atabeg Şemseddin İldeniz infligió en 558/1163 una grave derrota al rey de Georgia Jorge, y Jorge se vio obligado a devolver Ani.", "a59e4ef4"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1163-07-01:0":{"b": ["El ejército aliado de los beyes turcos derrotó al ejército georgiano cerca de la fortaleza de Lukri", "58d3a0d5"], "d": ["Más de 50.000 muyahidines, entre ellos İldeniz, Sökmen, İzzeddin Saltuk, İbn Aksungur y Arslanşah, invadieron Georgia; en julio de 1163 los georgianos fueron derrotados cerca de la fortaleza de Lukri, el rey Jorge huyó dejando su impedimenta y se vio obligado a devolver Ani.", "7ac70a0b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1164-08-04:0":{"b": ["Yağıbasan, melik de Sivas, murió en Çankırı; comenzó una nueva lucha entre los danişmendíes", "59448eb7"], "d": ["Yağıbasan, que fue a Çankırı para obtener ayuda de Şâhinşah, melik selyúcida de Çankırı, contra Kılıcarslan II, murió allí el 4 de agosto de 1164; fue enterrado en el cementerio de la madrasa que él mismo había hecho construir en Niksar. Quién le sucedió tras su muerte es objeto de disputa.", "0efd18be"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1165-01-01:0":{"b": ["Kılıcarslan II tomó a los danişmendíes la región de Darende y Gedük (Şarkışla)", "917ee1e6"], "d": ["Kılıcarslan II, que aprovechó la lucha interna de la dinastía tras la muerte de Yağıbasan, anexó en 1165 la región de Elbistan, Darende y Gedük.", "7f39a47e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1168-01-01:0":{"b": ["İzzeddin Saltuk II murió; subió al trono su hijo Nâsırüddin Muhammed", "40c0ab87"], "d": ["Tras İzzeddin Saltuk, que murió en 563/1168, subió al trono saltukí su hijo Nâsırüddin Muhammed; la Gran Mezquita de Erzurum se construyó en su nombre en 1179.", "18b4b682"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1170-09-14:0":{"b": ["Kılıcarslan II hizo reconstruir Aksaray y la convirtió en base militar con el nombre de Dârüzzafer", "e0f2e591"], "d": ["Kılıcarslan II convirtió en base militar la ciudad de Aksaray, que hizo reconstruir en 566 (1170-71) y a la que dio el nombre de Dârüzzafer; hizo construir mezquitas, zavias, madrasas y un caravasar, y asentó allí a los gazis y sabios que había traído de Azerbaiyán.", "0ddd80f6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1172-01-01:0":{"b": ["El pueblo de Sivas se sublevó y mató a İsmâil; con el apoyo de Nûreddin Zengî, Zünnûn subió al trono danişmendí en Sivas", "ab96caf2"], "d": ["En Sivas el pueblo se sublevó contra İsmâil por la hambruna y porque no repartía las existencias de los graneros; İsmâil y su esposa fueron muertos. Los notables de la ciudad invitaron a Zünnûn, que se había refugiado junto a Nûreddin; Zünnûn subió al trono danişmendí en Sivas en 567/1172 con la ayuda de Nûreddin, pero poco después huyó a Niksar por la presión de Kılıcarslan II.", "374133e0"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1175-01-01:0":{"b": ["Kılıcarslan II tomó Niksar a los danişmendíes y la incorporó al dominio selyúcida", "e49e3971"], "d": ["Kılıcarslan II conquistó en el verano de 1175 Sivas, Niksar, Comana, Tokat y otras tierras danişmendíes; Niksar, uno de los centros danişmendíes, en cuyo cementerio de la madrasa estaba enterrado Yağıbasan, pasó a manos selyúcidas.", "aa58d509"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1175-01-01:1":{"b": ["Kılıcarslan II tomó Tokat a la provincia danişmendí desaparecida y la incorporó al dominio selyúcida", "1894c403"], "d": ["Tras la muerte del atabeg Nûreddin Mahmud Zengî en 569/1174, Kılıcarslan II, desdeñando las condiciones del tratado, conquistó en el verano de 1175 Sivas, Niksar, Comana, Tokat y otras tierras danişmendíes; Zünnûn y Şâhinşah se refugiaron en Bizancio y la rama de Sivas de los danişmendíes desapareció.", "dbfcc454"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1180-05-28:0":{"b": ["Kılıcarslan II tomó a Bizancio Uluborlu, Kütahya y la región de Dorileo (Eskişehir)", "807be33d"], "d": ["Como el emperador Manuel no cumplió las condiciones del tratado y no derribó la fortaleza de Dorileo, Kılıcarslan II hizo devastar en 573/1177 el valle del Menderes; Uluborlu, Kütahya y Dorileo pasaron al dominio selyúcida en 576/1180.", "60e80418"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1184-01-01:0":{"b": ["El rey georgiano David marchó sobre Erzurum; regresó ante la resistencia de la población", "07419985"], "d": ["El rey georgiano David marchó sobre Erzurum, derrotó a Nâsırüddin Muhammed y lo obligó a replegarse a la ciudad; ante el valor y la determinación de la población turca, saqueó los alrededores y se retiró (580/1184-85).", "85711193"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1184-04-14:0":{"b": ["Kılıcarslan II repartió su país entre sus once hijos", "b1ee119d"], "d": ["En su vejez Kılıcarslan II dividió el país entre sus hijos; Tokat correspondió a su hijo mayor Rükneddin Süleyman Şah. El país selyúcida quedó dividido en once partes.", "09e83cd3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1185-01-01:0":{"b": ["El gobernador Isaac Ducas Comneno se sublevó contra el emperador Andrónico y proclamó la independencia de Chipre", "445f5db0"], "d": ["Mientras Chipre continuaba como provincia de Bizancio, el gobernador Isaac Ducas Comneno se sublevó contra el emperador Andrónico Comneno y proclamó su independencia, y Chipre salió del dominio bizantino en 1185.", "00f3ca97"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1185-07-10:0":{"b": ["El Ahlatşah Sökmen II (Shah-i Armen) murió durante el asedio de Mosul", "f492f6ba"], "d": ["Cuando Saladino asedió de nuevo Mosul en 1185, llegó la noticia de la muerte de su aliado Sökmen (9 de Rabi' al-ajir de 581 / 10 de julio de 1185). Saladino no regresó con las manos vacías de la campaña de Ahlat y tomó Mayyafariqin, que había quedado sin gobernante.", "2692f19a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1190-05-17:0":{"b": ["El ejército cruzado al mando de Federico Barbarroja derrotó al ejército selyúcida y entró en Konya", "f1f901b6"], "d": ["Barbarroja, emperador de Alemania, que pasó a Anatolia desde Gallípoli en marzo de 1190, entró en tierras selyúcidas cerca de Uluborlu y el 17 de mayo de 1190 derrotó al ejército de Kutbüddin Melikşah y de los demás meliks selyúcidas y entró en Konya, la capital abandonada por el sultán.", "0d30744a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1192-08-26:0":{"b": ["Kılıcarslan II murió durante el asedio de Aksaray; le sucedió Keyhusrev I", "083f9fae"], "d": ["Kılıcarslan II, que asedió Aksaray junto con Gıyâseddin Keyhusrev durante su lucha con sus hijos, enfermó y murió el 15 de Shaban de 588 / 26 de agosto de 1192; Keyhusrev subió al trono en Konya.", "1f04ea47"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1193-05-18:0":{"b": ["El Ahlatşah Begtemür fue asesinado por su yerno Hezâr Dînârî", "12078a3c"], "d": ["Unos dos meses y medio después de la muerte de Saladino, Seyfeddin Begtemür fue asesinado el 18 de mayo de 1193 por su yerno Bedreddin Aksungur Hezâr Dînârî, uno de sus comandantes. Hezâr Dînârî encarceló al hijo de siete años de Begtemür y a su esposa en una fortaleza de la región de Erzás.", "e0117ffd"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1196-11-24:0":{"b": ["Gıyâseddin Keyhusrev cedió el trono a su hermano Rükneddin Süleyman Şah y partió al exilio", "557c281e"], "d": ["Keyhusrev I, que luchaba con sus hermanos, tuvo que ceder el trono a Süleyman Şah II (Rükneddin) (593/1196) y salió de Konya; Süleyman Şah tomó las tierras de sus hermanos y estableció la unidad del país.", "129847ea"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1197-01-01:0":{"b": ["Amalarico de Lusignan tomó el título de rey de Chipre; ese mismo año fue reconocido también como rey de Jerusalén por los cruzados de Acre", "c38ed247"], "d": ["Amalarico tomó el título de rey en 1197 y ese mismo año fue reconocido como rey de Jerusalén por los cruzados de Acre; el Reino de Chipre se convirtió en la base naval del Oriente cruzado.", "1d28312c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1199-01-06:0":{"b": ["León se ciñó en la catedral de Tarso la corona enviada por el emperador del Sacro Imperio Romano Germánico Enrique VI y fue el primer rey del Reino Armenio de Cilicia", "99ceea3a"], "d": ["León, príncipe rupénida, se ciñó en la catedral de Tarso la corona enviada por el emperador del Sacro Imperio Romano Germánico Enrique VI y fue consagrado por el representante papal; el principado rupénida se transformó en el Reino Armenio de Cilicia.", "05fe804d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1201-06-23:0":{"b": ["Süleyman Şah II tomó Malatya a su hermano Muizzüddin Kayser Şah", "fff1df20"], "d": ["Süleyman Şah, que actuó contra su hermano Muizzüddin Kayser Şah, melik de Malatya, que se resistía a someterse a él, tomó la ciudad el 19 de Ramadán de 597 / 23 de junio de 1201.", "65e22bbb"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1202-01-01:0":{"b": ["Campaña de Süleyman Şah II a Georgia: los selyúcidas, atacados por los georgianos en el campamento, sufrieron graves pérdidas; fue capturado Behram Şah, bey mengücúquí de Erzincan", "3ee9e922"], "d": ["Süleyman Şah II, que en 1202 salió en campaña contra los georgianos que atacaban tierras turcas, fue atacado por los georgianos mientras descansaba en el campamento y sufrió graves pérdidas; entre los prisioneros estaba también Behram Şah, bey mengücúquí de Erzincan.", "4151b3d2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1202-06-25:0":{"b": ["Süleyman Şah II puso fin a la dinastía saltukí y concedió Erzurum como iqta a su hermano Tuğrul Şah", "37a63791"], "d": ["Süleyman Şah II, sultán selyúcida de Anatolia, que llegó a Erzurum durante la campaña de Georgia, encarceló a Melikşah y abolió el beylicato saltukí (2 de Shawwal de 598 / 25 de junio de 1202) y entregó Erzurum a su hermano Mugīsüddin Tuğrul Şah, melik de Elbistan. Las tierras saltukíes permanecieron en manos de Tuğrul Şah hasta 1225.", "6d717627"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1204-01-01:0":{"b": ["Süleyman Şah II murió; subió al trono su hijo menor Kılıcarslan III", "838d74dd"], "d": ["Süleyman Şah II, que no había obtenido resultado de la campaña de Georgia de 1202, murió en el camino en 1204 cuando marchaba a la segunda campaña de Georgia (600/1204). Le sucedió su hijo menor Kılıcarslan III; durante su reinado de siete u ocho meses fue conquistada la región de Isparta.", "6d8da37d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1204-08-29:0":{"b": ["Los georgianos incursionaron en Azerbaiyán, entraron en el país de los Ahlatşah y saquearon la región de Malazgirt y Erciş", "beb13519"], "d": ["Los georgianos, tras una incursión exitosa en Azerbaiyán en 601/1204-05, entraron en el país de los Ahlatşah y avanzaron hasta Malazgirt y después hasta los alrededores de Erciş, quemando y arrasando todo; no salió ningún ejército a su encuentro.", "5c1e0212"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1205-03-01:0":{"b": ["Gıyâseddin Keyhusrev I fue a Konya y ocupó por segunda vez el trono selyúcida de Anatolia", "f6332e53"], "d": ["Keyhusrev, que debido a la ocupación de Constantinopla por los cruzados (citada como febrero de 1204) tuvo que ir a la fortaleza de su suegro en la región de Trebisonda, llegó a la ciudad durante la minoría de Kılıcarslan III y ocupó el trono por segunda vez (Rayab de 601 / marzo de 1205).", "59c0db32"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1207-01-01:0":{"b": ["Keyhusrev I se apoderó de la región de Denizli", "47cabadd"], "d": ["Durante el segundo sultanato de Gıyâseddin Keyhusrev I (1205-1211) fueron conquistadas las regiones de Denizli y Antalya (603/1207); Antalya fue tomada el 5 de marzo de 1207.", "190b906c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1211-06-01:0":{"b": ["Keyhusrev I murió en la guerra con el ejército bizantino cerca de Alaşehir; el ejército bizantino también sufrió graves pérdidas", "fdac0ce7"], "d": ["Keyhusrev murió en la guerra que libró con el ejército bizantino cerca de Alaşehir; el ejército bizantino también sufrió pérdidas muy graves. Su cuerpo fue enterrado primero en Alaşehir y luego llevado a Konya y sepultado en el Mausoleo de los Sultanes junto a la Mezquita de Alâeddin (finales de junio de 1211).", "fd58f9bc"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1211-06-15:0":{"b": ["Los dignatarios del Estado se reunieron en Konya y decidieron elevar al trono selyúcida a İzzeddin Keykâvus, melik de Malatya; Keykâvus I fue proclamado sultán en Kayseri", "f80be390"], "d": ["A la muerte de Keyhusrev I (608/1211), los dignatarios del Estado decidieron elevar al trono a İzzeddin Keykâvus, melik de Malatya, por ser el hijo mayor, y enviaron un mensajero para que viniera a Kayseri; su hermano Alâeddin Keykubad no reconoció su sultanato.", "09e0f400"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1212-01-01:0":{"b": ["Keykubad no reconoció el sultanato de su hermano mayor Keykâvus I y se sublevó; se encerró en la fortaleza de Ankara y se rindió", "13cc17e2"], "d": ["Alâeddin Keykubad, que se sublevó contra İzzeddin Keykâvus, proclamado sultán en Kayseri a la muerte de su padre, asedió Kayseri junto con el rey armenio León y su tío Tuğrul Şah, melik de Erzurum; sin resultado, se replegó a la fortaleza de Ankara y, agotadas las provisiones, se rindió con la condición de que no se le hiciera daño ni a él ni a la población (608/1212).", "7b48bb7a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:0":{"b": ["İzzeddin Keykâvus I murió en Viranşehir, cerca de Malatya, mientras preparaba la campaña de Alepo", "61f16209"], "d": ["İzzeddin Keykâvus, que marchaba sobre Alepo, donde tras la muerte (1216) del ayubí al-Malik al-Zahir había subido al trono su hijo de corta edad, se alió con el artuquí de Amida Nâsırüddin Mahmud y con Kökböri, señor de Arbil; cuando llegó a Malatya enfermó y murió en Viranşehir, cerca de Malatya (Shawwal de 616 / enero de 1220).", "a8264a2f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:1":{"b": ["Alâeddin Keykubad fue sacado de la prisión y proclamado gobernante en Sivas", "2e697d48"], "d": ["Keykubad, sacado de la prisión a la muerte de İzzeddin Keykâvus I, fue proclamado sultán en Sivas (616/1220). Hizo rodear de murallas Konya, Sivas y Kayseri contra la invasión mongola.", "c731bdd7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:2":{"b": ["Los mongoles derrotan por primera vez a los georgianos", "b869830b"], "d": ["Los mongoles derrotaron por primera vez a los georgianos en 1220 y entraron en Georgia en 1231.", "7f39fa9d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1225-01-13:0":{"b": ["El rey armenio Hetum pidió la paz a Keykubad; se concluyó la paz a cambio de un tributo anual de 40.000 monedas de oro y ayuda militar", "0d137195"], "d": ["Tras las quejas de los mercaderes contra los francos y los armenios, Keykubad declaró la guerra a los armenios y a los cruzados en 622 (1225); el rey armenio Hetum envió un emisario y pidió la paz. El rey pagaría cada año 40.000 monedas de oro al sultán y, cuando este lo quisiera, enviaría 1000 jinetes y 500 ballesteros.", "9d0f1a8e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1228-01-01:0":{"b": ["Alâeddin Keykubad tomó Erzincan y puso fin a la rama de Erzincan de los Mengücükoğulları", "edfdc566"], "d": ["Keykubad, que marchó contra los Mengücükoğulları, quienes querían la independencia, anexó Erzincan a las tierras de los selyúcidas de Anatolia en 625/1228; al gobernante de Şarkîkarahisar de la dinastía, Melik Muzafferüddin, se le dio Kırşehir como iktâ y, junto con algunos lugares, Efsûs como mülk.", "ba31e942"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1228-01-01:1":{"b": ["Terminó el gobierno de Melik Muzafferüddin, soberano de la rama de Şarkîkarahisar de los Mengücükoğulları; se le dio Kırşehir como iktâ", "1ec2fd55"], "d": ["Alâeddin Keykubad puso fin en 1228 a la rama de Erzincan de los Mengücükoğulları; al gobernante de Şarkîkarahisar de la dinastía, Melik Muzafferüddin, se le dio Kırşehir como iktâ y, junto con algunos lugares, la localidad de Efsûs como mülk.", "e17ab2ba"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1232-01-01:0":{"b": ["Los ejércitos selyúcidas tomaron algunas fortalezas en Georgia; la reina Rusudan propuso la paz y aceptó casar a su hija Tamara con Keyhusrev II", "2a057d64"], "d": ["En tiempos de Alâeddin Keykubad I, en 1232, Kemâleddin Kâmyâr y Mübârizüddin Çavlı organizaron una campaña contra Georgia y se apoderaron de algunas fortalezas; la reina Rusudan, que no pudo resistir al ejército selyúcida, propuso la paz y aceptó casar a su hija Tamara con Gıyâseddin Keyhusrev II, hijo de Keykubad.", "c8ce3253"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1234-01-01:0":{"b": ["La rama de Harput pasó a manos de los selyúcidas de Anatolia", "f2572ad0"], "d": ["Alâeddin Keykubad tomó Harput en 631/1234 frente al avance de los ayubíes hacia Anatolia; terminó el dominio de la rama artuklu de Harput (tras Kösedağ la ciudad pasó a manos de los ilkánidas).", "b0bea54d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1236-01-01:0":{"b": ["Los mongoles volvieron a ocupar Georgia y enviaron a los notables georgianos a Mongolia", "245ae81a"], "d": ["Cuando los mongoles volvieron a ocupar Georgia en 633/1235-36, enviaron a los notables georgianos a Mongolia; estos permanecieron allí durante años. Los mongoles emplearon a numerosos soldados georgianos en sus campañas.", "159ea654"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1237-05-31:0":{"b": ["Alâeddin Keykubad I murió envenenado por carne de caza; le sucedió su hijo Gıyâseddin Keyhusrev II", "5d74714c"], "d": ["Keykubad, que cerró la época de auge selyúcida, murió al día siguiente envenenado por la carne de caza que comió en el banquete ofrecido a los embajadores en la fiesta de Ramadán (4 de shawwal de 634 / 31 de mayo de 1237); en lugar del heredero İzzeddin Kılıcarslan, Keyhusrev II subió al trono por el empeño de los hombres de Estado.", "7b42c0c6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1239-01-01:0":{"b": ["El ejército mongol al mando de Curmagan Noyan tomó Kars y la destruyó durante la campaña de Georgia", "f510f715"], "d": ["En 636/1239 el ejército mongol al mando de Curmagan Noyan tomó Kars y la destruyó durante la campaña de Georgia; la ciudad permaneció bajo la administración de los ilkánidas hasta 1336.", "38d144da"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1242-01-01:0":{"b": ["El comandante mongol Baycu Noyan se apoderó de Erzurum y pasó a su población a cuchillo", "118b9e3a"], "d": ["Baycu Noyan, comandante mongol en Azerbaiyán, aprovechó el debilitamiento de los selyúcidas por la rebelión de los babaíes, tomó Erzurum a fines de 1242, pasó a su población a cuchillo y regresó a Mugan para atacar de nuevo Anatolia en primavera.", "dcfa189c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:0":{"b": ["Los mongoles, que ocuparon Anatolia tras Kösedağ, tomaron Amasya y la gobernaron con gobernadores mongoles", "3b39a0ad"], "d": ["Tras la batalla de Kösedağ de 1243, los mongoles que ocuparon Anatolia tomaron Amasya, y la ciudad empezó a ser administrada por gobernadores mongoles.", "a9d1a1e2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:1":{"b": ["Tras la derrota de Kösedağ, Kayseri cayó en manos de los mongoles después de diez días de resistencia", "5600cbe9"], "d": ["Tras la batalla de Kösedağ (1243), Kayseri cayó en manos de los mongoles después de diez días de resistencia y sufrió una gran destrucción.", "924187ac"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:2":{"b": ["La reina Rusudan aceptó pagar tributo a los mongoles y reconoció formalmente al Gran Kan como soberano", "99d19c31"], "d": ["La reina Rusudan, que comprendió que no podría hacer frente a los mongoles, aceptó someterse a ellos pagando tributo y en 1243 reconoció formalmente al Gran Kan como soberano. Tras la muerte de Rusudan, los mongoles dividieron el Cáucaso en ocho provincias.", "c61c6116"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:3":{"b": ["El emirato de Tokat fue entregado por los ilkánidas a Muînüddin Süleyman Pervâne tras Kösedağ", "f2938da6"], "d": ["Los ilkánidas, que dominaron el Estado selyúcida de Anatolia tras la batalla de Kösedağ, entregaron el emirato de Tokat a Muînüddin Süleyman Pervâne; en 1276 Tokat estaba bajo la administración de Nûreddin Cibrîl.", "d931de12"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1244-01-01:0":{"b": ["El comandante mongol Yasavur Noyan ocupó Malatya por un breve tiempo", "98759910"], "d": ["Los mongoles no obtuvieron resultado en sus primeros intentos contra Malatya tras la victoria de Kösedağ (1243); Yasavur Noyan ocupó la ciudad brevemente en 1244, y en 1258 fue destruida por Baycu Noyan.", "78c903ae"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1246-01-01:0":{"b": ["Los hombres de Estado proclamaron sultán a İzzeddin Keykâvus, melik de Uluborlu, en la aldea de Altuntaş, en Akşehir", "20d6f3e7"], "d": ["Los hombres de Estado proclamaron sultán, en la aldea de Altuntaş de Akşehir, a İzzeddin Keykâvus, que era melik de Uluborlu (Borgulu) en el momento de la muerte de Gıyâseddin Keyhusrev II (643/1246).", "e7c6a924"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1247-01-01:0":{"b": ["El rey Hetum I envió a su hermano Sempad a Karakórum y se alió con el hermano de Möngke Kan contra los mamelucos", "7413b5e5"], "d": ["El rey Hetum I, al enviar a su hermano Sempad a Karakórum, inició la alianza formal con el Imperio mongol.", "769d4bcf"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1251-01-01:0":{"b": ["Los dos David, que regresaron de Mongolia tras la entronización de Mengü Kan, reinaron conjuntamente en Georgia", "f1640157"], "d": ["Tras la entronización del Gran Kan mongol Mengü Kan (1251), los dos georgianos llamados David, designados por él, regresaron de Karakórum a su país y reinaron conjuntamente; después Batu Kan y Hulagu trataron de establecer su dominio en Georgia.", "96249933"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1255-01-01:0":{"b": ["Kılıcarslan IV fue derrotado por Keykâvus II en la batalla de Ahmedhisarı, cerca de Kayseri", "edac92e9"], "d": ["Tras la muerte de Celâleddin Karatay, Kılıcarslan se proclamó sultán independiente en Kayseri (652/1254); al año siguiente fue derrotado por Keykâvus en la batalla librada en el lugar llamado Ahmedhisarı, cerca de Kayseri.", "d64649d2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1257-01-01:0":{"b": ["Los mongoles, al mando de Yaşmut, tomaron Meyyâfârikīn tras un largo asedio; Mardin resistió ocho meses", "c2328a27"], "d": ["Cuando Hulagu marchaba a la campaña de Siria en 1257, encargó a una unidad al mando de Yaşmut tomar Mardin y Meyyâfârikīn; Meyyâfârikīn cayó tras un largo asedio, y la fortificada Mardin resistió más de ocho meses.", "18f326a7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1257-03-05:0":{"b": ["Kılıcarslan IV, traído de Burgulu a Konya, fue entronizado como único soberano selyúcida", "cb3eced9"], "d": ["Kılıcarslan IV, que se encontraba en Burgulu (Uluborlu) tras la derrota de Sultanhanı (654/1256), fue llevado a Konya y entronizado como único soberano selyúcida el 16 de safar de 655 / 5 de marzo de 1257; cuando Keykâvus II llegó a Konya el 14 de rabi' al-ajir de 655 / 1 de mayo de 1257, envió contra Kılıcarslan a su comandante Ali Bahadır.", "32f17269"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1258-01-08:0":{"b": ["Keykâvus II sometió Malatya, Sivas, Tokat y Amasya; Kılıcarslan se retiró a Erzincan", "d4834ad1"], "d": ["Cuando İzzeddin Keykâvus, con la ayuda de sus célebres comandantes, puso bajo su dominio Malatya, Sivas, Tokat y Amasya, Kılıcarslan IV se vio obligado a retirarse a Erzincan (656/1258); luego, por el yarlığ de Mengü Kan, el país fue dividido en dos (657/1259).", "5954d32b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1259-01-01:0":{"b": ["Por el yarlığ de Mengü Kan, el territorio selyúcida fue dividido en dos entre Keykâvus II y Kılıcarslan IV", "4dacbe83"], "d": ["Tras la salida de Baycu de Anatolia, Keykâvus II fue entronizado de nuevo en Konya (1 de mayo de 1257); por el yarlığ de Mengü Kan, el país fue dividido entre Keykâvus y Kılıcarslan. Keykâvus, que no aceptó el dominio mongol, se refugió en Bizancio en 660/1262.", "c7df29bf"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1260-01-01:0":{"b": ["Kara Arslan, soberano artuklu de Mardin, aceptó el dominio ilkánida", "c6b7b1a6"], "d": ["Mardin padeció hambre y peste durante el asedio mongol de más de 8 meses; Kara Arslan, que accedió al poder con la muerte de Necmeddin Gazi, reconoció el dominio mongol a cambio de que Dârâ, Habur, Nusaybin y Re'sülayn fueran devueltas a los artukíes, y en 659/1261 fue confirmado por Hulagu como soberano de Mardin.", "ff8d14de"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1260-01-01:1":{"b": ["Cuando los mongoles, derrotados por los mamelucos, se retiraron a Persia, los mamelucos atacaron Cilicia y devastaron el país", "505db4aa"], "d": ["Cuando los mongoles ilkánidas, derrotados por los mamelucos, se retiraron a Persia, los mamelucos atacaron Cilicia y devastaron el país; este es el comienzo efectivo de los ataques mamelucos.", "89ccf21b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:0":{"b": ["Muînüddin Pervâne hizo matar a Kılıcarslan IV a manos de los mongoles y entronizó a su hijo menor de edad, Keyhusrev III", "27f0dc7a"], "d": ["Cuando Kılıcarslan fue obligado a aceptar que Sinop le fuera dada como mülk, el visir Muînüddin Pervâne lo hizo matar a manos de los mongoles (664/1266) y puso en su lugar a su hijo, aún niño, Keyhusrev III; Pervâne se convirtió en el dueño indiscutido del Estado.", "4aa91de1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:1":{"b": ["Baybars descendió a Cilicia y capturó a Leyfon, hijo del rey de Sis, Hethum", "2cefee6a"], "d": ["El sultán mameluco Baybars descendió a Cilicia en 1266 y capturó a Leyfon, hijo del rey de Sis, Hethum; según el acuerdo posterior, el rey armenio devolvería las ciudades y fortalezas ocupadas y Leyfon sería puesto en libertad (en 1268 solo Besni quedó en manos de los armenios).", "e5f53d00"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:2":{"b": ["Berke, kan de la Horda de Oro, llegó hasta Tiflis", "23866ba3"], "d": ["Berke Kan llegó hasta Tiflis en 1266; el nivel de prosperidad de Georgia, bajo dominio ilkánida, era sin embargo bastante alto.", "013e2621"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1268-01-01:0":{"b": ["Los atabegs que gobernaban las zonas de Ahıska, Ardahan y Artvin (Atabegato de Samtshe/Meshet) asumieron el gobierno de la región", "71bb5a86"], "d": ["Entre 1268 y 1578, los atabegs, que eran los administradores de las zonas de Ahıska, Ardahan y Artvin, mantuvieron en sus manos el gobierno de la región y en este periodo permanecieron sometidos a los Estados ilkánida, Kara Koyunlu y Ak Koyunlu.", "44bea8bb"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1269-01-01:0":{"b": ["Hetum I abdicó y cedió el trono a su hijo Levon II; el reino pasó a ser de hecho vasallo de los mamelucos", "3d94aadc"], "d": ["Hetum I abdicó y cedió su lugar a su hijo Levon II; Levon II se vio obligado a pagar un gran tributo anual y el reino pasó a ser de hecho vasallo de los mamelucos.", "cd7ade63"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1271-01-01:0":{"b": ["El sultán mameluco Baybars envió una flota de diecisiete naves contra Chipre; el ataque fracasó a causa de una tormenta", "cfeb4521"], "d": ["Mientras tomaba en 1271 las últimas fortalezas y ciudades de los cruzados en Palestina y Siria, Baybars envió contra Chipre una flota de diecisiete naves, pero el ataque fracasó a causa de una tormenta que se levantó.", "c0ba5344"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1275-01-01:0":{"b": ["Se fundó el beylicato de los Sâhib Ataoğulları en Afyonkarahisar y sus alrededores", "c909e2f5"], "d": ["Los hijos y nietos del visir selyúcida de Anatolia Sâhib Ata fundaron un beylicato en Afyonkarahisar y sus alrededores (1275-1341).", "26972b2f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1277-06-04:0":{"b": ["Los ilkánidas, al descubrir la traición de Muînüddin Süleyman Pervâne, pusieron fin a su vida", "9a7cc34e"], "d": ["Abaka Kan, que llegó con un gran ejército tras la salida de Baybars de Anatolia, hizo masacrar a 200.000 personas alegando colaboración con los mamelucos; al descubrir también la traición de Pervâne, pusieron fin a su vida y empezaron a administrar el Estado selyúcida de Anatolia con funcionarios enviados desde Tabriz (muerte de Pervâne: 676/1277).", "c7bb6ee3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1280-05-03:0":{"b": ["Mesud II, hijo de Keykâvus II, llegó a Sinop y se dirigió a la capital ilkánida para presentarse ante Abaka Kan", "9b43e13f"], "d": ["Mesud II, hijo y heredero de Keykâvus II, llegó a Sinop en 679/1280, luego fue a la capital ilkánida y se presentó ante Abaka Kan; Abaka Kan le entregó la administración de Erzurum, Erzincan, Sivas, Diyarbekir y Harput.", "0ddb3753"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1282-04-11:0":{"b": ["Argun Kan proclamó sultán a Mesud II e hizo matar a Keyhusrev III", "0afda15b"], "d": ["Tras la partición de las tierras selyúcidas por Ahmed Teküder entre Mesud II y Keyhusrev III, Argun Kan, que salió vencedor en la lucha por el trono ilkánida, proclamó sultán a Mesud II, que se encontraba en Tabriz (681/1282), e hizo matar a Keyhusrev III, que esperaba en Erzurum.", "ffa63120"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1284-03-20:0":{"b": ["Mesud II regresó a Anatolia y subió al trono como sultán selyúcida, primero en Kayseri y luego en Konya", "ca5c28f4"], "d": ["Mesud II regresó a Anatolia con la aprobación de Argun y subió al trono en Kayseri y en Konya en 683/1284; bajo la tiranía de los comandantes y gobernadores mongoles siguió siendo un 'soberano de sombra' y combatió a los Karamanoğulları, los Eşrefoğulları y los Germiyanoğulları.", "c089c457"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1288-11-22:0":{"b": ["El visir selyúcida Sâhib Ata Fahreddin Ali murió cerca de Akşehir", "9c7034f1"], "d": ["Sâhib Ata, que sirvió a Keykâvus como nâib-i saltanat (657/1259), fue encarcelado en la fortaleza de Osmancık en 670/1271-72 y nombrado visir de nuevo en 674/1275-76; murió el 25 de shawwal de 687 / 22 de noviembre de 1288 en la aldea de Nâdir, dependiente de Akşehir, tras una campaña con el ejército aliado selyúcida-mongol contra los Karamanoğulları a fines de 686 / comienzos de 1288, y fue sepultado en su mausoleo de Konya.", "f8bf5f4a"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0481-01-01:0":{"b": ["Clodoveo sucedió a su padre Childerico como rey de los francos salios; el centro de su poder era Tournai", "e4d35fd1"], "d": ["Clodoveo se convirtió en 481, a los quince años, en rey de los francos salios en lugar de su padre Childerico I. En aquella fecha los francos salios habían avanzado hasta el río Somme y el centro de su poder era Tournai.", "d4c684f8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0486-01-01:0":{"b": ["Clodoveo derrota a Siagrio en la batalla de Soissons; el residuo del dominio romano al sur del Somme pasa a los francos", "afa05aa7"], "d": ["Clodoveo atacó en 486 al general romano Siagrio; derrotado en la batalla de Soissons, Siagrio se refugió junto al rey visigodo Alarico II y le fue entregado. Clodoveo trasladó después su residencia a Soissons y fue tomando poco a poco la Bélgica Segunda (cuya capital era Reims).", "f20e6e70"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0496-12-25:0":{"b": ["Clodoveo es bautizado en Reims por el obispo Remigio (Navidad)", "16299c9a"], "d": ["Tras su victoria sobre los alamanes, Clodoveo fue a Reims y el día de Navidad de 496 fue bautizado por san Remigio junto con tres mil francos. El bautismo volvió hacia Clodoveo la mirada de la población católica de los reinos de los burgundios y de los visigodos.", "2d58bf65"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0507-01-01:0":{"b": ["Clodoveo mata en Vouillé (cerca de Poitiers) al rey visigodo Alarico II; el territorio visigodo hasta los Pirineos pasa a los francos", "e8ea0c78"], "d": ["Tras completar en 506 el sometimiento de los alamanes, Clodoveo marchó al año siguiente contra el rey visigodo Alarico II. En Vouillé, cerca de Poitiers, mató a Alarico con su propia mano; la parte del reino visigodo que se extendía hasta los Pirineos, salvo Septimania, se incorporó al Estado franco.", "e632a672"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0511-11-27:0":{"b": ["Muere Clodoveo; es enterrado en París, a la que hizo capital en sus últimos años; la unidad del reino queda como herencia merovingia", "c6c9caa4"], "d": ["Clodoveo pasó sus últimos años en París y la convirtió en capital del reino; tras eliminar a los pequeños reyes francos de centros como Cambrai y Colonia, se convirtió en el único rey de todas las tribus francas. Murió en 511.", "eeb42f8c"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0756-01-01:0":{"b": ["Pipino III, con sus campañas de Italia, quita a los longobardos el exarcado de Rávena y lo dona al papa; nace el Estado Pontificio", "f6bbc975"], "d": ["Pipino III hizo dos campañas en Italia, en 754 y 756, a petición del papa Esteban II; al donar al papa el exarcado de Rávena, tomado al rey longobardo Astolfo, se convirtió en el creador del Estado temporal del papado. Pipino otorgó al papa el título de «Patricio de los romanos».", "0e4f19d8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0800-12-25:0":{"b": ["Carlomagno es proclamado y coronado emperador por el papa León III en San Pedro de Roma", "3d72f37d"], "d": ["Carlomagno fue a Roma en 800 con el propósito de restablecer el orden; al día siguiente, el día de Navidad, al levantarse de la oración en la basílica de San Pedro, fue coronado por el papa León III y proclamado emperador y augusto.", "d6956767"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0814-01-28:0":{"b": ["Carlomagno muere en Aquisgrán y es enterrado ese mismo día en la iglesia de Santa María", "915d6f61"], "d": ["Carlomagno pasó en Aquisgrán (Aix) la mayor parte de sus últimos años. A comienzos de 814 le subió la fiebre; a consecuencia de una pleuresía murió el 28 de enero de 814, después de comulgar, y fue enterrado ese mismo día en la iglesia de Santa María de Aquisgrán; le sucedió su hijo Ludovico Pío.", "8ce37094"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0842-02-14:0":{"b": ["Juramentos de Estrasburgo: Carlos el Calvo y Luis el Germánico juran alianza en Estrasburgo", "b462f12a"], "d": ["Un año después de la victoria de Fontenoy, Carlos el Calvo y Luis el Germánico reforzaron su alianza con los Juramentos de Estrasburgo; Carlos juró en la lengua germánica del pueblo de Luis, y Luis en la lengua romance de los súbditos de Carlos.", "02ceae89"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0843-08-10:0":{"b": ["Tratado de Verdún: el Imperio carolingio se divide en tres (Francia occidental, Francia media, Francia oriental)", "1b628d03"], "d": ["Los hijos de Ludovico Pío se repartieron el Imperio en agosto de 843 por el tratado alcanzado en Verdún: Carlos el Calvo recibió el oeste de la línea Mosa-Saona-Ródano (Francia occidental, incluida la Marca de España), Luis el Germánico el este del Rin (Baviera, Turingia, Franconia, Sajonia; además la región de Espira-Worms-Maguncia), y Lotario recibió Italia, el título imperial y la franja de los valles del Rin y el Ródano.", "5bda08ed"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0875-12-25:0":{"b": ["Carlos el Calvo recibe en Roma la corona imperial", "49f42456"], "d": ["Tras la muerte de Luis II, Carlos el Calvo descendió a Italia con el apoyo del papa Juan VIII y recibió en Pavía la corona del reino de Italia y en Roma la corona imperial.", "d63d65ae"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0893-01-28:0":{"b": ["Carlos el Simple es coronado rey en Reims; comienza una realeza rival frente a Odón", "ccc4acd5"], "d": ["Carlos III el «Simple» había sido excluido por su juventud cuando Carlos el Gordo fue depuesto en 887; durante el reinado de Odón, con el reconocimiento de una parte de los grandes, fue coronado en Reims el 28 de enero de 893 y, con la alianza del emperador, obligó a Odón a ceder una parte de Neustria. Con la muerte de Odón en 898 poseyó todo el reino.", "cd52d1cb"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0911-01-01:0":{"b": ["Tratado de Saint-Clair-sur-Epte: Carlos el Simple cede a los normandos la actual Normandía", "fd0306b0"], "d": ["Carlos III firmó en 911 un tratado con los normandos en Saint-Clair-sur-Epte; una parte de los normandos fue bautizada y se les cedió la tierra que después se conocería como ducado de Normandía. La historia del matrimonio de Rollón con la hermana del rey es un relato de Dudón y es muy dudosa.", "5798ced7"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0923-06-15:0":{"b": ["Batalla de Soissons: muere el rey Roberto I, Raúl, duque de Borgoña, es elegido rey", "4430302d"], "d": ["Roberto, elegido rey en 922 contra Carlos el Simple, murió en la batalla de Soissons; los partidarios de Roberto, vencedores, eligieron rey a Raúl (Rodolfo), duque de Borgoña. Carlos, que confió en Heriberto, conde de Vermandois, cayó prisionero y murió en Péronne en 929.", "9c2c291f"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0955-08-10:0":{"b": ["Batalla de Lechfeld: Otón I pone fin a las incursiones húngaras", "7bd31ba4"], "d": ["Otón marchó contra los húngaros que sitiaban Augsburgo y con la gran victoria obtenida en Lechfeld el 10 de agosto de 955 libró a Alemania de las incursiones húngaras; ese mismo año derrotó también a los eslavos.", "fbb1b763"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0962-02-02:0":{"b": ["Otón I es coronado emperador en Roma; comienzo del Sacro Imperio Romano Germánico", "24571f97"], "d": ["Otón pasó a Italia por la petición de ayuda del papa Juan XII contra Berengario; tras llegar a Pavía en la Navidad de 961, fue coronado emperador en Roma el 2 de febrero de 962 y confirmó los derechos y privilegios del papado. El pueblo de Roma juró que obtendría la aprobación del emperador en la elección del papa.", "6e725f97"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1016-04-23:0":{"b": ["Muere Etelredo II; Canuto (Cnut) es elegido rey por los grandes reunidos en Southampton", "35653e3c"], "d": ["Tras la muerte de Etelredo II el 23 de abril de 1016, el danés Canuto fue elegido rey por la asamblea de los grandes en Southampton; Londres, en cambio, permaneció leal a Edmundo. Canuto venció en la gran batalla de Assandun y, tras la muerte de Edmundo en noviembre de 1016, a comienzos de 1017 fue elegido rey de toda Inglaterra.", "3a49dfc2"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:0":{"b": ["El rey Enrique I concede el Ducado de Borgoña a su hermano Roberto; comienza la primera casa ducal capeta de Borgoña", "18dcd0ab"], "d": ["Enrique I, rey de Francia, otorgó en 1032 el Ducado de Borgoña a su hermano Roberto; de Roberto descendió la primera casa ducal capeta, que duraría hasta 1361.", "cbb03a09"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:1":{"b": ["Muere Rodolfo III, último rey de Borgoña (Arlés); su país pasa a Conrado II (emperador alemán) — Basilea entra en las tierras imperiales", "4dc8eb08"], "d": ["Rodolfo III (993-1032), último rey de Borgoña (Borgoña Jurana/Arlés), al morir sin herederos legó sus tierras al emperador Conrado II. Esta herencia es la fuente de los derechos imperiales que comprendían, en el llamado Reino de Arlés a partir del siglo XIII, una parte de la actual Suiza que se extiende del Jura al Aar, además del Franco Condado, el Lyonnais, el Delfinado, Saboya y Provenza. Desde 888 la autoridad del reino había sido reconocida en los obispados de Besançon, Basilea, Lausana, Ginebra y Sion.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:2":{"b": ["Muere Rodolfo III, último rey de Borgoña (Arlés); su país pasa a Conrado II (emperador alemán) — Ginebra entra en las tierras imperiales", "be189789"], "d": ["Rodolfo III (993-1032), último rey de Borgoña (Borgoña Jurana/Arlés), al morir sin herederos legó sus tierras al emperador Conrado II. Esta herencia es la fuente de los derechos imperiales que comprendían, en el llamado Reino de Arlés a partir del siglo XIII, una parte de la actual Suiza que se extiende del Jura al Aar, además del Franco Condado, el Lyonnais, el Delfinado, Saboya y Provenza. Desde 888 la autoridad del reino había sido reconocida en los obispados de Besançon, Basilea, Lausana, Ginebra y Sion.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:3":{"b": ["Muere Rodolfo III, último rey de Borgoña (Arlés); su país pasa a Conrado II (emperador alemán) — Lyon entra en las tierras imperiales", "78601ea1"], "d": ["Rodolfo III (993-1032), último rey de Borgoña (Borgoña Jurana/Arlés), al morir sin herederos legó sus tierras al emperador Conrado II. Esta herencia es la fuente de los derechos imperiales que comprendían, en el llamado Reino de Arlés a partir del siglo XIII, una parte de la actual Suiza que se extiende del Jura al Aar, además del Franco Condado, el Lyonnais, el Delfinado, Saboya y Provenza. Desde 888 la autoridad del reino había sido reconocida en los obispados de Besançon, Basilea, Lausana, Ginebra y Sion.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1066-01-05:0":{"b": ["Muere Eduardo el Confesor; Haroldo Godwinson es elegido y coronado rey en Londres", "3ff7af82"], "d": ["Eduardo el Confesor, que no pudo asistir a la consagración de la abadía de Westminster, murió el 5 de enero de 1066; en su lecho de muerte recomendó a Haroldo como sucesor. Haroldo fue elegido y coronado de inmediato; Northumbria, aunque al principio lo rechazó, se sometió a él. Guillermo reclamó el trono invocando el testamento de Eduardo y la promesa de Haroldo hacia 1064, y se preparó para la invasión.", "c67100ae"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1066-12-25:0":{"b": ["Guillermo, duque de Normandía, es coronado rey de Inglaterra en Westminster", "92ddd637"], "d": ["Guillermo, que desembarcó en Pevensey el 28 de septiembre de 1066, aplastó a Haroldo el 14 de octubre en la batalla de Senlac (Hastings); el día de Navidad fue coronado en Westminster. Aún le llevó cinco años someter el sur, el oeste y el norte de Inglaterra.", "78756409"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1068-01-01:0":{"b": ["Guillermo el Conquistador emprende una campaña contra la rebelde Exeter", "cc25aa87"], "d": ["El año 1068 de Guillermo transcurrió en campañas militares contra Exeter y York, donde se habían refugiado los partidarios de Haroldo.", "e1fb87c6"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1069-01-01:0":{"b": ["Rebelión del norte: daneses e ingleses toman York; Guillermo sitia la ciudad, la recupera y devasta el norte", "c15ad892"], "d": ["Tras el asesinato de Roberto de Comines en Durham, el norte proclamó a Edgar Atheling y el rey danés Sweyn envió una flota; daneses e ingleses tomaron York, protegida por dos castillos normandos. Guillermo marchó sobre York, expulsó a los daneses a sus naves, tomó la ciudad mediante un bloqueo y asoló el país hasta Durham; a comienzos de 1070 marchó sobre Chester y completó el sometimiento del norte.", "a4420b47"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1075-01-01:0":{"b": ["El papa Gregorio VII prohíbe la investidura laica (la concesión de cargos por personas no eclesiásticas) en el nombramiento del clero", "bc8488be"], "d": ["La prohibición de la investidura laica, publicada dos años después de que Hildebrando fuera elegido papa en 1073 con el nombre de Gregorio VII, amenazó el poder del Imperio sobre los nombramientos religiosos y fue el comienzo del conflicto abierto con Enrique IV.", "c78da49d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1080-03-07:0":{"b": ["El papa Gregorio VII excomulga por segunda vez a Enrique IV y lo depone", "d73a0f3d"], "d": ["Por la presión de los sajones tras la victoria de Flarchheim (27 de enero de 1080) y por una información errónea, Gregorio VII abandonó su política de espera; el 7 de marzo de 1080 volvió a excomulgar a Enrique, lo declaró depuesto y absolvió a sus súbditos de sus juramentos de fidelidad. El efecto fue mucho más débil que el de 1076; el sínodo de Brixen depuso a Gregorio el 25 de junio de 1080.", "518e832b"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1111-04-13:0":{"b": ["Enrique V es coronado emperador en Roma; el problema de la investidura se resuelve con un breve compromiso", "f7e1aee5"], "d": ["Enrique V obtuvo en Sutri, en febrero de 1111, la promesa de la corona imperial a cambio de renunciar a la investidura; se arrancó al papa Pascual II el derecho de investidura y la promesa de la corona, y la ceremonia de coronación se celebró el 13 de abril de 1111. Después de que Enrique abandonara Roma, un concilio declaró inválida esa concesión.", "5d77b395"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1152-01-01:0":{"b": ["Enrique (II) se casa con Leonor y obtiene Poitou, Guyena y Gascuña", "4db69859"], "d": ["Enrique Plantagenet fue duque de Normandía en 1150 y conde de Anjou en 1151 por la muerte de su padre; en 1152 se casó con Leonor (Eleanor), divorciada del rey de Francia Luis VII, y obtuvo Poitou, Guyena y Gascuña, que son la mitad meridional del Imperio angevino. El matrimonio le granjeó la enemistad de su soberano Luis VII.", "39880a5d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1154-10-25:0":{"b": ["Muere el rey Esteban; Enrique II accede al trono de Inglaterra sin encontrar resistencia", "e1882039"], "d": ["En 1153, con la ayuda de la Iglesia y de los partidarios de su madre Matilde, Enrique había logrado que Esteban reconociera su derecho sucesorio inglés; cuando Esteban murió el 25 de octubre de 1154, hizo valer su pretensión sin oposición. El Imperio angevino unió las tierras que se extienden de Inglaterra a los Pirineos.", "82a14d22"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1155-06-18:0":{"b": ["Federico I Barbarroja es coronado emperador en Roma", "94350025"], "d": ["Federico, en su primera campaña de Italia, iniciada en 1154, recibió la corona imperial en Roma el 18 de junio de 1155; por la insuficiencia de sus fuerzas y la hostilidad que surgió, regresó a Alemania en el otoño.", "ae0ad79e"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1157-01-01:0":{"b": ["Dieta de Besançon: los nobles de Borgoña prestan homenaje a Federico; se agrava el conflicto entre el papa y el emperador", "7252823d"], "d": ["En la dieta reunida en Besançon en octubre de 1157, los nobles borgoñones prestaron juramento de fidelidad a Federico; la desavenencia entre el papa y el emperador creció a causa de la captura, a su regreso de Roma, del arzobispo sueco.", "7b20ab27"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1173-01-01:0":{"b": ["Raimundo V, conde de Tolosa, presta homenaje (homage) a Enrique II", "460d9e41"], "d": ["Enrique II, que heredó las pretensiones de Leonor sobre Tolosa, obligó en 1173, tras una larga lucha, al conde de Tolosa Raimundo V a prestarle juramento de homenaje por Tolosa.", "1727d885"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1176-05-29:0":{"b": ["Batalla de Legnano: la Liga Lombarda derrota a Federico I", "b7613445"], "d": ["Contra Federico, que había emprendido en 1174 su quinta campaña de Italia, se había formado la Liga Lombarda y se había levantado la fortaleza de Alejandría. Como Enrique el León, duque de Sajonia, no le prestó ayuda, Federico fue derrotado en Legnano el 29 de mayo de 1176; se le creyó herido y muerto. Se retiró a Pavía y comenzó negociaciones de paz con el papa Alejandro III.", "4d37e6ac"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1177-01-01:0":{"b": ["Tratado de Venecia: Federico Barbarroja y el papa Alejandro III hacen las paces; tregua de seis años con la Liga Lombarda", "041665b3"], "d": ["Después de Legnano, Federico, por el tratado de Venecia de agosto de 1177, reconoció a Alejandro III como verdadero papa y fue absuelto de la excomunión (en julio de 1177 besó el pie del papa); se acordó una tregua de seis años con la Liga Lombarda. La herencia de Matilde se dejó a un arbitraje.", "1b138556"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1183-06-25:0":{"b": ["Paz de Constanza: Federico hace una paz duradera con la Liga Lombarda", "91ea5aaf"], "d": ["En junio de 1183 se firmó en Constanza el tratado con la Liga Lombarda (la paz duradera que sustituyó a la tregua de seis años de 1177). Enrique el León, duque de Sajonia, había sido entretanto privado de su ducado y enviado al exilio, y el ducado había sido desmembrado; en 1184 su hijo Enrique fue prometido a Constanza, hija del rey Roger de Sicilia.", "97ab19ec"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1201-01-01:0":{"b": ["Capitulación de Neuss: Otón IV reconoce la autoridad papal sobre los territorios pontificios", "b43b4c91"], "d": ["El emperador alemán Otón IV reconoció, por la capitulación de Neuss de 1201, la autoridad papal sobre la región que se extiende de Radicofani al paso de Ceprano (el exarcado de Rávena, la Pentápolis, la Marca de Ancona, el obispado de Spoleto, los dominios de Matilde, el condado de Brittenoro). Una parte de estos territorios quedó durante siglos como un mero deseo papal; la anexión efectiva de lugares como Rávena, Ancona, Bolonia y Ferrara se data en el siglo XVI.", "e76fd40c"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1204-01-01:0":{"b": ["Felipe Augusto conquista Normandía: termina la unión con Inglaterra que duraba desde 1106; Maine, Turena, Anjou y Poitou pasan a Francia en 1204-1205", "ad5f7cb2"], "d": ["Tras el asesinato de Arturo por orden de Juan sin Tierra, Felipe Augusto tomó Normandía en 1203-1204 (asedio de Château-Gaillard, de septiembre de 1203 a abril de 1204; Ruán, 24 de junio de 1204). La conquista de Maine, Turena, Anjou y Poitou fue en 1204 y 1205 casi «un paseo»; solo los castillos de Loches y Chinon resistieron un año más.", "e587727d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1204-01-01:1":{"b": ["Turena (Tours) pasa a la corona de Francia", "220394a0"], "d": ["Las conquistas de Felipe Augusto en el Loira en 1204-1205 vincularon Maine, Turena, Anjou y Poitou al rey de Francia; los castillos de Loches y Chinon resistieron un año.", "c3eaca78"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1214-01-01:0":{"b": ["Federico II otorga el Palatinado del Rin a Otón de Wittelsbach (el condado palatino en la dinastía Wittelsbach)", "5f54fd76"], "d": ["A la muerte del conde palatino del Rin Enrique en 1214, el rey alemán Federico II entregó el Palatinado a Otón, hijo menor del duque Luis I de Baviera (prometido de Inés, hermana de Enrique). Desde que en 1155 Conrado se estableció en el castillo de Juttenbühel, cerca de Heidelberg, esta zona se consideraba la capital del Palatinado.", "066e8777"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1218-01-01:0":{"b": ["Simón de Montfort muere durante el asedio de Tolosa", "6da05355"], "d": ["Simón de Montfort, comandante de la Cruzada albigense, había entrado en Tolosa en 1215, pero murió en 1218 mientras sitiaba la ciudad. El mando de los cruzados pasó a su hijo Amaury; Raimundo VII, hijo de Raimundo VI, se puso al frente del condado en 1222.", "47aa27de"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1229-01-01:0":{"b": ["Tratado de París (Meaux-París): Raimundo VII cede la mayor parte de sus feudos a la corona de Francia", "ef1cb151"], "d": ["Por el tratado de París de 1229, el rey de Francia privó a la dinastía de Tolosa de la mayor parte de sus feudos; el condado pasaría en 1271 a la corona de Francia a través de la hija de Raimundo, Juana, y de su esposo Alfonso (hermano de Luis IX).", "7186cd3b"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1266-07-02:0":{"b": ["El rey de Noruega cede a Escocia la isla de Man y las Hébridas por 4000 marcos", "e027acbe"], "d": ["Alejandro III envió en 1261 una embajada a Noruega para la cesión de las islas y, al no obtener resultado, declaró la guerra; en 1263 la flota noruega fue destruida en Largs. Magnus, rey de Man, tuvo que abandonar todas las islas salvo Man. En 1266 el rey de Noruega cedió las islas (incluida Man) a Escocia por 4000 marcos; el dominio escocés se afianzó en Man solo en 1275, con la derrota de los manxeses en Ronaldsway.", "fdf0afa6"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1266-07-02:1":{"b": ["El rey de Noruega cede a Escocia las Hébridas y Man por 4000 marcos: Peel (Man)", "92b7f459"], "d": ["La derrota de Largs en 1263 hundió la pretensión noruega sobre las Hébridas; en 1266 el rey de Noruega cedió las islas (incluida Man) a Escocia por 4000 marcos.", "11675aa6"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1266-07-02:2":{"b": ["El rey de Noruega cede a Escocia las Hébridas por 4000 marcos: Iona (Hébridas)", "215cac00"], "d": ["Con la derrota que Alejandro III infligió a la flota noruega en Largs (1263), el dominio noruego sobre las Hébridas quedó quebrantado; en 1266 el rey de Noruega cedió las islas a Escocia por 4000 marcos.", "81cc8cf0"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1268-10-29:0":{"b": ["Conradino es ejecutado en Nápoles: se extingue la línea masculina de los Hohenstaufen", "55645d01"], "d": ["Conradino, último representante de la dinastía Hohenstaufen, tras ser derrotado por Carlos, duque de Anjou, en Tagliacozzo (23 de agosto de 1268), fue juzgado en Nápoles como traidor y ejecutado el 29 de octubre junto con su amigo Federico de Baden (duque titular de Austria). La línea masculina de los Hohenstaufen se extinguió.", "d81af0d1"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1271-01-01:0":{"b": ["Mueren Alfonso de Poitiers y su esposa Juana: la herencia del condado de Tolosa pasa a la corona de Francia", "eabc3640"], "d": ["A la muerte de Raimundo VII en 1249, la herencia pasó a su hija Juana; Juana estaba casada con Alfonso, hermano de Luis IX. Con la muerte de ambos en 1271, la vasta herencia de los condes de Tolosa pasó a la corona de Francia.", "ee58c39e"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1276-11-21:0":{"b": ["Paz de Viena: el rey de Bohemia Otakar II renuncia a Austria, Estiria, Carintia y Carniola", "db5c2bc4"], "d": ["Rodolfo de Habsburgo, tras ser elegido rey (1273), puso a Otakar bajo el bando imperial y declaró la guerra en junio de 1276; Rodolfo, que separó de Otakar al duque Enrique de la Baja Baviera, obligó al rey de Bohemia en noviembre de 1276 a ceder las cuatro provincias. Otakar fue reinvestido solo de Bohemia y Moravia, y su hijo Wenceslao fue prometido a la hija de Rodolfo; Rodolfo entró triunfalmente en Viena.", "d79ed14c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0569-09-04:0":{"b": ["Alboíno entró en Milán: el norte de Italia salió de manos de Bizancio", "b6be0ed6"], "d": ["Alboíno entró en Milán el 4 de septiembre de 569; el obispo Honorato huyó a Génova. Pavía cayó tras un largo asedio y el valle del Po pasó en gran parte a manos de los longobardos; Bizancio conservó solo algunas ciudades costeras y fortificadas.", "c0d39443"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0629-01-01:0":{"b": ["Los jázaros tomaron Tiflis", "d0847d32"], "d": ["Los jázaros, vinculados entonces a los Göktürk occidentales, cruzaron el paso de Derbent y realizaron incursiones en Georgia y Azerbaiyán; en 629 fue tomada Tiflis y algunos grupos armenios fueron sometidos. La capital es Belenyer.", "5027db3b"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0640-09-19:0":{"b": ["Hou Junji tomó Gaochang; los Tang fundaron Xizhou en su territorio", "1a8726a7"], "d": ["Hou Junji, comandante en jefe de la ruta de Jiaohe, se apoderó de Gaochang (Turfán) y los Tang fundaron allí la prefectura de Xizhou; el rey de Gaochang, Qu Zhisheng, fue llevado cautivo ante Taizong en el mes 12 y el ejército regresó a China.", "76b4f5c5"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0689-01-01:0":{"b": ["Malayu (Jambi) se incorporó a Srivijaya (entre 689 y 692, según el testimonio de Yijing)", "da0ffb9b"], "d": ["El peregrino chino Yijing informa de que Malayu (región de Jambi), por donde había pasado en 671, fue absorbido entre 689 y 692 por Shih-li-fo-shih (Srivijaya) (Coedès).", "a25038f0"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0708-01-01:0":{"b": ["Tánger fue tomada (Musa ibn Nusayr)", "0b579ded"], "d": ["Tánger fue tomada en 89 (708); en la primavera de 711 el gobernador de Tánger, Tariq ibn Ziyad, partió a la expedición de Hispania.", "a6fd7e17"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0708-11-20:0":{"b": ["Qutayba ibn Muslim recibió la rendición de Bujará", "38427fbf"], "d": ["Tras dos expediciones fallidas, Qutayba marchó sobre Bujará; después de un duro asedio recibió la rendición de la ciudad con las condiciones de ayuda militar, impuestos y colocación de una guarnición musulmana en la fortaleza (90/708-709); esto fue un punto de inflexión para las conquistas de Transoxiana.", "6b255806"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0714-01-01:0":{"b": ["Maslama ibn Abd al-Malik tomó el paso de Derbent", "839bbcf7"], "d": ["Los fuertes enfrentamientos con los jázaros tuvieron lugar en tiempos de al-Walid I; Maslama conquistó en 708 algunas ciudades y fortalezas, tomó en 714 el paso de Derbent y, cuando abandonó la región en 717 para el asedio de Constantinopla, los jázaros pasaron al contraataque.", "358cd23d"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0747-10-11:0":{"b": ["El jariyí Abu Hamza tomó Medina", "36cae3e0"], "d": ["El líder jariyí Abu Hamza al-Shari tomó Medina en Safar 130 (octubre de 747), después de haber puesto La Meca bajo su control.", "b0263b26"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0748-01-15:0":{"b": ["Nasr ibn Sayyar cedió Merv, el centro de Jorasán, a los rebeldes abasíes", "bc7bee2d"], "d": ["El gobernador omeya de Jorasán, Nasr, se vio obligado a abandonar Merv el 9 de Yumada al-ula de 130 (15 de enero de 748) y Nishapur en junio; antes de que terminara 749 los ejércitos abasíes controlaban todo Jorasán.", "dd216140"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0751-01-01:0":{"b": ["Los longobardos tomaron Rávena: terminó el Exarcado bizantino", "f5a42f8f"], "d": ["El rey longobardo Astolfo se apoderó de Rávena en 750-751; así cayó el único gran centro de Bizancio al norte de los Apeninos, y solo Venecia y una parte de Istria permanecieron vinculadas al Imperio.", "6debbee9"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0756-01-01:0":{"b": ["Pipino donó el Exarcado de Rávena al papado", "345e02a7"], "d": ["El rey franco Pipino derrotó a Astolfo y entregó al papado el Exarcado de Rávena y la Pentápolis; así Rávena, tomada a los longobardos, se incorporó al núcleo de los Estados Pontificios. Bizancio no pudo oponerse a esta donación.", "285518a8"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0757-12-03:0":{"b": ["El ejército Tang entró en Luoyang (757): la Capital Oriental fue recuperada de los rebeldes", "9d80b237"], "d": ["El comandante rebelde An Qingxu y sus partidarios, derrotados en el paraje de Xindian, en Shaanxi, huyeron a Hebei; el príncipe Guangping entró en Luoyang y formó su ejército al sur del Puente de Tianjin; más de 300 falsos funcionarios, como Chen Xilie y Zhang Ji, esperaron su castigo vestidos de blanco.", "6194d763"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0761-08-07:0":{"b": ["El comandante abasí Muhammad ibn al-Ashath tomó Kairuán", "40b80c87"], "d": ["Tras el nombramiento de Abderramán ibn Rustam como gobernador allí, la ciudad fue tomada por Muhammad ibn al-Ashath al-Juzai, a quien el califa al-Mansur había nombrado para el gobierno de Ifriquiya y el Magreb (Yumada al-ula de 144).", "b5951323"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0764-01-01:0":{"b": ["El ejército jázaro tomó Tiflis", "90eb05a6"], "d": ["Cuando la princesa jázara con quien se había casado el gobernador abasí Yazid ibn Usayd murió al dar a luz, el jagán envió un ejército al mando de As-Tarján; en 764 Tiflis fue tomada.", "0f1e9c4c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0774-01-01:0":{"b": ["Pavía se rinde; Desiderio es hecho prisionero; Carlomagno toma el título de 'rey de los longobardos' (termina el Reino Longobardo)", "2de54abb"], "d": ["Carlomagno, por la llamada del papa Adriano I, cruzó los Alpes en 773 y entró en el Reino Lombardo; en junio de 774 Pavía se rindió y el rey Desiderio fue enviado a un monasterio. Carlos tomó los títulos de 'rey de los longobardos' y de 'patricio de los romanos'.", "4dbdb9e5"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0775-01-01:0":{"b": ["Estela de Ligor (Nakhon Si Thammarat): el rey de Srivijaya se estableció en Ligor, en la península malaya, y erigió templos budistas (775)", "62e97b39"], "d": ["La estela de Wat Sema Muang muestra que el reino de Sumatra puso pie en 775 en Ligor, en la península malaya, y que el rey de Srivijaya (probablemente Dharmasetu) hizo construir un complejo de templos budistas; el texto de la segunda cara se refiere al linaje Sailendra.", "85396e40"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0809-01-01:0":{"b": ["El jan Krum tomó Sofía (Serdica)", "e24c951e"], "d": ["El jan búlgaro Krum, tras un largo asedio, se apoderó de Sredets (Sofía) e incorporó la ciudad al Estado búlgaro; el ejército búlgaro llegaría hasta Constantinopla en 813.", "468a62fd"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0813-01-01:0":{"b": ["El jan Krum tomó Dimotika (Didimoteicon)", "d4e6581d"], "d": ["Didimoteicon (Dimotika), de doble muralla, fue tomada en 813 por el jan búlgaro Krum.", "39bc9529"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0813-01-01:1":{"b": ["El jan Krum tomó Adrianópolis", "ab7bbb89"], "d": ["El jan búlgaro Krum se apoderó de Adrianópolis en 813 y su ejército llegó ante Constantinopla.", "fa54d545"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0827-04-02:0":{"b": ["La flota aglabí-Eufemio conquistó Mazara (Mazara del Vallo): comenzó la conquista de Sicilia", "a2676b9a"], "d": ["Cuando el comandante naval bizantino Eufemio se rebeló contra el gobernador Constantino Souda y pidió ayuda al emir aglabí Ziyadat Allah, llegó una flota musulmana de 10.000 hombres y más de setenta naves al mando de Asad ibn al-Furat, se unió a Eufemio y conquistó Mazara en 212 (827). La conquista de la isla duraría 75 años y se completaría en 902.", "cc8ea594"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0831-01-01:0":{"b": ["Bajo Malamir, Filibe se incorporó al Estado búlgaro", "f6c49ed3"], "d": ["El jan Malamir (831-836) incorporó Filibe (Filipópolis) a sus territorios; tras ello el jan Presian tomó la mayor parte de Macedonia.", "f8bd8891"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0831-02-18:0":{"b": ["Palermo se rindió a los musulmanes aglabíes", "6adfd1ac"], "d": ["Tras la caída de Mazara, las fuerzas musulmanas sitiaron Palermo; la ciudad se rindió en 216 (831). En 840 serían tomadas también Platani, Caltabellotta y Corleone.", "8693fb4d"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0831-09-12:0":{"b": ["Palermo se rindió a los musulmanes.", "4a74d5bb"], "d": ["Palermo se rindió a los musulmanes.", "4a74d5bb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0843-01-01:0":{"b": ["Mesina fue conquistada; el estrecho de Mesina, entre Sicilia e Italia, pasó al control de los musulmanes", "3c8d221c"], "d": ["Después de que en 840 fueran tomadas Platani, Caltabellotta y Corleone y en 842 toda la región de Mazara, al año siguiente (843) fue conquistada Mesina, en el noreste de la isla, y el estratégico estrecho quedó bajo control.", "87fda636"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0843-01-01:1":{"b": ["Mesina se rindió.", "3702c5ff"], "d": ["Mesina se rindió.", "3702c5ff"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0868-01-01:0":{"b": ["Oporto fue repoblada bajo Alfonso III.", "3338d015"], "d": ["Oporto fue repoblada bajo Alfonso III.", "3338d015"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0869-01-01:0":{"b": ["Malta fue conquistada.", "4edaaaa6"], "d": ["Malta fue conquistada.", "4edaaaa6"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0878-01-01:0":{"b": ["Batalla de Edington (Ethandun) y paz de Wedmore: Alfredo derrota a los daneses (Guthrum)", "bb82711f"], "d": ["Tras el súbito ataque de los daneses a Chippenham en enero de 878, Alfredo se ocultó con unos pocos hombres; los ejércitos se encontraron en Edington, en Wiltshire. Tras la paz de Wedmore (878) los daneses se retiraron de Wessex; la mitad nororiental, incluida Londres, permaneció en manos de los daneses, pero 'la marea había cambiado'.", "4f02f617"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0878-05-21:0":{"b": ["Los árabes tomaron Siracusa", "0ad38c19"], "d": ["Los aglabíes, tras un largo asedio, tomaron el 21 de mayo de 878 Siracusa, el principal centro bizantino de Sicilia; la isla comenzó a salir de hecho de manos de Bizancio.", "3c2d97da"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0886-01-01:0":{"b": ["Alfredo toma Londres a los daneses; la paz entre Alfredo y Guthrum modifica las fronteras a favor de Alfredo", "32d8daf9"], "d": ["Alfredo, al término de las medidas adoptadas contra los daneses rebeldes, tomó Londres en 885 o 886; entre Alfredo y Guthrum se hizo una paz que modificó a favor de Alfredo los límites de Wedmore.", "01209a4c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0893-01-01:0":{"b": ["Zamora fue repoblada bajo Alfonso III.", "78edf65c"], "d": ["Zamora fue repoblada bajo Alfonso III.", "78edf65c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0893-03-23:0":{"b": ["El emir samánida Ismail ibn Ahmad tomó Talas (Taraz); los samánidas alcanzaron en el este sus fronteras más amplias", "a25f7598"], "d": ["Ismail ibn Ahmad, para proteger Transoxiana de las incursiones de los turcos no musulmanes, organizó una expedición hasta Taraz (Talas) y se apoderó de la ciudad; la mayoría de los emires y dihqanes turcos de allí se hicieron musulmanes, y Oguljak, que perdió Talas, el centro de los karajánidas orientales, trasladó la capital a Kashgar.", "8bf208a3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0902-08-01:0":{"b": ["Taormina cayó: se perdió la última fortaleza de Bizancio en Sicilia", "525abc8c"], "d": ["Con la toma de Taormina por los árabes terminó el dominio de Bizancio en la isla de Sicilia; solo quedaron los territorios del sur de Italia.", "9e2eb491"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0903-01-01:0":{"b": ["Los cármatas tomaron Hama, Homs, Maarrat al-Numan y Baalbek; las tropas tuluníes enviadas fueron derrotadas (290/903).", "291ecf32"], "d": ["Los cármatas tomaron Hama, Homs, Maarrat al-Numan y Baalbek; las tropas tuluníes enviadas fueron derrotadas (290/903).", "291ecf32"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0911-01-01:0":{"b": ["El ejército uigur de Kan-chou tomó Tun-huang", "36ec7038"], "d": ["Tun-huang, centro del reino autónomo fundado en 905 por el comandante chino, fue tomada en 911 por el ejército uigur al mando de Tegin; la victoria aumentó el prestigio de los uigures de Kan-chou ante los chinos.", "3bffe840"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0914-01-01:0":{"b": ["Simeón tomó Adrianópolis", "fe0efa60"], "d": ["El zar búlgaro Simeón se apoderó de Adrianópolis en 914; la ciudad fue durante mucho tiempo escenario de las guerras bizantino-búlgaras.", "0d8b77bc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0923-11-19:0":{"b": ["Li Cunxu entró en Kaifeng: cayeron los Liang Posteriores", "aebaab18"], "d": ["Li Siyuan, vanguardia de Li Cunxu, que había desbaratado al ejército Liang en Zhongdu, llegó al amanecer a la Puerta de Fengqiu de Kaifeng; Wang Zan, gobernador Liang de Kaifeng, entregó la ciudad y Li Cunxu entró en ella por la Puerta de Daliang.", "4ee60f2e"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0934-01-01:0":{"b": ["Bizancio tomó Malatya", "fd0898d0"], "d": ["El ejército bizantino al mando del doméstico de Oriente Juan Curcuas avanzó hasta el Éufrates y se apoderó de Malatya en 934; en 943 fueron tomadas también Mayyafariqin, Amida, Dara y Nisibis.", "46c833cc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0943-01-01:0":{"b": ["Marzubán asume el control de Azerbaiyán, Arrán y Armenia (330-331 / 942-943).", "fc600309"], "d": ["Marzubán asume el control de Azerbaiyán, Arrán y Armenia (330-331 / 942-943).", "fc600309"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0943-01-01:1":{"b": ["Vushmgir pierde Rey a manos del emir buyí Rukn al-Dawla (331/943).", "1e7169f4"], "d": ["Vushmgir pierde Rey a manos del emir buyí Rukn al-Dawla (331/943).", "1e7169f4"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0943-09-04:0":{"b": ["El comandante turco Tuzun expulsó a los hamdánidas de Mosul (332/943).", "04d1fecc"], "d": ["El comandante turco Tuzun expulsó a los hamdánidas de Mosul (332/943).", "04d1fecc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0947-01-01:0":{"b": ["Tras la segunda derrota frente a los ijshidíes (primavera de 335/947) Alepo pasó a los ijshidíes; en 336, por un acuerdo, Sayf al-Dawla se estableció definitivamente en Alepo.", "f5572476"], "d": ["Tras la segunda derrota frente a los ijshidíes (primavera de 335/947) Alepo pasó a los ijshidíes; en 336, por un acuerdo, Sayf al-Dawla se estableció definitivamente en Alepo.", "f5572476"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0960-01-01:0":{"b": ["Los fatimíes toman Fez y Sijilmasa.", "48efa30c"], "d": ["Los fatimíes toman Fez y Sijilmasa.", "48efa30c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0961-03-06:0":{"b": ["Candía cayó: Nicéforo Focas reconquistó Creta", "aeefb280"], "d": ["Las fuerzas bizantinas al mando de Nicéforo Focas tomaron Candía el 6 de marzo de 961 tras un asedio de un año; terminó el Emirato de Creta, que había durado unos 130 años. Una parte de la población musulmana de la isla abandonó la isla y otra parte fue obligada a convertirse.", "ec04c12b"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0962-01-01:0":{"b": ["Ahmad ibn al-Hasan al-Kalbi, tras un asedio de siete meses, tomó la fortaleza bizantina de Taormina y la llamó Muizziyya", "37e8ae59"], "d": ["Ahmad ibn al-Hasan al-Kalbi, tras un asedio de siete meses, toma la fortaleza bizantina de Taormina y la llama Muizziyya.", "f8fcc7b1"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0965-01-01:0":{"b": ["Nicéforo Focas ocupó Mopsuestia y Tarso (354/965).", "045053b4"], "d": ["Nicéforo Focas ocupó Mopsuestia y Tarso (354/965).", "045053b4"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0965-08-16:0":{"b": ["Tarso se rindió a Bizancio: Cilicia pasó bajo dominio bizantino", "b05e9bd3"], "d": ["Mopsuestia se rindió en julio de 965 y Tarso un mes después, el 16 de agosto de 965, en condiciones humanitarias, y volvió a ser una ciudad cristiana. Así la región de Cilicia se incorporó a Bizancio.", "faeb461f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0969-10-28:0":{"b": ["Antioquía pasó a manos de Bizancio", "ad0a5da3"], "d": ["Tras tomar los ejércitos bizantinos muchas fortalezas y ciudades en el norte de Siria, Miguel Burcio y Pedro Focas, llegados desde Cilicia, se apoderaron de Antioquía el 28 de octubre de 969. La ciudad fue durante unos 115 años la principal base de Bizancio en Siria.", "38b840e3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0971-04-13:0":{"b": ["Tzimiscés tomó al asalto Preslav la Grande: Bulgaria oriental se incorporó a Bizancio", "07c84840"], "d": ["Juan Tzimiscés entró en la llanura de Preslav el 12 de abril de 971; la tarde del 13 de abril cayó la capital búlgara, defendida por los hombres de Sviatoslav. El zar Boris fue hecho prisionero y la administración bizantina se extendió a Tracia y a Bulgaria oriental.", "ae050b34"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0979-01-01:0":{"b": ["Azerbaiyán pasó a manos de los rawwadíes; los musafiríes se retiraron a Tarum (979 o 980)", "b5b0e767"], "d": ["Azerbaiyán pasó a manos de los rawwadíes; los musafiríes se retiraron a Tarum (979 o 980)", "b5b0e767"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0983-06-15:0":{"b": ["Los cármatas atacaron Basora y la sometieron a tributo (373).", "d667e02e"], "d": ["Los cármatas atacaron Basora y la sometieron a tributo (373).", "d667e02e"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0992-01-01:0":{"b": ["Harún Bugra Jan tomó Samarcanda; los karajánidas entraron por primera vez en Transoxiana", "31e0d0ae"], "d": ["Harún Bugra Jan, llamado por un acuerdo secreto por Abu Ali al-Simyuri y Faiq al-Jassa, se apoderó de Samarcanda a comienzos de 992 y después marchó sobre Bujará; murió en Koçkarbaşı cuando regresaba a Kashgar.", "8377be9f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0992-05-07:0":{"b": ["El karajánida Harún Bugra Jan se apoderó de Bujará", "36955b70"], "d": ["Harún Bugra Jan, que se había concertado en secreto con Abu Ali al-Simyuri y Faiq al-Jassa, se apoderó de Bujará, la capital samánida, en Rabi al-awwal de 382 (mayo de 992); poco después enfermó y murió.", "cdd97d30"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0992-08-18:0":{"b": ["Nuh II recuperó el dominio de Bujará con la ayuda de los turcomanos selyúcidas", "8a88b4d3"], "d": ["El 15 de Yumada al-ajira de 382 (18 de agosto de 992), tras la muerte de Harún Bugra Jan, Nuh II volvió a dominar Bujará con la ayuda de los turcomanos selyúcidas.", "00c3767a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0993-01-01:0":{"b": ["Ziri ibn Atiyya derrota al gobernador fatimí Yaddu ibn Yala y recupera Fez; comienza a fundar Uchda.", "69e1def0"], "d": ["Ziri ibn Atiyya derrota al gobernador fatimí Yaddu ibn Yala y recupera Fez; comienza a fundar Uchda.", "69e1def0"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0997-01-01:0":{"b": ["Muere Fajr al-Dawla; el sallarí Ibrahim ibn Marzubán toma Zanyán, Abhar, Suhraward y Tarum (387/997).", "f7dde64a"], "d": ["Muere Fajr al-Dawla; el sallarí Ibrahim ibn Marzubán toma Zanyán, Abhar, Suhraward y Tarum (387/997).", "f7dde64a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0998-03-03:0":{"b": ["Mahmud derrotó a su hermano Ismail y subió al trono gaznaví", "b2acf57c"], "d": ["Mahmud, que se hallaba en Nishapur, no reconoció el testamento de su padre y se puso en movimiento; en Rabi al-awwal de 388 (marzo de 998) se encontraron los ejércitos de los dos hermanos, y Mahmud derrotó a Ismail y subió al trono gaznaví.", "3c2c1e3d"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0999-10-14:0":{"b": ["El karajánida Ilig Jan Nasr entró en Bujará; la familia samánida fue desterrada a Özkent y el Estado terminó de hecho", "ec519748"], "d": ["En Dhu l-qada de 389 (octubre de 999) los karajánidas ocuparon Bujará; Abd al-Malik fue hecho prisionero y la familia samánida fue llevada a Özkent y encarcelada. Ilig Jan Nasr nombró en la región a sus propios gobernadores.", "ef9a0a65"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1000-01-01:0":{"b": ["El dogo Pedro II Orseolo sometió las ciudades de Dalmacia y se convirtió en 'Duque de Dalmacia'", "fa3dde09"], "d": ["Orseolo, que partió con una gran flota por invitación de los dálmatas, derrotó a croatas y narentanos, limpió el Adriático de piratería y recibió de las ciudades de Dalmacia los impuestos y el juramento de fidelidad; tomó el título de 'Duque de Dalmacia'. Zara prestó homenaje al dogo en 1000.", "d2c778fc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1000-01-01:1":{"b": ["Ragusa (Dubrovnik) y las ciudades del sur de Dalmacia prestaron homenaje a Orseolo", "6121e2e9"], "d": ["En la expedición de Orseolo a Dalmacia, Ragusa, la más meridional de las ciudades dálmatas, recibió al ejército del dogo en el islote de San Massimo con sus embajadores y su arzobispo y presentó su sumisión a Venecia.", "638f8cad"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1013-01-01:0":{"b": ["Mahmud tomó Lahore a los hindushahíes; Lahore se convirtió en la ciudad predilecta de los gaznavíes", "37ab3445"], "d": ["Lahore, que desde 991 estaba en manos de los hindushahíes, pasó en 1013-1014 a manos de Mahmud de Gazni; Mahmud fortificó la fortaleza de Lahore y estableció una guarnición con soldados turcos y tayikos traídos de Jorasán. Cuando los gaznavíes perdieron su independencia (después de 1157), Lahore fue el centro de la rama que conservó su existencia en el este.", "90b6f385"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1015-01-01:0":{"b": ["El rey Roberto II, tras una guerra de trece años, incorpora el Ducado de Borgoña a la corona de Francia", "257ea2c6"], "d": ["Tras la muerte del duque Enrique en 1002 estalló la guerra por el Ducado de Borgoña; el rey de Francia Roberto II, pese a la resistencia del conde de Borgoña Otón Guillermo, anexionó en 1015 el ducado al reino al cabo de una guerra de trece años y se lo entregó a su hijo Enrique (más tarde Enrique I).", "9b353b9c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-01-01:0":{"b": ["Basilio II entró en Ocrida: la capital de Bulgaria occidental pasó a manos de Bizancio", "05fe0972"], "d": ["La dinastía búlgara, que resistió cuatro años tras la muerte de Samuel, se rindió a Basilio II a comienzos de 1018 a las puertas de Ocrida. El arzobispado de Ocrida siguió existiendo bajo la administración bizantina como centro del cristianismo eslavo.", "b6ac5adb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-01-01:1":{"b": ["El rey de Polonia Boleslao Chrobry tomó Kiev con apoyo alemán y pecheneg", "3e44ca65"], "d": ["En agosto de 1018 Boleslao se apoderó de Kiev con fuerzas alemanas y pechenegas; puso en el trono a su yerno Sviatopolk, tras derrotar a Yaroslav en el río Bug. Yaroslav solo pudo recuperar Kiev en 1019.", "02428d3c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-05-20:0":{"b": ["Mahmud dominó la ciudad de Mathura (Muttra)", "78547f01"], "d": ["Durante la expedición a Kannauj, el ejército gaznaví dominó la ciudad de Mathura, situada a mitad de camino entre Delhi y Agra (409/1018).", "bb198817"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-12-20:0":{"b": ["Mahmud conquistó Kannauj (Kanyakubja)", "258b5624"], "d": ["Mahmud partió de Gazni el 13 de Yumada al-ula de 409 (27 de septiembre de 1018) a su duodécima expedición a la India; tras la fortaleza de Sarsawa, la sumisión del rajá de Baran y Mathura, el objetivo principal, Kannauj, fue conquistado el 8 de Shaban de 409 (20 de diciembre de 1018).", "5952deed"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1028-01-01:0":{"b": ["Canuto el Grande fue proclamado rey en Noruega; Olaf Haraldsson huyó", "89688331"], "d": ["Canuto llegó a Noruega en 1028 con una flota de cincuenta naves y fue aclamado rey de Noruega en el Øretinget; el rey Olaf II Haraldsson huyó primero a Suecia y luego a Rus (Gardarike).", "35460867"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1030-01-01:0":{"b": ["Se fundó el Condado de Aversa: Rainulfo Drengot se convirtió en conde normando", "ec99b57a"], "d": ["En 1030, cuando el duque de Nápoles Sergio estableció a Rainulfo en el castillo de Aversa, los normandos obtuvieron por primera vez una base permanente y comenzó la conquista organizada del sur de Italia.", "8d2a9071"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1033-01-01:0":{"b": ["Los Banu Ifran toman la ciudad de Fez a Hamama ibn al-Muizz.", "6cad34e9"], "d": ["Los Banu Ifran toman la ciudad de Fez a Hamama ibn al-Muizz.", "6cad34e9"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1038-01-01:0":{"b": ["Guaimario tomó Capua a su tío y sometió también a Amalfi, Sorrento y Gaeta", "3b8444df"], "d": ["Guaimario toma Capua a su tío Pandolfo IV; después somete también a Amalfi, Sorrento y Gaeta y obtiene el reconocimiento del emperador Conrado II.", "9e207542"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1038-02-09:0":{"b": ["Ala al-Dawla toma Rey y luego la abandona (Yumada al-ula de 429 / febrero de 1038).", "8cd709ec"], "d": ["Ala al-Dawla toma Rey y luego la abandona (Yumada al-ula de 429 / febrero de 1038).", "8cd709ec"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1039-01-01:0":{"b": ["El príncipe de Salerno Guaimario se apodera del ducado de Amalfi con el apoyo de mercenarios normandos.", "39b73a57"], "d": ["El príncipe de Salerno Guaimario se apodera del ducado de Amalfi con el apoyo de mercenarios normandos.", "39b73a57"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1047-01-01:0":{"b": ["La fortaleza de Kinkever se rinde; Hamadán pasa al control directo de los selyúcidas (439/1047).", "2bdca680"], "d": ["La fortaleza de Kinkever se rinde; Hamadán pasa al control directo de los selyúcidas (439/1047).", "2bdca680"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1048-06-16:0":{"b": ["Kavurd Bey tomó Bardsir, el centro de Kirmán, y puso fin al dominio buyí en Kirmán", "131afa64"], "d": ["Cuando Kavurd Bey, hijo de Çağrı Bey, entró en el norte de Kirmán con 5-6000 jinetes y sitió el centro, Bardsir, Bahram ibn Laskarsitán, que gobernaba en nombre de los buyíes, entregó la ciudad (440/1048); se echaron los cimientos de los selyúcidas de Kirmán. Ese mismo año murió Abu Kalijar.", "8817f5aa"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1050-01-01:0":{"b": ["Kavurd Bey tomó a la tribu de los kufs la parte sur de Kirmán, Garmsir, y se apoderó de todo Kirmán; el emir de Ormuz se hizo vasallo", "87e442c0"], "d": ["Garmsir, el sur de Kirmán, estaba en manos de la tribu bandolera de los kufs; Kavurd Bey los reprimió en las montañas del este, destruyó a la mayoría y se apoderó también del sur de Kirmán (442/1050); el emir de la isla de Ormuz, Badr Isa, se hizo vasallo de los selyúcidas, y Kavurd conquistó también Omán.", "7d6e7ded"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1051-05-15:0":{"b": ["Faramurz, tras un asedio de un año, entregó Isfahán a los selyúcidas; terminó el dominio sobre el Yibal, Yazd quedó como iqta", "37716461"], "d": ["Faramurz, tras un asedio de un año, entregó Isfahán a los selyúcidas; terminó el dominio sobre el Yibal, Yazd quedó como iqta", "37716461"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1051-05-15:1":{"b": ["Tugrul Bey incorporó Isfahán a su país", "93d9438c"], "d": ["Tugrul Bey incorporó Isfahán a su país en 443 (1051).", "573195e7"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1057-03-10:0":{"b": ["El emir zirí al-Muizz abandonó Kairuán y se fue a Mahdia; Kairuán cayó en manos de los hilalíes", "becee655"], "d": ["Por el asedio de los Banu Hilal, al-Muizz ibn Badis abandonó Kairuán en el año 449 (1057) y se fue a Mahdia, de la que su hijo Tamim era gobernador; la indefensa Kairuán fue saqueada e incendiada por los beduinos.", "7b6732bb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1061-01-01:0":{"b": ["El conde Roger tomó Mesina (1061)", "28b31d9a"], "d": ["Roger desembarcó en 1061 cerca de Mesina y tomó la ciudad con relativa facilidad; así comenzó la conquista normanda de Sicilia. TDV da este año como el de la toma de Mesina.", "d06afdbf"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1067-01-01:0":{"b": ["Alp Arslan conquistó Kars, que pertenecía a Bizancio; el rey georgiano se hizo vasallo de los selyúcidas", "25994288"], "d": ["Alp Arslan reapareció en 1067 en las fronteras de Bizancio y de Georgia; fue conquistada Kars, que pertenecía a Bizancio, y el rey georgiano se hizo vasallo de los selyúcidas.", "5395feca"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1067-01-01:1":{"b": ["Alp Arslan tomó Cesarea", "c40df514"], "d": ["En tiempos del sultán selyúcida Alp Arslan los turcos tomaron Ani en 1065 y Cesarea en 1067; Bizancio perdió las puertas de Capadocia.", "fbeb3963"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1071-01-01:0":{"b": ["Catania pasó a manos de los normandos (1071)", "21617f1b"], "d": ["Mientras continuaba el asedio de Bari, en 1071 Catania pasó a manos de los normandos por una traición en la ciudad; pero la ciudad se perdió después y fue tomada definitivamente unos diez años más tarde.", "3d49a9a2"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1072-01-01:0":{"b": ["Mazara pasó a manos de los normandos (1072)", "e7cb9667"], "d": ["En 1072, año en que fue tomada Palermo, fue conquistada también Mazara; en los años siguientes se construyó allí una fortaleza y se resistió a un ataque procedente del norte de África (1075).", "95450106"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1072-12-15:0":{"b": ["Nasr II tomó Termez a la muerte de Alp Arslan, luego marchó sobre Balj y también la tomó", "7747ccc9"], "d": ["A la muerte de Alp Arslan en su campaña de Transoxiana, el karajánida occidental Shams al-Mulk Nasr II tomó Termez en Rabi al-ajir de 465 (diciembre de 1072) y luego marchó sobre Balj y la tomó también; la lucha selyúcida-karajánida continuó en tiempos de Malik Shah.", "1ba5253a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1073-01-01:0":{"b": ["Amalfi recurre a Roberto Guiscardo frente a la presión de Salerno; los normandos ocupan la ciudad y la independencia...", "3d375631"], "d": ["Amalfi recurre a Roberto Guiscardo frente a la presión de Salerno; los normandos ocupan la ciudad y la independencia termina.", "be93237a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1075-08-16:0":{"b": ["Savtegin, emir de Malik Shah, tomó Arrán; terminó la rama de Ganja de los shaddadíes", "e031fc26"], "d": ["En tiempos del shaddadí Fadl III, Savtegin, uno de los emires del sultán Malik Shah, tomó Arrán (468/1075-76); la región entró en la administración selyúcida y terminó la rama de Ganja de los shaddadíes.", "b39c17bd"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1076-01-01:0":{"b": ["Salerno cayó en poder de Roberto Guiscardo; terminó el Principado lombardo de Salerno", "c678238f"], "d": ["Tras una larga resistencia, Salerno se rindió a Roberto Guiscardo en diciembre de 1076; el príncipe Gisulfo II se retiró al exilio, a la corte papal. Guiscardo hizo de Salerno la capital de su propio ducado.", "705fecee"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1077-01-01:0":{"b": ["Roger tomó Trapani con su flota", "2b0b3d98"], "d": ["Roger, que había construido una flota, intensificó en 1077 la actividad bélica y tomó Trapani y después Castronovo.", "6e482ca5"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1077-07-25:0":{"b": ["Yusuf ibn Tashfin tomó Tánger", "aa4376c4"], "d": ["El emir almorávide Yusuf ibn Tashfin tomó Tánger, importante ciudad costera del Magreb extremo, en el año 470 (1077-78).", "94bf21ec"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1081-01-01:0":{"b": ["Roberto Guiscardo desembarcó en Valona y tomó Corfú", "d5e43c94"], "d": ["En 1081 Guiscardo marchó con su flota a Valona (Avlonya), tomó Corfú y en 1082 se apoderó de Dirraquio; la marcha sobre Constantinopla quedó interrumpida porque fue llamado a Roma en ayuda de Gregorio VII.", "f805ca31"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1082-01-01:0":{"b": ["Süleyman Shah I, fundador de los selyúcidas de Anatolia, conquistó Tarso", "93d6092f"], "d": ["Süleyman Shah I conquistó Tarso en 475/1082; la ciudad fue tomada por los cruzados en 490/1097 y después cambió de manos entre cruzados, bizantinos y los armenios de la región.", "912208e8"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1084-03-24:0":{"b": ["Roma se rinde a Enrique IV; el antipapa Clemente III (Guibert) es entronizado, Enrique recibe la corona imperial y Gregorio huye de Roma", "311cfeb4"], "d": ["Los romanos entregaron la ciudad a Enrique, que había descendido a Italia en 1081; Guibert, arzobispo de Rávena, fue proclamado papa con el nombre de Clemente III el 24 de marzo de 1084, y Enrique fue coronado emperador por el papa rival. Gregorio VII, abandonado por trece cardenales, tuvo que huir de Roma; confió en el apoyo de los normandos.", "996d4e46"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1084-05-10:0":{"b": ["Los almorávides dominaron Ceuta", "48f062fb"], "d": ["Yūsuf b. Tāshufīn tomó Ceuta bajo su dominio en el año 477 (1084); esto fue la puerta de acceso a al-Ándalus.", "4ba802e3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1085-01-01:0":{"b": ["El emir de Süleyman Şah, Buldacı, conquistó la región de Ceyhan (Elbistan)", "406d5385"], "d": ["La región de Ceyhan (Elbistan), objetivo de las incursiones de los gazis turcomanos, fue conquistada en 1085 por Buldacı, uno de los emires del sultán selyúcida de Anatolia Süleyman Şah.", "f1f8ec8c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1086-01-01:0":{"b": ["Siracusa cayó en manos de los normandos", "0d66d006"], "d": ["Tras la caída de Agrigento en julio de 1086, Siracusa pasó a los normandos en octubre de 1086; Castrogiovanni se rendiría en 1087 y Noto en 1091.", "b99596a6"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1086-07-11:0":{"b": ["Tutuş tomó Alepo tras sitiarla durante un tiempo.", "11f90dba"], "d": ["Tutuş tomó Alepo tras sitiarla durante un tiempo.", "11f90dba"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1088-03-27:0":{"b": ["Melikşah se apoderó de Bujará y Samarcanda, capturó al karajánida occidental Ahmed Jan y lo llevó a Isfahán", "ababb7d4"], "d": ["Tras la muerte del cadí supremo Ahmed b. Süleyman a manos de Ahmed Jan, Melikşah, a petición de auxilio del jurista chafiita Ebû Tâhir b. Alek, se apoderó de Bujará y Samarcanda en 481 (1088) y llegó a Özkent; capturó a Ahmed Jan y lo llevó a Isfahán. Ebû Tâhir el-Hârizmî fue nombrado lugarteniente en Samarcanda.", "b43535bd"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1089-01-01:0":{"b": ["El duque Ruggero reconquista Amalfi.", "18ff3563"], "d": ["El duque Ruggero reconquista Amalfi.", "18ff3563"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1090-01-01:0":{"b": ["La isla de Malta fue anexionada al condado normando", "181ee62e"], "d": ["Roger sometió también la isla de Malta a su dominio en 1090.", "88b62d2a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1090-03-06:0":{"b": ["Melikşah tomó Samarcanda por segunda vez y nombró gobernador al emir Atsız", "685e6aef"], "d": ["Ante la rebelión de Aynüddevle, comandante de los chigiles, y el paso de Yâkub Tegin a Samarcanda, Melikşah tomó Samarcanda por segunda vez a finales del año 483 (1090) y nombró gobernador al emir Atsız; después puso a Yâkub Tegin al frente de los karajánidas orientales y le encargó combatir a Tuğrul b. Yinal.", "f2c9b630"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1090-03-06:1":{"b": ["Los almorávides tomaron Granada", "65113a38"], "d": ["En su tercer paso a al-Ándalus (483/1090), Yûsuf b. Tâşfîn tomó Granada y regresó al norte de África; el emirato ziríe llegó a su fin.", "f032e02c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1091-02-23:0":{"b": ["Los almorávides tomaron Sevilla a los abadíes", "9ee64f2b"], "d": ["Sevilla pasó a manos de los almorávides en el año 484 (1091); el emirato abadí llegó a su fin.", "75adcb2f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1092-01-01:0":{"b": ["Çaka Bey, tras un asedio bizantino de tres meses, cedió Mitilene a Bizancio con la condición de que sus soldados salieran con vida", "4a8d9810"], "d": ["En la primavera de 1092 el emperador Alejo Comneno envió a Ioannes Dukas por tierra y a Dalassenos por mar para liberar Mitilene; aunque el asedio de tres meses no tuvo éxito, Çaka Bey comprendió que no podría resistir más y cedió Mitilene a Bizancio con la condición de que sus soldados abandonaran la isla sanos y salvos.", "f1e57c7a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1094-01-01:0":{"b": ["Rodrigo Díaz de Vivar (el Cid) tomó Valencia", "7e966419"], "d": ["El héroe épico castellano Rodrigo Díaz de Vivar tomó Valencia en 1094, hizo matar al gobernante, el cadí Ibn Chahhaf, y sometió a la población a tributo.", "27df4900"]}
});
